-- Free-limit account total: EVERY Scene the caller owns, placed or Unplaced.
-- Not the ordered manuscript total (placed Scenes only). Never collapse them.
CREATE OR REPLACE FUNCTION public.account_word_total(p_candidate_scene_id uuid DEFAULT NULL::uuid, p_candidate_word_count integer DEFAULT NULL::integer)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_total int;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  with existing_scenes as (
    select
      case
        when p_candidate_scene_id is not null and s.id = p_candidate_scene_id
        then p_candidate_word_count
        else s.word_count
      end as word_count
    from public.scenes s
    join public.manuscripts m on m.id = s.manuscript_id
    join public.projects pr on pr.id = m.project_id
    where pr.user_id = auth.uid()
  ),
  new_scene as (
    -- Synthetic row for a brand-new Scene not yet inserted anywhere.
    select p_candidate_word_count as word_count
    where p_candidate_scene_id is null
      and p_candidate_word_count is not null
  )
  select coalesce(sum(word_count), 0)
  into v_total
  from (
    select word_count from existing_scenes
    union all
    select word_count from new_scene
  ) all_words;

  return v_total;
end;
$function$;

CREATE OR REPLACE FUNCTION public.add_object_reference(p_source_type text, p_source_id uuid, p_target_type text, p_target_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_project_id uuid;
  v_reference public.object_references%rowtype;
begin
  if p_source_type is null or p_source_type not in ('entry', 'page', 'scene')
     or p_target_type is null or p_target_type not in ('entry', 'page', 'scene') then
    return jsonb_build_object('status', 'error', 'error', 'Unknown object type');
  end if;
  v_project_id := public.reference_object_project(p_source_type, p_source_id);
  if v_project_id is null or not exists (select 1 from public.projects p where p.id = v_project_id and p.user_id = auth.uid()) then
    return jsonb_build_object('status', 'error', 'error', 'Source not found');
  end if;
  perform public.lock_project_workspace(v_project_id);
  -- Another writer's object, or one of another Project, is simply not found.
  if public.reference_object_project(p_target_type, p_target_id) is distinct from v_project_id then
    return jsonb_build_object('status', 'error', 'error', 'Target not found');
  end if;
  if p_source_type = p_target_type and p_source_id = p_target_id then
    return jsonb_build_object('status', 'error', 'error', 'An object cannot reference itself');
  end if;

  select r.* into v_reference from public.object_references r
   where r.property_id is null and r.scene_property_id is null and r.origin = 'link'
     and r.source_type = p_source_type and coalesce(r.source_entry_id, r.source_document_id, r.source_scene_id) = p_source_id
     and r.target_type = p_target_type and coalesce(r.target_entry_id, r.target_document_id, r.target_scene_id) = p_target_id;
  if found then
    return jsonb_build_object('status', 'ok', 'reference', to_jsonb(v_reference));
  end if;
  if (select count(*) from public.object_references r
       where r.property_id is null and r.scene_property_id is null and r.origin = 'link' and r.source_type = p_source_type
         and coalesce(r.source_entry_id, r.source_document_id, r.source_scene_id) = p_source_id) >= 500 then
    return jsonb_build_object('status', 'error', 'error', 'Too many links');
  end if;

  insert into public.object_references
    (project_id, source_type, source_entry_id, source_document_id, source_scene_id,
     target_type, target_entry_id, target_document_id, target_scene_id, position)
  select v_project_id, p_source_type,
         case when p_source_type = 'entry' then p_source_id end,
         case when p_source_type = 'page' then p_source_id end,
         case when p_source_type = 'scene' then p_source_id end,
         p_target_type,
         case when p_target_type = 'entry' then p_target_id end,
         case when p_target_type = 'page' then p_target_id end,
         case when p_target_type = 'scene' then p_target_id end,
         coalesce(max(r.position), 0) + 1
    from public.object_references r
   where r.property_id is null and r.scene_property_id is null and r.origin = 'link' and r.source_type = p_source_type
     and coalesce(r.source_entry_id, r.source_document_id, r.source_scene_id) = p_source_id
  returning * into v_reference;

  return jsonb_build_object('status', 'ok', 'reference', to_jsonb(v_reference));
end;
$function$;

CREATE OR REPLACE FUNCTION public.bump_project_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  update public.projects
  set updated_at = now()
  where id = (
    select m.project_id
    from public.manuscripts m
    where m.id = new.manuscript_id
  );

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_object_reference()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_property public.workspace_collection_properties%rowtype;
  v_scene_property public.scene_property_definitions%rowtype;
begin
  if tg_op = 'UPDATE' then
    if (new.project_id, new.source_type, new.source_entry_id, new.source_document_id, new.source_scene_id,
        new.target_type, new.target_entry_id, new.target_document_id, new.target_scene_id, new.target_chapter_id,
        new.property_id, new.scene_property_id, new.origin)
       is distinct from
       (old.project_id, old.source_type, old.source_entry_id, old.source_document_id, old.source_scene_id,
        old.target_type, old.target_entry_id, old.target_document_id, old.target_scene_id, old.target_chapter_id,
        old.property_id, old.scene_property_id, old.origin) then
      raise exception 'A reference keeps its source, target and property for life' using errcode = 'check_violation';
    end if;
    new.id := old.id;
    new.created_at := old.created_at;
    return new;
  end if;

  if public.reference_object_project(new.source_type, coalesce(new.source_entry_id, new.source_document_id, new.source_scene_id))
       is distinct from new.project_id
     or public.reference_object_project(new.target_type,
          coalesce(new.target_entry_id, new.target_document_id, new.target_scene_id, new.target_chapter_id))
       is distinct from new.project_id then
    raise exception 'Both ends of a reference must be in its Project' using errcode = 'check_violation';
  end if;

  if new.property_id is not null then
    select pr.* into v_property
      from public.workspace_collection_properties pr
      join public.workspace_collection_entries e on e.collection_id = pr.collection_id
     where pr.id = new.property_id and e.id = new.source_entry_id and pr.type = 'relationship';
    if not found then
      raise exception 'Not a Relationship property of the Entry''s Collection' using errcode = 'check_violation';
    end if;
    if new.target_type <> v_property.relation_target
       or (v_property.relation_target = 'entry'
           and not exists (select 1 from public.workspace_collection_entries t
                            where t.id = new.target_entry_id and t.collection_id = v_property.relation_collection_id)) then
      raise exception 'The Relationship "%" cannot point to that', v_property.name using errcode = 'check_violation';
    end if;
    if not v_property.relation_many
       and exists (select 1 from public.object_references r
                    where r.property_id = new.property_id and r.source_entry_id = new.source_entry_id) then
      raise exception 'The Relationship "%" holds one value', v_property.name using errcode = 'check_violation';
    end if;
  end if;

  if new.scene_property_id is not null then
    select pr.* into v_scene_property
      from public.scene_property_definitions pr
      join public.scenes s on s.manuscript_id = pr.manuscript_id
     where pr.id = new.scene_property_id and s.id = new.source_scene_id and pr.type = 'relationship';
    if not found then
      raise exception 'Not a Relationship property of the Scene''s Manuscript' using errcode = 'check_violation';
    end if;
    if new.target_type <> v_scene_property.relation_target
       or (v_scene_property.relation_target = 'entry'
           and not exists (select 1 from public.workspace_collection_entries t
                            where t.id = new.target_entry_id and t.collection_id = v_scene_property.relation_collection_id)) then
      raise exception 'The Relationship "%" cannot point to that', v_scene_property.name using errcode = 'check_violation';
    end if;
    if not v_scene_property.relation_many
       and exists (select 1 from public.object_references r
                    where r.scene_property_id = new.scene_property_id and r.source_scene_id = new.source_scene_id) then
      raise exception 'The Relationship "%" holds one value', v_scene_property.name using errcode = 'check_violation';
    end if;
  end if;

  new.created_at := now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_scene_property_definition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not public.workspace_property_options_valid(new.options) then
    raise exception 'Invalid property options' using errcode = 'check_violation';
  end if;
  if new.relation_collection_id is not null
     and (tg_op = 'INSERT' or new.relation_collection_id is distinct from old.relation_collection_id)
     and not public.workspace_object_active('collection', new.relation_collection_id) then
    raise exception 'That collection is in Trash' using errcode = 'check_violation';
  end if;
  if tg_op = 'INSERT' then
    if not exists (select 1 from public.manuscripts m where m.id = new.manuscript_id and m.project_id = new.project_id) then
      raise exception 'A Scene property belongs to its Manuscript''s Project' using errcode = 'check_violation';
    end if;
    new.created_at := now();
    new.updated_at := now();
    return new;
  end if;
  if new.manuscript_id is distinct from old.manuscript_id then
    raise exception 'A Scene property cannot move to another Manuscript' using errcode = 'check_violation';
  end if;
  new.id := old.id;
  new.created_at := old.created_at;
  new.updated_at := now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_scene_property_value()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_property public.scene_property_definitions%rowtype;
begin
  if tg_op = 'UPDATE' and (new.scene_id is distinct from old.scene_id
                           or new.property_id is distinct from old.property_id
                           or new.manuscript_id is distinct from old.manuscript_id) then
    raise exception 'A value keeps its Scene and property for life' using errcode = 'check_violation';
  end if;
  if tg_op = 'INSERT' and not exists (select 1 from public.scenes s where s.id = new.scene_id and s.manuscript_id = new.manuscript_id) then
    raise exception 'A Scene holds values only for its own Manuscript''s properties' using errcode = 'check_violation';
  end if;
  select * into v_property from public.scene_property_definitions p where p.id = new.property_id;
  -- A missing property is left to the foreign key.
  if found then
    if v_property.project_id is distinct from new.project_id then
      raise exception 'A value belongs to its property''s Project' using errcode = 'check_violation';
    end if;
    if not public.workspace_property_value_valid(v_property.type, v_property.options, new.value) then
      raise exception 'Invalid value for a % property', v_property.type using errcode = 'check_violation';
    end if;
  end if;
  new.updated_at := now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_scene_view()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'UPDATE' and new.manuscript_id is distinct from old.manuscript_id then
    raise exception 'A view cannot move to another Manuscript' using errcode = 'check_violation';
  end if;
  if tg_op = 'UPDATE' and new.group_id is distinct from old.group_id then
    raise exception 'A view cannot move to another Base' using errcode = 'check_violation';
  end if;
  if not public.workspace_view_config_shape_valid(new.config)
     or new.config is distinct from public.prune_scene_view_config(new.manuscript_id, new.config) then
    raise exception 'Invalid view configuration' using errcode = 'check_violation';
  end if;
  if tg_op = 'INSERT' then
    if not exists (select 1 from public.manuscripts m where m.id = new.manuscript_id and m.project_id = new.project_id) then
      raise exception 'A Scene View belongs to its Manuscript''s Project' using errcode = 'check_violation';
    end if;
    new.created_at := now();
    new.updated_at := now();
    return new;
  end if;
  new.id := old.id;
  new.created_at := old.created_at;
  new.updated_at := now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_structure_sibling_position()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_table_name = 'chapters' then
    if new.trashed_at is not null then
      return null;
    end if;
    if exists (select 1 from public.manuscript_groups g
                where g.manuscript_id = new.manuscript_id
                  and g.parent_group_id is not distinct from new.group_id
                  and g.position = new.position) then
      raise exception 'Chapter % shares position % with a Group of the same parent', new.id, new.position
        using errcode = 'unique_violation';
    end if;
  else
    if exists (select 1 from public.chapters c
                where c.manuscript_id = new.manuscript_id
                  and c.group_id is not distinct from new.parent_group_id
                  and c.position = new.position
                  and c.trashed_at is null) then
      raise exception 'Group % shares position % with a Chapter of the same parent', new.id, new.position
        using errcode = 'unique_violation';
    end if;
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_workspace_collection_property()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not public.workspace_property_options_valid(new.options) then
    raise exception 'Invalid property options' using errcode = 'check_violation';
  end if;
  if tg_op = 'INSERT' then
    new.created_at := now();
    new.updated_at := now();
    return new;
  end if;
  if new.collection_id is distinct from old.collection_id then
    raise exception 'A property cannot move to another Collection' using errcode = 'check_violation';
  end if;
  new.id := old.id;
  new.created_at := old.created_at;
  new.updated_at := now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_workspace_collection_view()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'UPDATE' and new.collection_id is distinct from old.collection_id then
    raise exception 'A view cannot move to another Collection' using errcode = 'check_violation';
  end if;
  if not public.workspace_view_config_shape_valid(new.config)
     or new.config is distinct from public.prune_workspace_view_config(new.collection_id, new.config) then
    raise exception 'Invalid view configuration' using errcode = 'check_violation';
  end if;
  if tg_op = 'INSERT' then
    new.created_at := now();
    new.updated_at := now();
    return new;
  end if;
  new.id := old.id;
  new.created_at := old.created_at;
  new.updated_at := now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_workspace_entry_value()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_property public.workspace_collection_properties%rowtype;
begin
  if tg_op = 'UPDATE' and (new.entry_id is distinct from old.entry_id
                           or new.property_id is distinct from old.property_id
                           or new.collection_id is distinct from old.collection_id) then
    raise exception 'A value keeps its Entry and property for life' using errcode = 'check_violation';
  end if;
  select * into v_property from public.workspace_collection_properties p where p.id = new.property_id;
  -- A missing property is left to the foreign key.
  if found and not public.workspace_property_value_valid(v_property.type, v_property.options, new.value) then
    raise exception 'Invalid value for a % property', v_property.type using errcode = 'check_violation';
  end if;
  new.updated_at := now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_workspace_node_parent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.parent_node_id is null
     or (tg_op = 'UPDATE' and new.parent_node_id is not distinct from old.parent_node_id) then
    return new;
  end if;
  if not exists (select 1 from public.workspace_nodes n
                  where n.id = new.parent_node_id and n.target_type = 'folder') then
    raise exception 'Only a Folder can hold other Workspace items'
      using errcode = 'check_violation';
  end if;
  if exists (
       with recursive up(id) as (
         select new.parent_node_id
         union
         select n.parent_node_id
           from public.workspace_nodes n
           join up on n.id = up.id
          where n.parent_node_id is not null)
       select 1 from up where up.id = new.id) then
    raise exception 'A Folder cannot be placed inside itself or one of its own Folders'
      using errcode = 'check_violation';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_chapter_checked(p_manuscript_id uuid, p_title text, p_scene_title text, p_scene_content jsonb, p_scene_word_count integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_limit int;
  v_new_total int;
  v_chapter public.chapters%rowtype;
  v_scene_id uuid;
begin
  perform public.lock_account_word_budget();

  if not exists (
    select 1 from public.manuscripts m
      join public.projects p on p.id = m.project_id
     where m.id = p_manuscript_id and p.user_id = auth.uid()) then
    return jsonb_build_object('status', 'error', 'error', 'Manuscript not found');
  end if;

  if p_scene_word_count > 0 then
    v_limit := public.free_word_limit_for_caller();
    if v_limit is not null then
      v_new_total := public.account_word_total(null, p_scene_word_count);
      if v_new_total > v_limit then
        return jsonb_build_object('status', 'word_limit_blocked', 'limit', v_limit);
      end if;
    end if;
  end if;

  insert into public.chapters (manuscript_id, title, position)
  values (p_manuscript_id, p_title, public.next_structure_position(p_manuscript_id, null))
  returning * into v_chapter;

  insert into public.scenes (manuscript_id, chapter_id, title, content, word_count, position)
  values (p_manuscript_id, v_chapter.id, p_scene_title, p_scene_content, p_scene_word_count, 0)
  returning id into v_scene_id;

  return jsonb_build_object('status', 'ok', 'chapter', to_jsonb(v_chapter), 'scene_id', v_scene_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_default_workspace_collection_view()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  insert into public.workspace_collection_views (collection_id, project_id, name, type, position)
  values (new.id, new.project_id, 'List', 'list', 1);
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_manuscript_group(p_manuscript_id uuid, p_parent_group_id uuid, p_title text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_title text := nullif(btrim(coalesce(p_title, '')), '');
  v_group public.manuscript_groups%rowtype;
begin
  perform public.lock_account_word_budget();

  -- SECURITY DEFINER: ownership is checked here, not by RLS.
  if not exists (
    select 1 from public.manuscripts m
      join public.projects p on p.id = m.project_id
     where m.id = p_manuscript_id and p.user_id = auth.uid()) then
    return jsonb_build_object('status', 'error', 'error', 'Manuscript not found');
  end if;

  if p_parent_group_id is not null and not exists (
    select 1 from public.manuscript_groups g
     where g.id = p_parent_group_id and g.manuscript_id = p_manuscript_id) then
    return jsonb_build_object('status', 'error', 'error', 'Group not found');
  end if;

  insert into public.manuscript_groups (manuscript_id, parent_group_id, title, position)
  values (p_manuscript_id, p_parent_group_id, v_title,
          public.next_structure_position(p_manuscript_id, p_parent_group_id))
  returning * into v_group;

  return jsonb_build_object('status', 'ok', 'group', to_jsonb(v_group));
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_manuscript_milestone(p_manuscript_id uuid, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_name text := btrim(coalesce(p_name, ''));
  v_id uuid;
  v_scene public.scenes%rowtype;
  v_latest public.scene_revisions%rowtype;
  v_revision uuid;
  v_count integer := 0;
begin
  perform public.lock_account_word_budget();
  if not exists (select 1 from public.manuscripts m join public.projects p on p.id = m.project_id
                  where m.id = p_manuscript_id and p.user_id = auth.uid()) then
    return jsonb_build_object('status', 'error', 'error', 'Manuscript not found');
  end if;
  if v_name = '' then
    return jsonb_build_object('status', 'error', 'error', 'Give the milestone a name');
  end if;
  if char_length(v_name) > 120 then
    return jsonb_build_object('status', 'error', 'error', 'Keep the name to 120 characters');
  end if;

  insert into public.manuscript_milestones (manuscript_id, name, structure, manuscript_words, unplaced_words, scene_count)
  values (
    p_manuscript_id,
    v_name,
    jsonb_build_object(
      'groups', coalesce((select jsonb_agg(jsonb_build_object('id', g.id, 'title', g.title,
                                                              'parent_group_id', g.parent_group_id, 'position', g.position)
                                           order by g.position, g.id)
                            from public.manuscript_groups g where g.manuscript_id = p_manuscript_id), '[]'::jsonb),
      'chapters', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'title', c.title,
                                                                'group_id', c.group_id, 'position', c.position)
                                             order by c.position, c.id)
                              from public.chapters c where c.manuscript_id = p_manuscript_id and c.trashed_at is null), '[]'::jsonb)),
    public.ordered_manuscript_word_total(p_manuscript_id),
    (select coalesce(sum(s.word_count), 0)::int from public.scenes s
      where s.manuscript_id = p_manuscript_id and s.chapter_id is null and s.trashed_at is null),
    0)
  returning id into v_id;

  for v_scene in
    select s.* from public.scenes s
     where s.manuscript_id = p_manuscript_id and s.trashed_at is null
     order by s.chapter_id nulls last, s.position, s.id
  loop
    v_revision := null;
    select r.* into v_latest
      from public.scene_revisions r
     where r.scene_id = v_scene.id
     order by r.created_at desc, r.id desc
     limit 1;
    if found and v_latest.content is not distinct from v_scene.content and v_latest.title = v_scene.title then
      v_revision := v_latest.id;
    else
      insert into public.scene_revisions (manuscript_id, scene_id, title, content, word_count, saved_at, reason)
      values (v_scene.manuscript_id, v_scene.id, v_scene.title, v_scene.content, v_scene.word_count,
              v_scene.updated_at, 'milestone')
      returning id into v_revision;
    end if;
    insert into public.manuscript_milestone_scenes (milestone_id, scene_id, revision_id, chapter_id, position)
    values (v_id, v_scene.id, v_revision, v_scene.chapter_id, v_scene.position);
    v_count := v_count + 1;
  end loop;

  update public.manuscript_milestones set scene_count = v_count where id = v_id;
  return jsonb_build_object('status', 'ok', 'id', v_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_project_checked(p_title text, p_description text, p_cover_color text, p_first_scene_content jsonb, p_first_scene_word_count integer, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_title text := btrim(coalesce(p_title, ''));
  v_word_count int := coalesce(p_first_scene_word_count, 0);
  v_project public.projects%rowtype;
  v_manuscript_id uuid;
  v_chapter public.chapters%rowtype;
  v_has_chapter boolean;
  v_scene_id uuid;
  v_limit int;
  v_new_total int;
begin
  perform public.lock_account_word_budget();

  -- A retry of a creation that already happened: return it, write nothing.
  if p_request_id is not null then
    select * into v_project
      from public.projects p
     where p.user_id = auth.uid() and p.creation_request_id = p_request_id;
    if found then
      select c.* into v_chapter
        from public.chapters c
        join public.manuscripts m on m.id = c.manuscript_id
       where m.project_id = v_project.id
       order by c.position
       limit 1;
      v_has_chapter := found;
      if v_has_chapter then
        select s.id into v_scene_id
          from public.scenes s
         where s.chapter_id = v_chapter.id
         order by s.position
         limit 1;
      end if;
      return jsonb_build_object('status', 'ok', 'created', false,
        'project', to_jsonb(v_project),
        'chapter', case when v_has_chapter then to_jsonb(v_chapter) end,
        'scene_id', v_scene_id);
    end if;
  end if;

  if v_title = '' then
    return jsonb_build_object('status', 'error', 'error', 'Title is required');
  end if;

  if v_word_count > 0 then
    v_limit := public.free_word_limit_for_caller();
    if v_limit is not null then
      v_new_total := public.account_word_total(null, v_word_count);
      if v_new_total > v_limit then
        return jsonb_build_object('status', 'word_limit_blocked', 'limit', v_limit);
      end if;
    end if;
  end if;

  insert into public.projects (user_id, title, description, cover_color, creation_request_id)
  values (auth.uid(), v_title, p_description, p_cover_color, p_request_id)
  returning * into v_project;

  -- Created by trg_project_manuscript.
  select m.id into v_manuscript_id
    from public.manuscripts m
   where m.project_id = v_project.id;
  if v_manuscript_id is null then
    raise exception 'create_project_checked: the Manuscript of Project % was not created', v_project.id;
  end if;

  insert into public.chapters (manuscript_id, title, position)
  values (v_manuscript_id, 'Chapter 1', 1)
  returning * into v_chapter;

  insert into public.scenes (manuscript_id, chapter_id, title, content, word_count, position)
  values (v_manuscript_id, v_chapter.id, 'Scene 1', p_first_scene_content, v_word_count, 0)
  returning id into v_scene_id;

  -- Re-read: scenes_refresh_project_word_count has set word_count.
  select * into v_project from public.projects p where p.id = v_project.id;

  return jsonb_build_object('status', 'ok', 'created', true,
    'project', to_jsonb(v_project), 'chapter', to_jsonb(v_chapter), 'scene_id', v_scene_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_project_manuscript()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into public.manuscripts (project_id) values (new.id);
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_revision_note(p_note_id uuid, p_target_type text, p_target_id uuid, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_manuscript_id uuid;
  v_project_id uuid;
  v_note public.revision_notes%rowtype;
  v_body text := coalesce(p_body, '');
begin
  if auth.uid() is null or p_note_id is null or p_target_id is null then
    return jsonb_build_object('status', 'error', 'error', 'invalid');
  end if;
  if p_target_type is null or p_target_type not in ('scene', 'chapter', 'group', 'manuscript') then
    return jsonb_build_object('status', 'error', 'error', 'invalid');
  end if;
  if v_body !~ '\S' then
    return jsonb_build_object('status', 'error', 'error', 'blank');
  end if;
  if char_length(v_body) > 20000 then
    return jsonb_build_object('status', 'error', 'error', 'too_long');
  end if;

  -- A retry of a create that already landed.
  select n.* into v_note from public.revision_notes n where n.id = p_note_id;
  if found then
    if exists (select 1 from public.projects p where p.id = v_note.project_id and p.user_id = auth.uid())
       and v_note.target_type = p_target_type and v_note.target_id = p_target_id then
      return jsonb_build_object('status', 'ok', 'note', public.revision_note_json(v_note));
    end if;
    return jsonb_build_object('status', 'error', 'error', 'invalid');
  end if;

  if not public.revision_note_target_active(p_target_type, p_target_id) then
    return jsonb_build_object('status', 'unavailable');
  end if;
  case p_target_type
    when 'scene' then
      select s.manuscript_id, m.project_id into v_manuscript_id, v_project_id
        from public.scenes s join public.manuscripts m on m.id = s.manuscript_id where s.id = p_target_id;
    when 'chapter' then
      select c.manuscript_id, m.project_id into v_manuscript_id, v_project_id
        from public.chapters c join public.manuscripts m on m.id = c.manuscript_id where c.id = p_target_id;
    when 'group' then
      select g.manuscript_id, m.project_id into v_manuscript_id, v_project_id
        from public.manuscript_groups g join public.manuscripts m on m.id = g.manuscript_id where g.id = p_target_id;
    else
      select m.id, m.project_id into v_manuscript_id, v_project_id
        from public.manuscripts m where m.id = p_target_id;
  end case;

  insert into public.revision_notes (id, project_id, manuscript_id, target_type, scene_id, chapter_id, group_id, target_id, body)
  values (p_note_id, v_project_id, v_manuscript_id, p_target_type,
          case when p_target_type = 'scene' then p_target_id end,
          case when p_target_type = 'chapter' then p_target_id end,
          case when p_target_type = 'group' then p_target_id end,
          p_target_id, v_body)
  on conflict (id) do nothing
  returning * into v_note;
  if not found then
    -- The same create, racing itself: answer with what landed.
    select n.* into v_note from public.revision_notes n where n.id = p_note_id;
    if v_note.project_id <> v_project_id or v_note.target_id <> p_target_id then
      return jsonb_build_object('status', 'error', 'error', 'invalid');
    end if;
  end if;
  return jsonb_build_object('status', 'ok', 'note', public.revision_note_json(v_note));
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_revision_note_item(p_note_id uuid, p_target_type text, p_target_id uuid, p_body text, p_details text, p_resolved boolean, p_anchor jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_manuscript_id uuid;
  v_project_id uuid;
  v_note public.revision_notes%rowtype;
  v_body text := coalesce(p_body, '');
  v_details text := nullif(btrim(coalesce(p_details, '')), '');
begin
  if auth.uid() is null or p_note_id is null or p_target_id is null then
    return jsonb_build_object('status', 'error', 'error', 'invalid');
  end if;
  if p_target_type is null or p_target_type not in ('scene', 'chapter', 'group', 'manuscript') then
    return jsonb_build_object('status', 'error', 'error', 'invalid');
  end if;
  if v_body !~ '\S' then
    return jsonb_build_object('status', 'error', 'error', 'blank');
  end if;
  if char_length(v_body) > 20000 or (v_details is not null and char_length(v_details) > 20000) then
    return jsonb_build_object('status', 'error', 'error', 'too_long');
  end if;
  if p_anchor is not null and (p_target_type <> 'scene' or not public.revision_note_anchor_valid(p_anchor)) then
    return jsonb_build_object('status', 'error', 'error', 'invalid');
  end if;

  -- A retry of a create that already landed.
  select n.* into v_note from public.revision_notes n where n.id = p_note_id;
  if found then
    if exists (select 1 from public.projects p where p.id = v_note.project_id and p.user_id = auth.uid())
       and v_note.target_type = p_target_type and v_note.target_id = p_target_id then
      return jsonb_build_object('status', 'ok', 'note', public.revision_note_json(v_note));
    end if;
    return jsonb_build_object('status', 'error', 'error', 'invalid');
  end if;

  if not public.revision_note_target_active(p_target_type, p_target_id) then
    return jsonb_build_object('status', 'unavailable');
  end if;
  case p_target_type
    when 'scene' then
      select s.manuscript_id, m.project_id into v_manuscript_id, v_project_id
        from public.scenes s join public.manuscripts m on m.id = s.manuscript_id where s.id = p_target_id;
    when 'chapter' then
      select c.manuscript_id, m.project_id into v_manuscript_id, v_project_id
        from public.chapters c join public.manuscripts m on m.id = c.manuscript_id where c.id = p_target_id;
    when 'group' then
      select g.manuscript_id, m.project_id into v_manuscript_id, v_project_id
        from public.manuscript_groups g join public.manuscripts m on m.id = g.manuscript_id where g.id = p_target_id;
    else
      select m.id, m.project_id into v_manuscript_id, v_project_id
        from public.manuscripts m where m.id = p_target_id;
  end case;

  insert into public.revision_notes
    (id, project_id, manuscript_id, target_type, scene_id, chapter_id, group_id, target_id, body, details, resolved_at, anchor)
  values (p_note_id, v_project_id, v_manuscript_id, p_target_type,
          case when p_target_type = 'scene' then p_target_id end,
          case when p_target_type = 'chapter' then p_target_id end,
          case when p_target_type = 'group' then p_target_id end,
          p_target_id, v_body, v_details, case when coalesce(p_resolved, false) then now() end, p_anchor)
  on conflict (id) do nothing
  returning * into v_note;
  if not found then
    -- The same create, racing itself: answer with what landed.
    select n.* into v_note from public.revision_notes n where n.id = p_note_id;
    if v_note.project_id <> v_project_id or v_note.target_id <> p_target_id then
      return jsonb_build_object('status', 'error', 'error', 'invalid');
    end if;
  end if;
  return jsonb_build_object('status', 'ok', 'note', public.revision_note_json(v_note));
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_scene_property(p_project_id uuid, p_name text, p_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_manuscript_id uuid;
  v_name text := left(btrim(coalesce(p_name, '')), 100);
  v_property public.scene_property_definitions%rowtype;
begin
  -- SECURITY DEFINER: ownership is checked here, not by RLS.
  v_manuscript_id := public.owned_project_manuscript(p_project_id);
  if v_manuscript_id is null then
    return jsonb_build_object('status', 'error', 'error', 'Manuscript not found');
  end if;
  perform public.lock_project_workspace(p_project_id);

  if v_name = '' then
    return jsonb_build_object('status', 'error', 'error', 'A property needs a name');
  end if;
  if p_type is null or p_type not in ('text', 'number', 'select', 'multi_select', 'status', 'date', 'checkbox') then
    return jsonb_build_object('status', 'error', 'error', 'Unknown property type');
  end if;
  if exists (select 1 from public.scene_property_definitions p
              where p.manuscript_id = v_manuscript_id and lower(p.name) = lower(v_name)) then
    return jsonb_build_object('status', 'error', 'error', 'A property with this name already exists');
  end if;
  if (select count(*) from public.scene_property_definitions p where p.manuscript_id = v_manuscript_id) >= 100 then
    return jsonb_build_object('status', 'error', 'error', 'A manuscript can have at most 100 scene properties');
  end if;

  insert into public.scene_property_definitions (manuscript_id, project_id, name, type, position)
  select v_manuscript_id, p_project_id, v_name, p_type, coalesce(max(p.position), 0) + 1
    from public.scene_property_definitions p
   where p.manuscript_id = v_manuscript_id
  returning * into v_property;

  return jsonb_build_object('status', 'ok', 'property', to_jsonb(v_property));
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_scene_relationship_property(p_project_id uuid, p_name text, p_target text, p_target_collection_id uuid, p_many boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_manuscript_id uuid;
  v_name text := left(btrim(coalesce(p_name, '')), 100);
  v_property public.scene_property_definitions%rowtype;
begin
  v_manuscript_id := public.owned_project_manuscript(p_project_id);
  if v_manuscript_id is null then
    return jsonb_build_object('status', 'error', 'error', 'Manuscript not found');
  end if;
  perform public.lock_project_workspace(p_project_id);

  if v_name = '' then
    return jsonb_build_object('status', 'error', 'error', 'A property needs a name');
  end if;
  if p_target is null or p_target not in ('entry', 'page', 'scene') then
    return jsonb_build_object('status', 'error', 'error', 'Unknown relationship target');
  end if;
  if p_target = 'entry' then
    if not exists (select 1 from public.workspace_collections c
                    where c.id = p_target_collection_id and c.project_id = p_project_id and c.trashed_at is null) then
      return jsonb_build_object('status', 'error', 'error', 'Target collection not found');
    end if;
  elsif p_target_collection_id is not null then
    return jsonb_build_object('status', 'error', 'error', 'Only an Entry relationship names a collection');
  end if;
  if exists (select 1 from public.scene_property_definitions p
              where p.manuscript_id = v_manuscript_id and lower(p.name) = lower(v_name)) then
    return jsonb_build_object('status', 'error', 'error', 'A property with this name already exists');
  end if;
  if (select count(*) from public.scene_property_definitions p where p.manuscript_id = v_manuscript_id) >= 100 then
    return jsonb_build_object('status', 'error', 'error', 'A manuscript can have at most 100 scene properties');
  end if;

  insert into public.scene_property_definitions
    (manuscript_id, project_id, name, type, position, relation_target, relation_collection_id, relation_many)
  select v_manuscript_id, p_project_id, v_name, 'relationship', coalesce(max(p.position), 0) + 1,
         p_target, p_target_collection_id, coalesce(p_many, true)
    from public.scene_property_definitions p
   where p.manuscript_id = v_manuscript_id
  returning * into v_property;

  return jsonb_build_object('status', 'ok', 'property', to_jsonb(v_property));
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_scene_view(p_project_id uuid, p_name text, p_type text, p_config jsonb, p_group_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_manuscript_id uuid;
  v_name text := left(btrim(coalesce(p_name, '')), 100);
  v_config jsonb;
  v_view public.scene_views%rowtype;
begin
  v_manuscript_id := public.owned_project_manuscript(p_project_id);
  if v_manuscript_id is null then
    return jsonb_build_object('status', 'error', 'error', 'Manuscript not found');
  end if;
  perform public.lock_project_workspace(p_project_id);

  if p_group_id is not null
     and not exists (select 1 from public.manuscript_groups g where g.id = p_group_id and g.manuscript_id = v_manuscript_id) then
    return jsonb_build_object('status', 'error', 'error', 'Group not found');
  end if;
  if p_type is null or p_type not in ('list', 'table', 'board', 'timeline') then
    return jsonb_build_object('status', 'error', 'error', 'Unknown view type');
  end if;
  if v_name = '' then
    v_name := case p_type when 'list' then 'List' when 'table' then 'Table' when 'board' then 'Board' else 'Timeline' end;
  end if;
  if (select count(*) from public.scene_views v
       where v.manuscript_id = v_manuscript_id and v.group_id is not distinct from p_group_id) >= 50 then
    return jsonb_build_object('status', 'error', 'error', 'A base can have at most 50 scene views');
  end if;

  if p_config is null or p_config = 'null'::jsonb then
    v_config := public.default_scene_view_config(v_manuscript_id, p_type);
  else
    if not public.workspace_view_config_shape_valid(p_config) then
      return jsonb_build_object('status', 'error', 'error', 'Invalid view configuration');
    end if;
    v_config := public.normalize_workspace_view_config(p_config);
    if v_config is distinct from public.prune_scene_view_config(v_manuscript_id, v_config) then
      return jsonb_build_object('status', 'error', 'error', 'Invalid view configuration');
    end if;
  end if;
  if p_type = 'board' and jsonb_typeof(v_config -> 'group_by') = 'null' then
    v_config := jsonb_set(v_config, '{group_by}', public.default_scene_view_config(v_manuscript_id, 'board') -> 'group_by');
  end if;
  if p_type = 'timeline' and jsonb_typeof(v_config -> 'axis') is distinct from 'string' then
    v_config := jsonb_set(v_config, '{axis}', public.default_scene_view_config(v_manuscript_id, 'timeline') -> 'axis');
  end if;

  insert into public.scene_views (manuscript_id, project_id, group_id, name, type, position, config)
  select v_manuscript_id, p_project_id, p_group_id, v_name, p_type, coalesce(max(v.position), 0) + 1, v_config
    from public.scene_views v
   where v.manuscript_id = v_manuscript_id and v.group_id is not distinct from p_group_id
  returning * into v_view;

  return jsonb_build_object('status', 'ok', 'view', to_jsonb(v_view));
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_workspace_collection(p_project_id uuid, p_parent_node_id uuid, p_title text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_collection public.workspace_collections%rowtype;
  v_node_id uuid;
begin
  -- SECURITY DEFINER: ownership is checked here, not by RLS.
  if not exists (select 1 from public.projects p where p.id = p_project_id and p.user_id = auth.uid()) then
    return jsonb_build_object('status', 'error', 'error', 'Project not found');
  end if;
  perform public.lock_project_workspace(p_project_id);

  if p_parent_node_id is not null and not exists (
    select 1 from public.workspace_nodes n
     where n.id = p_parent_node_id and n.project_id = p_project_id and n.target_type = 'folder') then
    return jsonb_build_object('status', 'error', 'error', 'Folder not found');
  end if;

  insert into public.workspace_collections (project_id, title)
  values (p_project_id, left(nullif(btrim(coalesce(p_title, '')), ''), 200))
  returning * into v_collection;

  select n.id into v_node_id from public.workspace_nodes n where n.collection_id = v_collection.id;
  if p_parent_node_id is not null then
    perform public.place_workspace_node(v_node_id, p_parent_node_id, null);
  end if;

  return jsonb_build_object('status', 'ok', 'collection', to_jsonb(v_collection), 'node_id', v_node_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_workspace_collection_property(p_collection_id uuid, p_name text, p_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_project_id uuid;
  v_name text := left(btrim(coalesce(p_name, '')), 100);
  v_property public.workspace_collection_properties%rowtype;
begin
  -- SECURITY DEFINER: ownership is checked here, not by RLS.
  select c.project_id into v_project_id
    from public.workspace_collections c
    join public.projects p on p.id = c.project_id
   where c.id = p_collection_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Collection not found');
  end if;
  perform public.lock_project_workspace(v_project_id);

  if v_name = '' then
    return jsonb_build_object('status', 'error', 'error', 'A property needs a name');
  end if;
  if p_type is null or p_type not in ('text', 'number', 'select', 'multi_select', 'status', 'date', 'checkbox') then
    return jsonb_build_object('status', 'error', 'error', 'Unknown property type');
  end if;
  if exists (select 1 from public.workspace_collection_properties p
              where p.collection_id = p_collection_id and lower(p.name) = lower(v_name)) then
    return jsonb_build_object('status', 'error', 'error', 'A property with this name already exists');
  end if;

  -- The Collection's list shows the first three properties by default; the
  -- writer can change that per property.
  insert into public.workspace_collection_properties (collection_id, project_id, name, type, position, shown_in_list)
  select p_collection_id, v_project_id, v_name, p_type,
         coalesce(max(p.position), 0) + 1,
         count(*) filter (where p.shown_in_list) < 3
    from public.workspace_collection_properties p
   where p.collection_id = p_collection_id
  returning * into v_property;

  return jsonb_build_object('status', 'ok', 'property', to_jsonb(v_property));
end;
$function$;

