CREATE OR REPLACE FUNCTION public.default_scene_view_config(p_manuscript_id uuid, p_type text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'properties', case p_type
      when 'board' then '[]'::jsonb
      when 'timeline' then '[]'::jsonb
      when 'table' then '["words"]'::jsonb || coalesce((
        select jsonb_agg(to_jsonb(p.id::text) order by p.position)
          from public.scene_property_definitions p where p.manuscript_id = p_manuscript_id), '[]'::jsonb)
      else coalesce((
        select jsonb_agg(to_jsonb(p.id::text) order by p.position)
          from public.scene_property_definitions p where p.manuscript_id = p_manuscript_id and p.position <= 3), '[]'::jsonb)
    end,
    'sort', 'null'::jsonb,
    'filters', '[]'::jsonb,
    'group_by', case p_type
      when 'board' then coalesce((
        select to_jsonb(p.id::text)
          from public.scene_property_definitions p
         where p.manuscript_id = p_manuscript_id and p.type in ('status', 'select')
         order by (p.type = 'status') desc, p.position
         limit 1), 'null'::jsonb)
      else 'null'::jsonb
    end)
    || case when p_type = 'timeline' then '{"axis": "manuscript"}'::jsonb else '{}'::jsonb end;
$function$;

CREATE OR REPLACE FUNCTION public.default_workspace_view_config(p_collection_id uuid, p_type text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'properties', case p_type
      when 'board' then '[]'::jsonb
      when 'timeline' then '[]'::jsonb
      else coalesce((
        select jsonb_agg(to_jsonb(p.id::text) order by p.position)
          from public.workspace_collection_properties p
         where p.collection_id = p_collection_id
           and (p_type = 'table' or p.position <= 3)), '[]'::jsonb)
    end,
    'sort', 'null'::jsonb,
    'filters', '[]'::jsonb,
    'group_by', case p_type
      when 'board' then coalesce((
        select to_jsonb(p.id::text)
          from public.workspace_collection_properties p
         where p.collection_id = p_collection_id and p.type in ('status', 'select')
         order by (p.type = 'status') desc, p.position
         limit 1), 'null'::jsonb)
      else 'null'::jsonb
    end)
    || case when p_type = 'timeline' then jsonb_build_object('axis', coalesce((
         select to_jsonb(p.id::text)
           from public.workspace_collection_properties p
          where p.collection_id = p_collection_id and p.type in ('date', 'number')
          order by (p.type = 'date') desc, p.position
          limit 1), 'null'::jsonb))
       else '{}'::jsonb end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_chapter(p_chapter_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_chapter public.chapters%rowtype;
  v_scene_ids uuid[];
  v_base int;
begin
  perform public.lock_account_word_budget();

  select c.* into v_chapter
    from public.chapters c
    join public.manuscripts m on m.id = c.manuscript_id
    join public.projects p on p.id = m.project_id
   where c.id = p_chapter_id and p.user_id = auth.uid() and c.trashed_at is null
     for update of c;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Chapter not found');
  end if;

  select coalesce(array_agg(s.id order by s.position, s.id), '{}')
    into v_scene_ids
    from (select sc.id, sc.position from public.scenes sc
           where sc.chapter_id = p_chapter_id for update) s;

  select coalesce(max(s.position) + 1, 0) into v_base
    from public.scenes s
   where s.manuscript_id = v_chapter.manuscript_id and s.chapter_id is null and s.trashed_at is null;

  -- Same rows, new placement. scenes_refresh_project_word_count takes their
  -- words out of the ordered total.
  update public.scenes s
     set chapter_id = null, position = v_base + o.ord::int - 1
    from unnest(v_scene_ids) with ordinality as o(id, ord)
   where s.id = o.id;

  delete from public.chapters c where c.id = p_chapter_id;

  return jsonb_build_object('status', 'ok', 'unplaced_scene_ids', to_jsonb(v_scene_ids));
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_manuscript_group(p_group_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_group public.manuscript_groups%rowtype;
begin
  perform public.lock_account_word_budget();

  select g.* into v_group
    from public.manuscript_groups g
    join public.manuscripts m on m.id = g.manuscript_id
    join public.projects p on p.id = m.project_id
   where g.id = p_group_id and p.user_id = auth.uid()
     for update of g;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Group not found');
  end if;

  if exists (select 1 from public.manuscript_groups g where g.parent_group_id = p_group_id)
     or exists (select 1 from public.chapters c where c.group_id = p_group_id) then
    return jsonb_build_object('status', 'error', 'error', 'Only an empty Group can be deleted');
  end if;

  delete from public.manuscript_groups g where g.id = p_group_id;
  return jsonb_build_object('status', 'ok');
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_manuscript_milestone(p_milestone_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_revisions uuid[];
begin
  perform public.lock_account_word_budget();
  if not exists (select 1 from public.manuscript_milestones ml
                   join public.manuscripts m on m.id = ml.manuscript_id
                   join public.projects p on p.id = m.project_id
                  where ml.id = p_milestone_id and p.user_id = auth.uid()) then
    return jsonb_build_object('status', 'error', 'error', 'Milestone not found');
  end if;
  select coalesce(array_agg(ms.revision_id), '{}') into v_revisions
    from public.manuscript_milestone_scenes ms where ms.milestone_id = p_milestone_id;
  delete from public.manuscript_milestones where id = p_milestone_id;
  delete from public.scene_revisions r
   where r.id = any (v_revisions)
     and r.scene_id is null
     and not exists (select 1 from public.manuscript_milestone_scenes ms where ms.revision_id = r.id);
  return jsonb_build_object('status', 'ok');
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_revision_note(p_note_id uuid, p_base_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_note public.revision_notes%rowtype;
begin
  select n.* into v_note
    from public.revision_notes n
    join public.projects p on p.id = n.project_id
   where n.id = p_note_id and p.user_id = auth.uid()
   for update of n;
  if not found then
    return jsonb_build_object('status', 'ok');
  end if;
  if not public.revision_note_target_active(v_note.target_type, v_note.target_id) then
    return jsonb_build_object('status', 'unavailable');
  end if;
  if p_base_version is not null and p_base_version <> v_note.version then
    return jsonb_build_object('status', 'conflict', 'note', public.revision_note_json(v_note));
  end if;
  delete from public.revision_notes n where n.id = p_note_id;
  return jsonb_build_object('status', 'ok');
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_scene_property(p_property_id uuid, p_expected_values integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_property public.scene_property_definitions%rowtype;
  v_values integer;
begin
  select pr.* into v_property
    from public.scene_property_definitions pr
    join public.projects p on p.id = pr.project_id
   where pr.id = p_property_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Property not found');
  end if;
  perform public.lock_project_workspace(v_property.project_id);

  if v_property.type = 'relationship' then
    select count(distinct r.source_scene_id) into v_values from public.object_references r where r.scene_property_id = p_property_id;
  else
    select count(*) into v_values from public.scene_property_values v where v.property_id = p_property_id;
  end if;
  if v_values is distinct from coalesce(p_expected_values, 0) then
    return jsonb_build_object('status', 'confirm', 'values', v_values);
  end if;

  -- Its values go with it (scene_property_values_property_same_manuscript_fkey,
  -- object_references_scene_property_id_fkey).
  delete from public.scene_property_definitions p where p.id = p_property_id;
  update public.scene_property_definitions p
     set position = r.rank
    from (select id, row_number() over (order by position) as rank
            from public.scene_property_definitions
           where manuscript_id = v_property.manuscript_id) r
   where p.id = r.id and p.position <> r.rank;
  return jsonb_build_object('status', 'ok', 'deleted_values', v_values);
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_scene_view(p_view_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_view public.scene_views%rowtype;
begin
  select v.* into v_view
    from public.scene_views v
    join public.projects p on p.id = v.project_id
   where v.id = p_view_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'View not found');
  end if;
  perform public.lock_project_workspace(v_view.project_id);

  delete from public.scene_views v where v.id = p_view_id;
  update public.scene_views v
     set position = r.rank
    from (select id, row_number() over (order by position) as rank
            from public.scene_views
           where manuscript_id = v_view.manuscript_id and group_id is not distinct from v_view.group_id) r
   where v.id = r.id and v.position <> r.rank;
  return jsonb_build_object('status', 'ok');
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_trashed_manuscript_chapter(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_chapter public.chapters%rowtype;
  v_scenes integer;
begin
  perform public.lock_account_word_budget();
  select c.* into v_chapter
    from public.chapters c
    join public.manuscripts m on m.id = c.manuscript_id
    join public.projects p on p.id = m.project_id
   where c.id = p_id and p.user_id = auth.uid()
     for update of c;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Item not found');
  end if;
  if v_chapter.trashed_at is null then
    return jsonb_build_object('status', 'error', 'error', 'Only an item in Trash can be deleted permanently');
  end if;

  -- Its Scenes' writing history stays (scenes_detach_writing_sessions); their
  -- Scene History goes, except revisions a Milestone uses.
  delete from public.scenes
   where trashed_with_chapter and trashed_from_chapter_id = p_id and manuscript_id = v_chapter.manuscript_id;
  get diagnostics v_scenes = row_count;
  delete from public.chapters where id = p_id;
  return jsonb_build_object('status', 'ok', 'entries', 0, 'properties', 0, 'scenes', v_scenes);
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_trashed_manuscript_scene(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform public.lock_account_word_budget();
  if not exists (select 1 from public.scenes s
                   join public.manuscripts m on m.id = s.manuscript_id
                   join public.projects p on p.id = m.project_id
                  where s.id = p_id and p.user_id = auth.uid()) then
    return jsonb_build_object('status', 'error', 'error', 'Item not found');
  end if;
  if not exists (select 1 from public.scenes s where s.id = p_id and s.trashed_at is not null) then
    return jsonb_build_object('status', 'error', 'error', 'Only an item in Trash can be deleted permanently');
  end if;
  if exists (select 1 from public.scenes s where s.id = p_id and s.trashed_with_chapter) then
    return jsonb_build_object('status', 'error', 'error', 'It is in Trash with its chapter');
  end if;
  delete from public.scenes s where s.id = p_id;
  return jsonb_build_object('status', 'ok', 'entries', 0, 'properties', 0);
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_trashed_workspace_object(p_type text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_project_id uuid;
  v_entries integer := 0;
  v_properties integer := 0;
  v_in_trash boolean;
begin
  -- A Scene (031) follows the manuscript's rules, not the Workspace tree's.
  if p_type = 'scene' then
    return public.delete_trashed_manuscript_scene(p_id);
  end if;
  -- A Chapter (037) goes with its Scenes, as one piece of the manuscript.
  if p_type = 'chapter' then
    return public.delete_trashed_manuscript_chapter(p_id);
  end if;
  if p_type is null or p_type not in ('page', 'folder', 'collection', 'entry') then
    return jsonb_build_object('status', 'error', 'error', 'Unknown item type');
  end if;
  v_project_id := public.owned_workspace_object_project(p_type, p_id);
  if v_project_id is null then
    return jsonb_build_object('status', 'error', 'error', 'Item not found');
  end if;
  perform public.lock_project_workspace(v_project_id);

  -- Only what is in Trash itself (an Entry: trashed on its own).
  v_in_trash := case p_type
    when 'page' then exists (select 1 from public.workspace_documents d where d.id = p_id and d.trashed_at is not null)
    when 'folder' then exists (select 1 from public.workspace_folders f where f.id = p_id and f.trashed_at is not null)
    when 'collection' then exists (select 1 from public.workspace_collections c where c.id = p_id and c.trashed_at is not null)
    else exists (select 1 from public.workspace_collection_entries e where e.id = p_id and e.trashed_at is not null)
  end;
  if not v_in_trash then
    return jsonb_build_object('status', 'error', 'error', 'Only an item in Trash can be deleted permanently');
  end if;

  if p_type = 'page' then
    delete from public.workspace_documents d where d.id = p_id;
  elsif p_type = 'folder' then
    delete from public.workspace_folders f where f.id = p_id;
  elsif p_type = 'entry' then
    delete from public.workspace_collection_entries e where e.id = p_id;
  else
    select count(*) into v_properties from public.workspace_collection_properties pr
     where pr.relation_collection_id = p_id and pr.collection_id <> p_id;
    v_properties := v_properties
      + (select count(*) from public.scene_property_definitions sp where sp.relation_collection_id = p_id);
    delete from public.workspace_collection_entries e where e.collection_id = p_id;
    get diagnostics v_entries = row_count;
    delete from public.workspace_collections c where c.id = p_id;
  end if;
  return jsonb_build_object('status', 'ok', 'entries', v_entries, 'properties', v_properties);
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_workspace_collection(p_collection_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_project_id uuid;
  v_parent uuid;
begin
  select c.project_id into v_project_id
    from public.workspace_collections c
    join public.projects p on p.id = c.project_id
   where c.id = p_collection_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Collection not found');
  end if;
  perform public.lock_project_workspace(v_project_id);

  -- Only an empty Collection: there is no Trash, so no Entry is ever lost.
  if exists (select 1 from public.workspace_collection_entries e where e.collection_id = p_collection_id) then
    return jsonb_build_object('status', 'error', 'error', 'Only an empty collection can be deleted');
  end if;

  select n.parent_node_id into v_parent from public.workspace_nodes n where n.collection_id = p_collection_id;
  -- Its node goes with it (workspace_nodes_collection_same_project_fkey).
  delete from public.workspace_collections c where c.id = p_collection_id;
  perform public.renumber_workspace_siblings(v_project_id, v_parent);
  return jsonb_build_object('status', 'ok');
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_workspace_collection_property(p_property_id uuid, p_expected_values integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_property public.workspace_collection_properties%rowtype;
  v_values integer;
begin
  select pr.* into v_property
    from public.workspace_collection_properties pr
    join public.projects p on p.id = pr.project_id
   where pr.id = p_property_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Property not found');
  end if;
  perform public.lock_project_workspace(v_property.project_id);

  if v_property.type = 'relationship' then
    select count(distinct r.source_entry_id) into v_values from public.object_references r where r.property_id = p_property_id;
  else
    select count(*) into v_values from public.workspace_entry_values v where v.property_id = p_property_id;
  end if;
  if v_values is distinct from coalesce(p_expected_values, 0) then
    return jsonb_build_object('status', 'confirm', 'values', v_values);
  end if;

  -- Its values go with it (workspace_entry_values_property_same_collection_fkey,
  -- object_references_property_id_fkey). The objects they pointed to stay.
  delete from public.workspace_collection_properties p where p.id = p_property_id;
  update public.workspace_collection_properties p
     set position = r.rank
    from (select id, row_number() over (order by position) as rank
            from public.workspace_collection_properties
           where collection_id = v_property.collection_id) r
   where p.id = r.id and p.position <> r.rank;
  return jsonb_build_object('status', 'ok', 'deleted_values', v_values);
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_workspace_collection_view(p_view_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_view public.workspace_collection_views%rowtype;
begin
  select v.* into v_view
    from public.workspace_collection_views v
    join public.projects p on p.id = v.project_id
   where v.id = p_view_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'View not found');
  end if;
  perform public.lock_project_workspace(v_view.project_id);

  if not exists (select 1 from public.workspace_collection_views v
                  where v.collection_id = v_view.collection_id and v.id <> p_view_id) then
    return jsonb_build_object('status', 'error', 'error', 'A collection keeps at least one view');
  end if;

  delete from public.workspace_collection_views v where v.id = p_view_id;
  update public.workspace_collection_views v
     set position = r.rank
    from (select id, row_number() over (order by position) as rank
            from public.workspace_collection_views
           where collection_id = v_view.collection_id) r
   where v.id = r.id and v.position <> r.rank;
  return jsonb_build_object('status', 'ok');
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_workspace_folder(p_folder_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_project_id uuid;
  v_node public.workspace_nodes%rowtype;
begin
  select f.project_id into v_project_id
    from public.workspace_folders f
    join public.projects p on p.id = f.project_id
   where f.id = p_folder_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Folder not found');
  end if;
  perform public.lock_project_workspace(v_project_id);

  select n.* into v_node from public.workspace_nodes n where n.folder_id = p_folder_id;
  if exists (select 1 from public.workspace_nodes n where n.parent_node_id = v_node.id) then
    return jsonb_build_object('status', 'error', 'error', 'Only an empty folder can be deleted');
  end if;

  -- Its node goes with it (workspace_nodes_folder_same_project_fkey).
  delete from public.workspace_folders f where f.id = p_folder_id;
  perform public.renumber_workspace_siblings(v_project_id, v_node.parent_node_id);
  return jsonb_build_object('status', 'ok');
end;
$function$;

CREATE OR REPLACE FUNCTION public.detach_scene_writing_sessions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_project_id uuid;
  r public.writing_sessions%rowtype;
  v_bucket_id uuid;
begin
  select m.project_id into v_project_id
    from public.manuscripts m where m.id = old.manuscript_id;
  if v_project_id is null then
    -- The Project is being deleted: its writing history goes with it.
    delete from public.writing_sessions ws where ws.scene_id = old.id;
    return old;
  end if;

  for r in select * from public.writing_sessions ws where ws.scene_id = old.id for update loop
    select ws.id into v_bucket_id
      from public.writing_sessions ws
     where ws.user_id = r.user_id and ws.session_date = r.session_date
       and ws.scene_id is null and ws.project_id = coalesce(r.project_id, v_project_id)
       for update;
    if found then
      update public.writing_sessions ws set words_added = ws.words_added + r.words_added where ws.id = v_bucket_id;
      delete from public.writing_sessions ws where ws.id = r.id;
    else
      update public.writing_sessions ws
         set scene_id = null, project_id = coalesce(r.project_id, v_project_id)
       where ws.id = r.id;
    end if;
  end loop;
  return old;
end;
$function$;

CREATE OR REPLACE FUNCTION public.duplicate_project_checked(p_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_source public.projects%rowtype;
  v_source_manuscript_id uuid;
  v_source_chapter record;
  v_new_project public.projects%rowtype;
  v_new_manuscript_id uuid;
  v_new_chapter_id uuid;
  v_group_map jsonb;
  v_new_title text;
  v_used_numbers int[];
  v_draft_num int;
  v_source_total int;
  v_placed_total int;
begin
  perform public.lock_account_word_budget();

  select * into v_source
    from public.projects
   where id = p_project_id and user_id = auth.uid();

  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Project not found');
  end if;

  select m.id into v_source_manuscript_id
    from public.manuscripts m
   where m.project_id = p_project_id;

  select coalesce(sum(s.word_count), 0),
         coalesce(sum(s.word_count) filter (where s.chapter_id is not null), 0)
    into v_source_total, v_placed_total
    from public.scenes s
   where s.manuscript_id = v_source_manuscript_id and s.trashed_at is null;

  -- Unique "— Draft N" title: smallest unused number starting at 2 (gap-filling).
  select array_agg((regexp_match(p.title, '— Draft (\d+)$'))[1]::int)
    into v_used_numbers
  from public.projects p
  where p.user_id = auth.uid()
    and p.title ilike v_source.title || ' — Draft%'
    and regexp_match(p.title, '— Draft (\d+)$') is not null;

  v_draft_num := 2;
  while v_used_numbers is not null and v_draft_num = any(v_used_numbers) loop
    v_draft_num := v_draft_num + 1;
  end loop;

  v_new_title := v_source.title || ' — Draft ' || v_draft_num;

  insert into public.projects (user_id, title, description, cover_color, word_count)
  values (auth.uid(), v_new_title, v_source.description, v_source.cover_color, v_placed_total)
  returning * into v_new_project;

  -- Created by trg_project_manuscript.
  select m.id into v_new_manuscript_id
    from public.manuscripts m
   where m.project_id = v_new_project.id;

  -- Every Group in one statement (a parent's foreign key is checked at its end).
  select coalesce(jsonb_object_agg(g.id, gen_random_uuid()), '{}'::jsonb) into v_group_map
    from public.manuscript_groups g
   where g.manuscript_id = v_source_manuscript_id;

  insert into public.manuscript_groups (id, manuscript_id, parent_group_id, title, position)
  select (v_group_map ->> g.id::text)::uuid, v_new_manuscript_id,
         (v_group_map ->> g.parent_group_id::text)::uuid, g.title, g.position
    from public.manuscript_groups g
   where g.manuscript_id = v_source_manuscript_id;

  for v_source_chapter in
    select * from public.chapters where manuscript_id = v_source_manuscript_id and trashed_at is null order by position
  loop
    insert into public.chapters (manuscript_id, group_id, title, position)
    values (v_new_manuscript_id, (v_group_map ->> v_source_chapter.group_id::text)::uuid,
            v_source_chapter.title, v_source_chapter.position)
    returning id into v_new_chapter_id;

    insert into public.scenes (manuscript_id, chapter_id, title, content, word_count, position)
    select v_new_manuscript_id, v_new_chapter_id, s.title, s.content, s.word_count, s.position
      from public.scenes s
     where s.chapter_id = v_source_chapter.id and s.trashed_at is null
     order by s.position;
  end loop;

  insert into public.scenes (manuscript_id, chapter_id, title, content, word_count, position)
  select v_new_manuscript_id, null, s.title, s.content, s.word_count, s.position
    from public.scenes s
   where s.manuscript_id = v_source_manuscript_id and s.chapter_id is null and s.trashed_at is null
   order by s.position;

  return jsonb_build_object('status', 'ok', 'project', to_jsonb(v_new_project));
end;
$function$;

CREATE OR REPLACE FUNCTION public.fill_scene_manuscript_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.manuscript_id is null and new.chapter_id is not null then
    select c.manuscript_id into new.manuscript_id
      from public.chapters c
     where c.id = new.chapter_id;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.forbid_manuscript_group_cycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.parent_group_id is not null and exists (
       with recursive up(id) as (
         select new.parent_group_id
         union
         select g.parent_group_id
           from public.manuscript_groups g
           join up on g.id = up.id
          where g.parent_group_id is not null)
       select 1 from up where up.id = new.id) then
    raise exception 'A Group cannot be placed inside itself or one of its own Groups'
      using errcode = 'check_violation';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.forbid_manuscript_reassignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.manuscript_id is distinct from old.manuscript_id then
    raise exception 'A row of % cannot move to another Manuscript', tg_table_name
      using errcode = 'check_violation';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.forbid_project_reassignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.project_id is distinct from old.project_id then
    raise exception 'A row of % cannot move to another Project', tg_table_name
      using errcode = 'check_violation';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.forget_scene_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  delete from public.scene_revisions r
   where r.scene_id = old.id
     and not exists (select 1 from public.manuscript_milestone_scenes ms where ms.revision_id = r.id);
  return old;
end;
$function$;

CREATE OR REPLACE FUNCTION public.free_word_limit_for_caller()
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;
  -- Rune 2.0 has no free-word limit (migration 037).
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.freeze_workspace_entry_collection()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.collection_id is distinct from old.collection_id then
    raise exception 'An Entry cannot move to another Collection'
      using errcode = 'check_violation';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.freeze_workspace_node_target()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.target_type is distinct from old.target_type
     or new.document_id is distinct from old.document_id
     or new.folder_id is distinct from old.folder_id
     or new.collection_id is distinct from old.collection_id then
    raise exception 'A Workspace node keeps its object for life'
      using errcode = 'check_violation';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_manuscript_milestone(p_milestone_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_ml public.manuscript_milestones%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;
  select ml.* into v_ml
    from public.manuscript_milestones ml
    join public.manuscripts m on m.id = ml.manuscript_id
    join public.projects p on p.id = m.project_id
   where ml.id = p_milestone_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Milestone not found');
  end if;
  return jsonb_build_object(
    'status', 'ok',
    'milestone', jsonb_build_object('id', v_ml.id, 'name', v_ml.name, 'created_at', v_ml.created_at,
                                    'manuscript_words', v_ml.manuscript_words, 'unplaced_words', v_ml.unplaced_words,
                                    'scene_count', v_ml.scene_count, 'structure', v_ml.structure),
    'scenes', coalesce((
      select jsonb_agg(jsonb_build_object('scene_id', ms.scene_id, 'chapter_id', ms.chapter_id, 'position', ms.position,
                                          'revision_id', r.id, 'title', r.title, 'content', r.content,
                                          'word_count', r.word_count)
                       order by ms.chapter_id nulls last, ms.position, ms.scene_id)
        from public.manuscript_milestone_scenes ms
        join public.scene_revisions r on r.id = ms.revision_id
       where ms.milestone_id = v_ml.id), '[]'::jsonb));
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_scene_revision(p_revision_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_rev public.scene_revisions%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;
  select r.* into v_rev
    from public.scene_revisions r
    join public.manuscripts m on m.id = r.manuscript_id
    join public.projects p on p.id = m.project_id
   where r.id = p_revision_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Version not found');
  end if;
  return jsonb_build_object('status', 'ok', 'revision', jsonb_build_object(
    'id', v_rev.id, 'scene_id', v_rev.scene_id, 'title', v_rev.title, 'content', v_rev.content,
    'word_count', v_rev.word_count, 'saved_at', v_rev.saved_at, 'created_at', v_rev.created_at,
    'reason', v_rev.reason));
end;
$function$;

CREATE OR REPLACE FUNCTION public.guard_workspace_trash()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_table_name = 'object_references' then
    if not public.workspace_object_active(new.source_type, coalesce(new.source_entry_id, new.source_document_id, new.source_scene_id))
       or not public.workspace_object_active(new.target_type,
            coalesce(new.target_entry_id, new.target_document_id, new.target_scene_id, new.target_chapter_id)) then
      raise exception 'Nothing can be linked to or from an item in Trash' using errcode = 'check_violation';
    end if;
  elsif tg_table_name = 'workspace_collection_properties' then
    if tg_op = 'INSERT' and not public.workspace_object_active('collection', new.collection_id) then
      raise exception 'This collection is in Trash' using errcode = 'check_violation';
    end if;
    if new.relation_collection_id is not null
       and (tg_op = 'INSERT' or new.relation_collection_id is distinct from old.relation_collection_id)
       and not public.workspace_object_active('collection', new.relation_collection_id) then
      raise exception 'That collection is in Trash' using errcode = 'check_violation';
    end if;
  elsif tg_table_name = 'workspace_collection_views' then
    if not public.workspace_object_active('collection', new.collection_id) then
      raise exception 'This collection is in Trash' using errcode = 'check_violation';
    end if;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into public.profiles (
    id,
    display_name,
    avatar_url,
    xp,
    level,
    has_written_first_words,
    subscription_tier
  ) values (
    new.id,
    new.raw_user_meta_data ->> 'display_name',
    new.raw_user_meta_data ->> 'avatar_url',
    0,
    1,
    false,
    'free'
  );

  insert into public.user_pricing_entitlements (
    user_id,
    pricing_cohort,
    founder_offer_status
  ) values (
    new.id,
    'starter_2k',
    'not_offered'
  );

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.import_manuscript_checked(p_title text, p_manuscript jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_title text := btrim(coalesce(p_title, ''));
  v_project public.projects%rowtype;
  v_manuscript_id uuid;
  v_items jsonb;
  v_unplaced jsonb;
  v_shape jsonb;
  v_unplaced_shape jsonb;
  v_words bigint;
  v_limit int;
begin
  perform public.lock_account_word_budget();

  -- A retry of an import that already happened: return it, write nothing.
  if p_request_id is not null then
    select * into v_project
      from public.projects p
     where p.user_id = auth.uid() and p.creation_request_id = p_request_id;
    if found then
      select m.id into v_manuscript_id from public.manuscripts m where m.project_id = v_project.id;
      return jsonb_build_object('status', 'ok', 'created', false,
        'project', to_jsonb(v_project), 'manuscript_id', v_manuscript_id);
    end if;
  end if;

  if v_title = '' or char_length(v_title) > 200 then
    return jsonb_build_object('status', 'error', 'error', 'The project needs a title of at most 200 characters');
  end if;
  if jsonb_typeof(p_manuscript) is distinct from 'object'
     or exists (select 1 from jsonb_object_keys(p_manuscript) k where k not in ('items', 'unplaced')) then
    return jsonb_build_object('status', 'error', 'error', 'Invalid manuscript structure');
  end if;
  v_items := coalesce(p_manuscript -> 'items', '[]'::jsonb);
  v_unplaced := coalesce(p_manuscript -> 'unplaced', '[]'::jsonb);
  if jsonb_typeof(v_unplaced) is distinct from 'array' then
    return jsonb_build_object('status', 'error', 'error', 'Invalid manuscript structure');
  end if;

  v_shape := public.import_manuscript_shape(v_items, 0);
  if v_shape ? 'error' then
    return jsonb_build_object('status', 'error', 'error', v_shape ->> 'error');
  end if;
  v_unplaced_shape := public.import_manuscript_shape(
    coalesce((select jsonb_agg(jsonb_build_object('kind', 'scene', 'scene', s)) from jsonb_array_elements(v_unplaced) s), '[]'::jsonb), 0);
  if v_unplaced_shape ? 'error' then
    return jsonb_build_object('status', 'error', 'error', v_unplaced_shape ->> 'error');
  end if;
  if (v_shape ->> 'chapters')::int = 0 and (v_unplaced_shape ->> 'scenes')::int = 0 then
    return jsonb_build_object('status', 'error', 'error', 'There is nothing to import');
  end if;
  if (v_shape ->> 'groups')::int > 1000 or (v_shape ->> 'chapters')::int > 5000
     or (v_shape ->> 'scenes')::int + (v_unplaced_shape ->> 'scenes')::int > 20000 then
    return jsonb_build_object('status', 'error', 'error', 'This manuscript has more structure than one import can create');
  end if;

  v_words := (v_shape ->> 'words')::bigint + (v_unplaced_shape ->> 'words')::bigint;
  if v_words > 2000000 then
    return jsonb_build_object('status', 'error', 'error', 'This manuscript is too long to import');
  end if;
  if v_words > 0 then
    v_limit := public.free_word_limit_for_caller();
    if v_limit is not null and public.account_word_total(null, v_words::int) > v_limit then
      return jsonb_build_object('status', 'word_limit_blocked', 'limit', v_limit);
    end if;
  end if;

  insert into public.projects (user_id, title, creation_request_id)
  values (auth.uid(), v_title, p_request_id)
  returning * into v_project;

  -- Created by trg_project_manuscript.
  select m.id into v_manuscript_id
    from public.manuscripts m
   where m.project_id = v_project.id;
  if v_manuscript_id is null then
    raise exception 'import_manuscript_checked: the Manuscript of Project % was not created', v_project.id;
  end if;

  perform public.import_manuscript_items(v_manuscript_id, null, v_items);

  insert into public.scenes (manuscript_id, chapter_id, title, content, word_count, position)
  select v_manuscript_id, null, coalesce(btrim(s ->> 'title'), ''), s -> 'content', (s ->> 'word_count')::int, (i - 1)::int
    from jsonb_array_elements(v_unplaced) with ordinality as t(s, i)
   order by i;

  -- The stored total, as the triggers left it.
  select * into v_project from public.projects where id = v_project.id;

  return jsonb_build_object('status', 'ok', 'created', true,
    'project', to_jsonb(v_project), 'manuscript_id', v_manuscript_id,
    'groups', (v_shape ->> 'groups')::int,
    'chapters', (v_shape ->> 'chapters')::int,
    'scenes', (v_shape ->> 'scenes')::int + (v_unplaced_shape ->> 'scenes')::int);
end;
$function$;

CREATE OR REPLACE FUNCTION public.import_manuscript_items(p_manuscript_id uuid, p_parent_group_id uuid, p_items jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_item jsonb;
  v_position int;
  v_group_id uuid;
  v_chapter_id uuid;
begin
  for v_item, v_position in
    select x, i::int from jsonb_array_elements(p_items) with ordinality as t(x, i)
  loop
    if v_item ->> 'kind' = 'group' then
      insert into public.manuscript_groups (manuscript_id, parent_group_id, title, position)
      values (p_manuscript_id, p_parent_group_id, nullif(btrim(v_item ->> 'title'), ''), v_position)
      returning id into v_group_id;
      perform public.import_manuscript_items(p_manuscript_id, v_group_id, v_item -> 'items');
    else
      insert into public.chapters (manuscript_id, group_id, title, position)
      values (p_manuscript_id, p_parent_group_id, btrim(v_item ->> 'title'), v_position)
      returning id into v_chapter_id;
      insert into public.scenes (manuscript_id, chapter_id, title, content, word_count, position)
      select p_manuscript_id, v_chapter_id, coalesce(btrim(s ->> 'title'), ''), s -> 'content',
             (s ->> 'word_count')::int, (i - 1)::int
        from jsonb_array_elements(v_item -> 'scenes') with ordinality as t(s, i)
       order by i;
    end if;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION public.import_manuscript_shape(p_items jsonb, p_depth integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_item jsonb;
  v_scene jsonb;
  v_inner jsonb;
  v_groups bigint := 0;
  v_chapters bigint := 0;
  v_scenes bigint := 0;
  v_words bigint := 0;
begin
  if jsonb_typeof(p_items) is distinct from 'array' then
    return jsonb_build_object('error', 'Invalid manuscript structure');
  end if;
  for v_item in select x from jsonb_array_elements(p_items) x loop
    if jsonb_typeof(v_item) is distinct from 'object' then
      return jsonb_build_object('error', 'Invalid manuscript structure');
    end if;
    if v_item ->> 'kind' = 'group' then
      if p_depth >= 4 then
        return jsonb_build_object('error', 'Groups can be nested at most 4 deep');
      end if;
      if jsonb_typeof(v_item -> 'title') not in ('null', 'string')
         or (jsonb_typeof(v_item -> 'title') = 'string'
             and (btrim(v_item ->> 'title') = '' or char_length(v_item ->> 'title') > 500)) then
        return jsonb_build_object('error', 'A group title must be text of at most 500 characters, or none');
      end if;
      v_inner := public.import_manuscript_shape(v_item -> 'items', p_depth + 1);
      if v_inner ? 'error' then
        return v_inner;
      end if;
      v_groups := v_groups + 1 + (v_inner ->> 'groups')::bigint;
      v_chapters := v_chapters + (v_inner ->> 'chapters')::bigint;
      v_scenes := v_scenes + (v_inner ->> 'scenes')::bigint;
      v_words := v_words + (v_inner ->> 'words')::bigint;
    elsif v_item ->> 'kind' = 'chapter' then
      if jsonb_typeof(v_item -> 'title') is distinct from 'string'
         or btrim(v_item ->> 'title') = '' or char_length(v_item ->> 'title') > 500 then
        return jsonb_build_object('error', 'A chapter needs a title of at most 500 characters');
      end if;
      if jsonb_typeof(v_item -> 'scenes') is distinct from 'array' or jsonb_array_length(v_item -> 'scenes') = 0 then
        return jsonb_build_object('error', 'A chapter needs at least one scene');
      end if;
      v_chapters := v_chapters + 1;
      for v_scene in select x from jsonb_array_elements(v_item -> 'scenes') x loop
        v_inner := public.import_manuscript_shape(jsonb_build_array(jsonb_build_object('kind', 'scene', 'scene', v_scene)), p_depth);
        if v_inner ? 'error' then
          return v_inner;
        end if;
        v_scenes := v_scenes + 1;
        v_words := v_words + (v_inner ->> 'words')::bigint;
      end loop;
    elsif v_item ->> 'kind' = 'scene' then
      -- One Scene (a Chapter's, or Unplaced), wrapped by the caller.
      v_scene := v_item -> 'scene';
      if jsonb_typeof(v_scene) is distinct from 'object'
         or jsonb_typeof(v_scene -> 'title') not in ('null', 'string')
         or char_length(coalesce(v_scene ->> 'title', '')) > 500
         or jsonb_typeof(v_scene -> 'content') is distinct from 'object'
         or v_scene -> 'content' ->> 'type' is distinct from 'doc'
         or jsonb_typeof(v_scene -> 'content' -> 'content') is distinct from 'array'
         or jsonb_typeof(v_scene -> 'word_count') is distinct from 'number'
         or (v_scene ->> 'word_count')::numeric <> floor((v_scene ->> 'word_count')::numeric)
         or (v_scene ->> 'word_count')::numeric not between 0 and 2000000 then
        return jsonb_build_object('error', 'Invalid scene');
      end if;
      v_scenes := v_scenes + 1;
      v_words := v_words + (v_scene ->> 'word_count')::bigint;
    else
      return jsonb_build_object('error', 'Invalid manuscript structure');
    end if;
  end loop;
  return jsonb_build_object('groups', v_groups, 'chapters', v_chapters, 'scenes', v_scenes, 'words', v_words);
end;
$function$;

-- Unused by the app. SECURITY DEFINER without a pinned search_path, trusts
-- p_user_id, and is executable by PUBLIC/anon. Carried over from the Rune 1.x
-- baseline as-is; hardening is a separate, explicitly approved change.
CREATE OR REPLACE FUNCTION public.increment_game_ticket(p_user_id uuid, p_week_start date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  INSERT INTO public.game_tickets (user_id, week_start, tickets_used)
  VALUES (p_user_id, p_week_start, 1)
  ON CONFLICT (user_id, week_start)
  DO UPDATE SET tickets_used = game_tickets.tickets_used + 1;
END;
$function$;

CREATE OR REPLACE FUNCTION public.increment_scene_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.trashed_at is distinct from old.trashed_at then
    new.version = old.version;
    new.updated_at = old.updated_at;
    return new;
  end if;
  new.version = old.version + 1;
  new.updated_at = now(); -- server-side high-precision timestamp
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.insert_scene_checked(p_chapter_id uuid, p_title text, p_content jsonb, p_word_count integer, p_position integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_manuscript_id uuid;
  v_position int;
  v_new public.scenes%rowtype;
begin
  perform public.lock_account_word_budget();

  -- SECURITY DEFINER: ownership is checked here, not by RLS.
  select c.manuscript_id into v_manuscript_id
    from public.chapters c
    join public.manuscripts m on m.id = c.manuscript_id
    join public.projects p on p.id = m.project_id
   where c.id = p_chapter_id and p.user_id = auth.uid() and c.trashed_at is null;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Chapter not found');
  end if;

  -- p_position is ignored (migration 018): always the end of the Chapter.
  select coalesce(max(s.position) + 1, 0) into v_position
    from public.scenes s
   where s.chapter_id = p_chapter_id;

  insert into public.scenes (manuscript_id, chapter_id, title, content, word_count, position)
  values (v_manuscript_id, p_chapter_id, p_title, p_content, p_word_count, v_position)
  returning * into v_new;

  return jsonb_build_object('status', 'ok', 'id', v_new.id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.insert_unplaced_scene_checked(p_manuscript_id uuid, p_title text, p_content jsonb, p_word_count integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_limit int;
  v_new_total int;
  v_position int;
  v_new public.scenes%rowtype;
begin
  perform public.lock_account_word_budget();

  -- SECURITY DEFINER: ownership is checked here, not by RLS.
  if not exists (
    select 1 from public.manuscripts m
      join public.projects p on p.id = m.project_id
     where m.id = p_manuscript_id and p.user_id = auth.uid()) then
    return jsonb_build_object('status', 'error', 'error', 'Manuscript not found');
  end if;

  if p_word_count > 0 then
    v_limit := public.free_word_limit_for_caller();
    if v_limit is not null then
      v_new_total := public.account_word_total(null, p_word_count);
      if v_new_total > v_limit then
        return jsonb_build_object('status', 'word_limit_blocked', 'limit', v_limit);
      end if;
    end if;
  end if;

  select coalesce(max(s.position) + 1, 0) into v_position
    from public.scenes s
   where s.manuscript_id = p_manuscript_id and s.chapter_id is null;

  insert into public.scenes (manuscript_id, chapter_id, title, content, word_count, position)
  values (p_manuscript_id, null, p_title, p_content, p_word_count, v_position)
  returning * into v_new;

  return jsonb_build_object('status', 'ok', 'id', v_new.id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.list_manuscript_milestones(p_manuscript_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;
  if not exists (select 1 from public.manuscripts m join public.projects p on p.id = m.project_id
                  where m.id = p_manuscript_id and p.user_id = auth.uid()) then
    return jsonb_build_object('status', 'error', 'error', 'Manuscript not found');
  end if;
  return jsonb_build_object('status', 'ok', 'milestones', coalesce((
    select jsonb_agg(jsonb_build_object('id', ml.id, 'name', ml.name, 'created_at', ml.created_at,
                                        'manuscript_words', ml.manuscript_words, 'unplaced_words', ml.unplaced_words,
                                        'scene_count', ml.scene_count)
                     order by ml.created_at desc, ml.id desc)
      from public.manuscript_milestones ml where ml.manuscript_id = p_manuscript_id), '[]'::jsonb));
end;
$function$;

CREATE OR REPLACE FUNCTION public.list_object_milestones(p_type text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_manuscript_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if p_type = 'scene' then
    select s.manuscript_id into v_manuscript_id
      from public.scenes s
      join public.manuscripts m on m.id = s.manuscript_id
      join public.projects p on p.id = m.project_id
     where s.id = p_id and p.user_id = auth.uid();
    if not found then
      return jsonb_build_object('status', 'error', 'error', 'Scene not found');
    end if;
    return jsonb_build_object('status', 'ok', 'milestones', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', ml.id, 'name', ml.name, 'created_at', ml.created_at,
               'chapter_id', ms.chapter_id,
               'chapter_title', (select c ->> 'title' from jsonb_array_elements(ml.structure -> 'chapters') c
                                  where c ->> 'id' = ms.chapter_id::text limit 1),
               'title', r.title, 'word_count', r.word_count)
             order by ml.created_at desc, ml.id desc)
        from public.manuscript_milestone_scenes ms
        join public.manuscript_milestones ml on ml.id = ms.milestone_id
        join public.scene_revisions r on r.id = ms.revision_id
       where ms.scene_id = p_id and ml.manuscript_id = v_manuscript_id), '[]'::jsonb));
  end if;

  if p_type = 'chapter' then
    select c.manuscript_id into v_manuscript_id
      from public.chapters c
      join public.manuscripts m on m.id = c.manuscript_id
      join public.projects p on p.id = m.project_id
     where c.id = p_id and p.user_id = auth.uid();
    if not found then
      return jsonb_build_object('status', 'error', 'error', 'Chapter not found');
    end if;
    return jsonb_build_object('status', 'ok', 'milestones', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', ml.id, 'name', ml.name, 'created_at', ml.created_at,
               'chapter_id', p_id,
               'chapter_title', (select c ->> 'title' from jsonb_array_elements(ml.structure -> 'chapters') c
                                  where c ->> 'id' = p_id::text limit 1),
               'scene_count', (select count(*)::int from public.manuscript_milestone_scenes ms
                                where ms.milestone_id = ml.id and ms.chapter_id = p_id),
               'word_count', (select coalesce(sum(r.word_count), 0)::int
                                from public.manuscript_milestone_scenes ms
                                join public.scene_revisions r on r.id = ms.revision_id
                               where ms.milestone_id = ml.id and ms.chapter_id = p_id))
             order by ml.created_at desc, ml.id desc)
        from public.manuscript_milestones ml
       where ml.manuscript_id = v_manuscript_id
         and ml.structure -> 'chapters' @> jsonb_build_array(jsonb_build_object('id', p_id))), '[]'::jsonb));
  end if;

  return jsonb_build_object('status', 'error', 'error', 'Unknown item type');
end;
$function$;

CREATE OR REPLACE FUNCTION public.list_scene_history(p_scene_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_scene public.scenes%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;
  select s.* into v_scene
    from public.scenes s
    join public.manuscripts m on m.id = s.manuscript_id
    join public.projects p on p.id = m.project_id
   where s.id = p_scene_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Scene not found');
  end if;
  if v_scene.trashed_at is not null then
    return jsonb_build_object('status', 'error', 'error', 'Restore this scene from Trash first');
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'scene', jsonb_build_object('id', v_scene.id, 'title', v_scene.title, 'version', v_scene.version,
                                'word_count', v_scene.word_count, 'updated_at', v_scene.updated_at),
    'revisions', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', r.id, 'title', r.title, 'word_count', r.word_count,
               'saved_at', r.saved_at, 'created_at', r.created_at, 'reason', r.reason,
               'current', r.content is not distinct from v_scene.content,
               'milestones', coalesce((select jsonb_agg(ml.name order by ml.created_at)
                                         from public.manuscript_milestone_scenes ms
                                         join public.manuscript_milestones ml on ml.id = ms.milestone_id
                                        where ms.revision_id = r.id), '[]'::jsonb))
             order by r.saved_at desc, r.created_at desc, r.id desc)
        from public.scene_revisions r
       where r.scene_id = v_scene.id), '[]'::jsonb));
end;
$function$;

CREATE OR REPLACE FUNCTION public.list_workspace_trash(p_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not exists (select 1 from public.projects p where p.id = p_project_id and p.user_id = auth.uid()) then
    return jsonb_build_object('status', 'error', 'error', 'Project not found');
  end if;

  return jsonb_build_object('status', 'ok', 'items', coalesce((
    select jsonb_agg(to_jsonb(t) order by t.trashed_at desc, t.id)
      from (
        select 'page' as type, d.id, d.title, d.trashed_at,
               d.trashed_from_folder_id as from_folder_id, ff.title as from_folder_title,
               (ff.id is not null and ff.trashed_at is null) as from_folder_active,
               null::uuid as collection_id, null::text as collection_title, null::boolean as collection_active,
               null::integer as entries, null::integer as properties,
               null::uuid as from_chapter_id, null::text as from_chapter_title, null::boolean as from_chapter_active,
               null::uuid as from_group_id, null::text as from_group_title, null::boolean as from_group_active,
               null::integer as scenes, null::integer as words
          from public.workspace_documents d
          left join public.workspace_folders ff on ff.id = d.trashed_from_folder_id
         where d.project_id = p_project_id and d.trashed_at is not null
        union all
        select 'folder', f.id, f.title, f.trashed_at,
               f.trashed_from_folder_id, ff.title, (ff.id is not null and ff.trashed_at is null),
               null, null, null, null, null, null, null, null, null, null, null, null, null
          from public.workspace_folders f
          left join public.workspace_folders ff on ff.id = f.trashed_from_folder_id
         where f.project_id = p_project_id and f.trashed_at is not null
        union all
        select 'collection', c.id, c.title, c.trashed_at,
               c.trashed_from_folder_id, ff.title, (ff.id is not null and ff.trashed_at is null),
               null, null, null,
               (select count(*)::integer from public.workspace_collection_entries e where e.collection_id = c.id),
               (select count(*)::integer from public.workspace_collection_properties pr
                 where pr.relation_collection_id = c.id and pr.collection_id <> c.id)
                 + (select count(*)::integer from public.scene_property_definitions sp where sp.relation_collection_id = c.id),
               null, null, null, null, null, null, null, null
          from public.workspace_collections c
          left join public.workspace_folders ff on ff.id = c.trashed_from_folder_id
         where c.project_id = p_project_id and c.trashed_at is not null
        union all
        select 'entry', e.id, e.title, e.trashed_at,
               null, null, null,
               c.id, c.title, c.trashed_at is null,
               null, null, null, null, null, null, null, null, null, null
          from public.workspace_collection_entries e
          join public.workspace_collections c on c.id = e.collection_id
         where e.project_id = p_project_id and e.trashed_at is not null
        union all
        select 'scene', s.id, s.title, s.trashed_at,
               null, null, null, null, null, null, null, null,
               s.trashed_from_chapter_id, ch.title, (ch.id is not null and ch.trashed_at is null),
               null, null, null, null, s.word_count
          from public.scenes s
          join public.manuscripts m on m.id = s.manuscript_id
          left join public.chapters ch on ch.id = s.trashed_from_chapter_id and ch.manuscript_id = s.manuscript_id
         where m.project_id = p_project_id and s.trashed_at is not null and not s.trashed_with_chapter
        union all
        select 'chapter', ch.id, ch.title, ch.trashed_at,
               null, null, null, null, null, null, null, null, null, null, null,
               ch.trashed_from_group_id, g.title, g.id is not null,
               (select count(*)::integer from public.scenes s
                 where s.trashed_with_chapter and s.trashed_from_chapter_id = ch.id),
               (select coalesce(sum(s.word_count), 0)::integer from public.scenes s
                 where s.trashed_with_chapter and s.trashed_from_chapter_id = ch.id)
          from public.chapters ch
          join public.manuscripts m on m.id = ch.manuscript_id
          left join public.manuscript_groups g on g.id = ch.trashed_from_group_id and g.manuscript_id = ch.manuscript_id
         where m.project_id = p_project_id and ch.trashed_at is not null
      ) t), '[]'::jsonb));
end;
$function$;

CREATE OR REPLACE FUNCTION public.lock_account_word_budget()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  perform pg_advisory_xact_lock(('x' || substr(md5(auth.uid()::text), 1, 16))::bit(64)::bigint);
end;
$function$;

CREATE OR REPLACE FUNCTION public.lock_project_workspace(p_project_id uuid)
 RETURNS void
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  select pg_advisory_xact_lock(('x' || substr(md5('rune.workspace:' || p_project_id::text), 1, 16))::bit(64)::bigint);
$function$;

CREATE OR REPLACE FUNCTION public.manuscript_scene_view_fields(p_manuscript_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select coalesce((select jsonb_agg(jsonb_build_object('id', p.id::text, 'type', p.type, 'options', p.options,
                                                       'relation_target', p.relation_target) order by p.position)
                     from public.scene_property_definitions p
                    where p.manuscript_id = p_manuscript_id), '[]'::jsonb)
      || jsonb_build_array(
           jsonb_build_object('id', 'words', 'type', 'number', 'native', true),
           jsonb_build_object('id', 'placement', 'type', 'select', 'native', true,
                              'options', '[{"id": "placed", "name": "Placed"}, {"id": "unplaced", "name": "Unplaced"}]'::jsonb),
           jsonb_build_object('id', 'manuscript', 'type', 'position', 'native', true));
$function$;

CREATE OR REPLACE FUNCTION public.move_chapter(p_chapter_id uuid, p_parent_group_id uuid, p_index integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_chapter public.chapters%rowtype;
  v_parent_manuscript_id uuid;
begin
  perform public.lock_account_word_budget();

  select c.* into v_chapter
    from public.chapters c
    join public.manuscripts m on m.id = c.manuscript_id
    join public.projects p on p.id = m.project_id
   where c.id = p_chapter_id and p.user_id = auth.uid() and c.trashed_at is null;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Chapter not found');
  end if;

  if p_parent_group_id is not null then
    select g.manuscript_id into v_parent_manuscript_id
      from public.manuscript_groups g
      join public.manuscripts m on m.id = g.manuscript_id
      join public.projects p on p.id = m.project_id
     where g.id = p_parent_group_id and p.user_id = auth.uid();
    if not found then
      return jsonb_build_object('status', 'error', 'error', 'Group not found');
    end if;
    if v_parent_manuscript_id <> v_chapter.manuscript_id then
      return jsonb_build_object('status', 'error', 'error', 'A Chapter can only move within its own manuscript');
    end if;
  end if;

  return jsonb_build_object('status', 'ok', 'moved',
    public.place_in_manuscript_structure(v_chapter.manuscript_id, p_parent_group_id, 'chapter', p_chapter_id, p_index));
end;
$function$;

CREATE OR REPLACE FUNCTION public.move_manuscript_group(p_group_id uuid, p_parent_group_id uuid, p_index integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_group public.manuscript_groups%rowtype;
  v_parent_manuscript_id uuid;
begin
  perform public.lock_account_word_budget();

  select g.* into v_group
    from public.manuscript_groups g
    join public.manuscripts m on m.id = g.manuscript_id
    join public.projects p on p.id = m.project_id
   where g.id = p_group_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Group not found');
  end if;

  if p_parent_group_id is not null then
    select g.manuscript_id into v_parent_manuscript_id
      from public.manuscript_groups g
      join public.manuscripts m on m.id = g.manuscript_id
      join public.projects p on p.id = m.project_id
     where g.id = p_parent_group_id and p.user_id = auth.uid();
    if not found then
      return jsonb_build_object('status', 'error', 'error', 'Group not found');
    end if;
    if v_parent_manuscript_id <> v_group.manuscript_id then
      return jsonb_build_object('status', 'error', 'error', 'A Group can only move within its own manuscript');
    end if;
    if exists (
         with recursive up(id) as (
           select p_parent_group_id
           union
           select g.parent_group_id from public.manuscript_groups g join up on g.id = up.id
            where g.parent_group_id is not null)
         select 1 from up where up.id = p_group_id) then
      return jsonb_build_object('status', 'error', 'error', 'A Group cannot move inside itself');
    end if;
  end if;

  return jsonb_build_object('status', 'ok', 'moved',
    public.place_in_manuscript_structure(v_group.manuscript_id, p_parent_group_id, 'group', p_group_id, p_index));
end;
$function$;

CREATE OR REPLACE FUNCTION public.move_scene(p_scene_id uuid, p_chapter_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_scene public.scenes%rowtype;
  v_chapter_manuscript_id uuid;
  v_position int;
begin
  perform public.lock_account_word_budget();

  -- RLS: another writer's Scene is invisible.
  select * into v_scene from public.scenes s where s.id = p_scene_id for update;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Scene not found');
  end if;

  if p_chapter_id is not null then
    -- RLS: another writer's Chapter is invisible.
    select c.manuscript_id into v_chapter_manuscript_id
      from public.chapters c where c.id = p_chapter_id;
    if not found then
      return jsonb_build_object('status', 'error', 'error', 'Chapter not found');
    end if;
    if v_chapter_manuscript_id <> v_scene.manuscript_id then
      return jsonb_build_object('status', 'error', 'error', 'A Scene can only move within its own manuscript');
    end if;
  end if;

  if v_scene.chapter_id is not distinct from p_chapter_id then
    return jsonb_build_object('status', 'ok', 'moved', false);
  end if;

  if p_chapter_id is null then
    select coalesce(max(s.position) + 1, 0) into v_position
      from public.scenes s
     where s.manuscript_id = v_scene.manuscript_id and s.chapter_id is null;
  else
    select coalesce(max(s.position) + 1, 0) into v_position
      from public.scenes s
     where s.chapter_id = p_chapter_id;
  end if;

  -- scenes_refresh_project_word_count recomputes projects.word_count.
  update public.scenes
     set chapter_id = p_chapter_id, position = v_position
   where id = p_scene_id;

  if p_chapter_id is not null then
    update public.chapters set updated_at = now() where id = p_chapter_id;
  end if;

  return jsonb_build_object('status', 'ok', 'moved', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.move_scene_property(p_property_id uuid, p_index integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_property public.scene_property_definitions%rowtype;
  v_count integer;
  v_target integer;
begin
  select pr.* into v_property
    from public.scene_property_definitions pr
    join public.projects p on p.id = pr.project_id
   where pr.id = p_property_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Property not found');
  end if;
  perform public.lock_project_workspace(v_property.project_id);

  select count(*) into v_count from public.scene_property_definitions p where p.manuscript_id = v_property.manuscript_id;
  v_target := greatest(0, least(coalesce(p_index, v_count - 1), v_count - 1)) + 1;

  -- One statement: the others close up around the moved one (position is
  -- unique, checked at commit).
  update public.scene_property_definitions p
     set position = o.next
    from (
      select id, row_number() over (order by (id = p_property_id), position) as rank
        from public.scene_property_definitions
       where manuscript_id = v_property.manuscript_id
    ) r
    cross join lateral (
      select case
               when r.id = p_property_id then v_target
               when r.rank < v_target then r.rank
               else r.rank + 1
             end as next
    ) o
   where p.id = r.id and p.position <> o.next;

  select * into v_property from public.scene_property_definitions where id = p_property_id;
  return jsonb_build_object('status', 'ok', 'property', to_jsonb(v_property));
end;
$function$;

CREATE OR REPLACE FUNCTION public.move_scene_view(p_view_id uuid, p_index integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_view public.scene_views%rowtype;
  v_count integer;
  v_target integer;
begin
  select v.* into v_view
    from public.scene_views v
    join public.projects p on p.id = v.project_id
   where v.id = p_view_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'View not found');
  end if;
  perform public.lock_project_workspace(v_view.project_id);

  select count(*) into v_count from public.scene_views v
   where v.manuscript_id = v_view.manuscript_id and v.group_id is not distinct from v_view.group_id;
  v_target := greatest(0, least(coalesce(p_index, v_count - 1), v_count - 1)) + 1;

  update public.scene_views v
     set position = o.next
    from (
      select id, row_number() over (order by (id = p_view_id), position) as rank
        from public.scene_views
       where manuscript_id = v_view.manuscript_id and group_id is not distinct from v_view.group_id
    ) r
    cross join lateral (
      select case
               when r.id = p_view_id then v_target
               when r.rank < v_target then r.rank
               else r.rank + 1
             end as next
    ) o
   where v.id = r.id and v.position <> o.next;

  select * into v_view from public.scene_views where id = p_view_id;
  return jsonb_build_object('status', 'ok', 'view', to_jsonb(v_view));
end;
$function$;

