CREATE OR REPLACE FUNCTION public.move_workspace_node(p_node_id uuid, p_parent_node_id uuid, p_index integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_project_id uuid;
  v_parent public.workspace_nodes%rowtype;
begin
  select n.project_id into v_project_id
    from public.workspace_nodes n
    join public.projects p on p.id = n.project_id
   where n.id = p_node_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Item not found');
  end if;
  perform public.lock_project_workspace(v_project_id);

  if p_parent_node_id is not null then
    select n.* into v_parent
      from public.workspace_nodes n
      join public.projects p on p.id = n.project_id
     where n.id = p_parent_node_id and p.user_id = auth.uid();
    if not found then
      return jsonb_build_object('status', 'error', 'error', 'Folder not found');
    end if;
    if v_parent.project_id <> v_project_id then
      return jsonb_build_object('status', 'error', 'error', 'Items can only move within their own Project');
    end if;
    if v_parent.target_type <> 'folder' then
      return jsonb_build_object('status', 'error', 'error', 'Only a Folder can hold other items');
    end if;
    if exists (
         with recursive up(id) as (
           select p_parent_node_id
           union
           select n.parent_node_id from public.workspace_nodes n join up on n.id = up.id
            where n.parent_node_id is not null)
         select 1 from up where up.id = p_node_id) then
      return jsonb_build_object('status', 'error', 'error', 'A Folder cannot move inside itself');
    end if;
  end if;

  return jsonb_build_object('status', 'ok', 'moved',
    public.place_workspace_node(p_node_id, p_parent_node_id, p_index));
end;
$function$;

CREATE OR REPLACE FUNCTION public.next_structure_position(p_manuscript_id uuid, p_parent_group_id uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select coalesce(max(s.position), 0) + 1
    from (select g.position from public.manuscript_groups g
           where g.manuscript_id = p_manuscript_id and g.parent_group_id is not distinct from p_parent_group_id
          union all
          select c.position from public.chapters c
           where c.manuscript_id = p_manuscript_id and c.group_id is not distinct from p_parent_group_id
             and c.trashed_at is null) s;
$function$;

CREATE OR REPLACE FUNCTION public.normalize_workspace_view_config(p_config jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'properties', coalesce(p_config -> 'properties', '[]'::jsonb),
    'sort',       coalesce(p_config -> 'sort', 'null'::jsonb),
    'filters',    coalesce(p_config -> 'filters', '[]'::jsonb),
    'group_by',   coalesce(p_config -> 'group_by', 'null'::jsonb))
    || case when p_config ? 'widths' then jsonb_build_object('widths', p_config -> 'widths') else '{}'::jsonb end
    || case when p_config ? 'axis' then jsonb_build_object('axis', p_config -> 'axis') else '{}'::jsonb end;
$function$;

-- The ordered manuscript total: every placed Scene of the Manuscript. Unplaced
-- Scenes excluded. The one SQL definition; projects.word_count stores it.
CREATE OR REPLACE FUNCTION public.ordered_manuscript_word_total(p_manuscript_id uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select coalesce(sum(s.word_count), 0)::int
    from public.scenes s
   where s.manuscript_id = p_manuscript_id and s.chapter_id is not null;
$function$;

CREATE OR REPLACE FUNCTION public.owned_project_manuscript(p_project_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select m.id
    from public.manuscripts m
    join public.projects p on p.id = m.project_id
   where m.project_id = p_project_id and p.user_id = auth.uid();
$function$;

CREATE OR REPLACE FUNCTION public.owned_workspace_object_project(p_type text, p_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select p.id
    from public.projects p
   where p.user_id = auth.uid()
     and p.id = case p_type
       when 'page' then (select d.project_id from public.workspace_documents d where d.id = p_id)
       when 'folder' then (select f.project_id from public.workspace_folders f where f.id = p_id)
       when 'collection' then (select c.project_id from public.workspace_collections c where c.id = p_id)
       when 'entry' then (select e.project_id from public.workspace_collection_entries e where e.id = p_id)
       when 'scene' then (select m.project_id from public.scenes s join public.manuscripts m on m.id = s.manuscript_id where s.id = p_id)
       when 'chapter' then (select m.project_id from public.chapters c join public.manuscripts m on m.id = c.manuscript_id where c.id = p_id)
     end;
$function$;

CREATE OR REPLACE FUNCTION public.place_in_manuscript_structure(p_manuscript_id uuid, p_parent_group_id uuid, p_kind text, p_id uuid, p_index integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_kinds text[];
  v_ids uuid[];
  v_n int;
  v_i int;
  v_base int;
  v_changed int := 0;
  v_rows int;
begin
  select coalesce(array_agg(s.kind order by s.position, s.kind desc, s.id), '{}'),
         coalesce(array_agg(s.id order by s.position, s.kind desc, s.id), '{}')
    into v_kinds, v_ids
    from (select 'group'::text as kind, g.id, g.position from public.manuscript_groups g
           where g.manuscript_id = p_manuscript_id and g.parent_group_id is not distinct from p_parent_group_id
             and not (p_kind = 'group' and g.id = p_id)
          union all
          select 'chapter'::text, c.id, c.position from public.chapters c
           where c.manuscript_id = p_manuscript_id and c.group_id is not distinct from p_parent_group_id
             and c.trashed_at is null
             and not (p_kind = 'chapter' and c.id = p_id)) s;

  v_n := coalesce(array_length(v_ids, 1), 0);
  v_i := least(greatest(coalesce(p_index, v_n), 0), v_n);
  v_kinds := v_kinds[1:v_i] || p_kind || v_kinds[v_i + 1:v_n];
  v_ids := v_ids[1:v_i] || p_id || v_ids[v_i + 1:v_n];

  -- Above every position the destination or the moving item holds.
  select greatest(coalesce(max(s.position), 0), 0) + v_n + 2 into v_base
    from (select g.position from public.manuscript_groups g where g.id = any(v_ids)
          union all
          select c.position from public.chapters c where c.id = any(v_ids)) s;

  update public.manuscript_groups g
     set parent_group_id = p_parent_group_id, position = v_base + o.ord::int
    from unnest(v_kinds, v_ids) with ordinality as o(kind, id, ord)
   where o.kind = 'group' and g.id = o.id
     and (g.position <> o.ord or g.parent_group_id is distinct from p_parent_group_id);
  get diagnostics v_rows = row_count;
  v_changed := v_changed + v_rows;

  update public.chapters c
     set group_id = p_parent_group_id, position = v_base + o.ord::int
    from unnest(v_kinds, v_ids) with ordinality as o(kind, id, ord)
   where o.kind = 'chapter' and c.id = o.id
     and (c.position <> o.ord or c.group_id is distinct from p_parent_group_id);
  get diagnostics v_rows = row_count;
  v_changed := v_changed + v_rows;

  if v_changed = 0 then
    return false;
  end if;

  update public.manuscript_groups g
     set position = g.position - v_base
   where g.id = any(v_ids) and g.position > v_base;
  update public.chapters c
     set position = c.position - v_base
   where c.id = any(v_ids) and c.position > v_base;

  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION public.place_new_workspace_object()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_type text := case tg_table_name
                   when 'workspace_documents' then 'page'
                   when 'workspace_folders' then 'folder'
                   when 'workspace_collections' then 'collection'
                 end;
begin
  if v_type is null then
    raise exception 'place_new_workspace_object: % is not a Workspace object table', tg_table_name;
  end if;
  perform public.lock_project_workspace(new.project_id);
  insert into public.workspace_nodes (project_id, target_type, document_id, folder_id, collection_id, parent_node_id, position)
  values (new.project_id, v_type,
          case when v_type = 'page' then new.id end,
          case when v_type = 'folder' then new.id end,
          case when v_type = 'collection' then new.id end,
          null,
          (select coalesce(max(n.position), 0) + 1 from public.workspace_nodes n
            where n.project_id = new.project_id and n.parent_node_id is null));
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.place_scene(p_scene_id uuid, p_chapter_id uuid, p_index integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_scene public.scenes%rowtype;
  v_chapter public.chapters%rowtype;
  v_ids uuid[];
  v_n int;
  v_i int;
  v_rows int;
begin
  perform public.lock_account_word_budget();

  select s.* into v_scene
    from public.scenes s
    join public.manuscripts m on m.id = s.manuscript_id
    join public.projects p on p.id = m.project_id
   where s.id = p_scene_id and p.user_id = auth.uid() and s.trashed_at is null
     for update of s;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Scene not found');
  end if;

  if p_chapter_id is not null then
    select c.* into v_chapter
      from public.chapters c
      join public.manuscripts m on m.id = c.manuscript_id
      join public.projects p on p.id = m.project_id
     where c.id = p_chapter_id and p.user_id = auth.uid() and c.trashed_at is null;
    if not found then
      return jsonb_build_object('status', 'error', 'error', 'Chapter not found');
    end if;
    if v_chapter.manuscript_id <> v_scene.manuscript_id then
      return jsonb_build_object('status', 'error', 'error', 'A Scene can only move within its own manuscript');
    end if;
  end if;

  select coalesce(array_agg(x.id order by x.position, x.id), '{}') into v_ids
    from (select s.id, s.position from public.scenes s
           where s.id <> p_scene_id
             and s.trashed_at is null
             and (case when p_chapter_id is null
                       then s.manuscript_id = v_scene.manuscript_id and s.chapter_id is null
                       else s.chapter_id = p_chapter_id end)
             for update) x;

  v_n := coalesce(array_length(v_ids, 1), 0);
  v_i := least(greatest(coalesce(p_index, v_n), 0), v_n);
  v_ids := v_ids[1:v_i] || p_scene_id || v_ids[v_i + 1:v_n];

  update public.scenes s
     set chapter_id = p_chapter_id, position = o.ord::int - 1
    from unnest(v_ids) with ordinality as o(id, ord)
   where s.id = o.id
     and (s.position <> o.ord::int - 1 or s.chapter_id is distinct from p_chapter_id);
  get diagnostics v_rows = row_count;

  if v_rows > 0 and p_chapter_id is not null then
    update public.chapters set updated_at = now() where id = p_chapter_id;
  end if;

  return jsonb_build_object('status', 'ok', 'moved', v_rows > 0,
                            'chapter_changed', v_scene.chapter_id is distinct from p_chapter_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.place_workspace_node(p_node_id uuid, p_parent_node_id uuid, p_index integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_project_id uuid;
  v_old_parent uuid;
  v_ids uuid[];
  v_n int;
  v_i int;
  v_changed int;
begin
  select n.project_id, n.parent_node_id into v_project_id, v_old_parent
    from public.workspace_nodes n where n.id = p_node_id;

  select coalesce(array_agg(n.id order by n.position, n.id), '{}') into v_ids
    from public.workspace_nodes n
   where n.project_id = v_project_id
     and n.parent_node_id is not distinct from p_parent_node_id
     and n.id <> p_node_id;

  v_n := coalesce(array_length(v_ids, 1), 0);
  v_i := least(greatest(coalesce(p_index, v_n), 0), v_n);
  v_ids := v_ids[1:v_i] || p_node_id || v_ids[v_i + 1:v_n];

  update public.workspace_nodes n
     set parent_node_id = p_parent_node_id, position = o.ord::int
    from unnest(v_ids) with ordinality as o(id, ord)
   where n.id = o.id
     and (n.position <> o.ord or n.parent_node_id is distinct from p_parent_node_id);
  get diagnostics v_changed = row_count;

  if v_old_parent is distinct from p_parent_node_id then
    perform public.renumber_workspace_siblings(v_project_id, v_old_parent);
  end if;

  return v_changed > 0;
end;
$function$;

CREATE OR REPLACE FUNCTION public.protect_billing_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.role() = 'authenticated' then
    if new.subscription_tier is distinct from old.subscription_tier then
      new.subscription_tier := old.subscription_tier;
    end if;
    if new.subscription_status is distinct from old.subscription_status then
      new.subscription_status := old.subscription_status;
    end if;
    if new.subscription_price_id is distinct from old.subscription_price_id then
      new.subscription_price_id := old.subscription_price_id;
    end if;
    if new.subscription_period_end is distinct from old.subscription_period_end then
      new.subscription_period_end := old.subscription_period_end;
    end if;
    if new.stripe_customer_id is distinct from old.stripe_customer_id then
      new.stripe_customer_id := old.stripe_customer_id;
    end if;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.protect_is_admin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.role() = 'authenticated' and new.is_admin is distinct from old.is_admin then
    new.is_admin := old.is_admin;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.protect_project_word_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.word_count is distinct from old.word_count
     and current_user in ('anon', 'authenticated') then
    raise exception 'projects.word_count is maintained by the database'
      using errcode = '42501';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.protect_structure_placement()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if current_user not in ('anon', 'authenticated') then
    return new;
  end if;
  -- Nested, not AND-ed: each table's record has only its own columns.
  if tg_table_name = 'chapters' then
    if new.group_id is distinct from old.group_id or new.position is distinct from old.position then
      raise exception 'A Chapter''s place in the manuscript changes only through move_chapter'
        using errcode = '42501';
    end if;
  elsif new.parent_group_id is distinct from old.parent_group_id or new.position is distinct from old.position then
    raise exception 'A Group''s place in the manuscript changes only through move_manuscript_group'
      using errcode = '42501';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.prune_scene_revisions(p_scene_id uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  delete from public.scene_revisions r
   using (select r2.id,
                 r2.created_at,
                 row_number() over (partition by (r2.created_at at time zone 'UTC')::date
                                    order by r2.created_at desc, r2.id desc) as day_rank,
                 row_number() over (order by r2.created_at desc, r2.id desc) as recency
            from public.scene_revisions r2
           where r2.scene_id = p_scene_id
             and not exists (select 1 from public.manuscript_milestone_scenes ms where ms.revision_id = r2.id)) k
   where r.id = k.id
     and (k.recency > 200 or (k.created_at < now() - interval '30 days' and k.day_rank > 1));
$function$;

CREATE OR REPLACE FUNCTION public.prune_scene_view_config(p_manuscript_id uuid, p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
begin
  return public.prune_view_config(public.manuscript_scene_view_fields(p_manuscript_id), p_config);
end;
$function$;

CREATE OR REPLACE FUNCTION public.prune_view_config(p_fields jsonb, p_config jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  with c as (select public.normalize_workspace_view_config(p_config) as v),
  fields as (
    select f ->> 'id' as id, f ->> 'type' as type, coalesce(f -> 'options', '[]'::jsonb) as options,
           f ->> 'relation_target' as relation_target, coalesce((f ->> 'native')::boolean, false) as native
      from jsonb_array_elements(coalesce(p_fields, '[]'::jsonb)) f
  )
  select jsonb_build_object(
    'properties', coalesce((
        select jsonb_agg(x order by i)
          from c, jsonb_array_elements(c.v -> 'properties') with ordinality as t(x, i)
         where exists (select 1 from fields where fields.id = x #>> '{}' and fields.type <> 'position')), '[]'::jsonb),
    'sort', (
        select case
                 when jsonb_typeof(c.v -> 'sort') <> 'object' then 'null'::jsonb
                 when c.v -> 'sort' ->> 'by' = 'title' then c.v -> 'sort'
                 when exists (select 1 from fields where fields.id = c.v -> 'sort' ->> 'by'
                                 and fields.type in ('text', 'number', 'select', 'status', 'date', 'checkbox'))
                   then c.v -> 'sort'
                 else 'null'::jsonb
               end
          from c),
    'filters', coalesce((
        select jsonb_agg(f order by i)
          from c, jsonb_array_elements(c.v -> 'filters') with ordinality as t(f, i)
         where exists (
                 select 1 from fields
                  where fields.id = f ->> 'property'
                    and (   ((f ->> 'op') in ('is_empty', 'is_not_empty') and not fields.native)
                         or ((f ->> 'op') in ('is', 'is_not') and fields.type in ('select', 'status', 'multi_select')
                             and exists (select 1 from jsonb_array_elements(fields.options) o where o -> 'id' = f -> 'value'))
                         or ((f ->> 'op') in ('is', 'is_not') and fields.type = 'relationship'
                             and (f ->> 'value') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
                         or ((f ->> 'op') = 'contains' and fields.type = 'text'
                             and btrim(f ->> 'value') <> '' and char_length(f ->> 'value') <= 200)
                         or ((f ->> 'op') in ('gt', 'lt') and fields.type = 'number' and jsonb_typeof(f -> 'value') = 'number')
                         or ((f ->> 'op') in ('gt', 'lt') and fields.type = 'date' and jsonb_typeof(f -> 'value') = 'string'
                             and (f ->> 'value') ~ '^\d{4}-\d{2}-\d{2}$')))), '[]'::jsonb),
    'group_by', (
        select case
                 when exists (select 1 from fields
                               where fields.id = c.v ->> 'group_by' and not fields.native
                                 and (fields.type in ('select', 'status')
                                      or (fields.type = 'relationship' and fields.relation_target = 'entry')))
                   then c.v -> 'group_by'
                 else 'null'::jsonb
               end
          from c))
    -- widths: kept only for the name column and fields that exist; the key
    -- is present exactly when the config had it.
    || case when c.v ? 'widths' then jsonb_build_object('widths', coalesce((
         select jsonb_object_agg(w.key, w.value)
           from jsonb_each(c.v -> 'widths') w
          where w.key = 'title' or exists (select 1 from fields where fields.id = w.key)), '{}'::jsonb))
       else '{}'::jsonb end
    -- axis: a number or date field, or the manuscript position; the key is
    -- present exactly when the config had it.
    || case when c.v ? 'axis' then jsonb_build_object('axis', (
         select case
                  when exists (select 1 from fields where fields.id = c.v ->> 'axis'
                                  and ((fields.type in ('number', 'date') and not fields.native) or fields.type = 'position'))
                    then c.v -> 'axis'
                  else 'null'::jsonb
                end))
       else '{}'::jsonb end
  from c;
$function$;

CREATE OR REPLACE FUNCTION public.prune_workspace_view_config(p_collection_id uuid, p_config jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select public.prune_view_config(
    coalesce((select jsonb_agg(jsonb_build_object('id', p.id::text, 'type', p.type, 'options', p.options,
                                                  'relation_target', p.relation_target))
                from public.workspace_collection_properties p
               where p.collection_id = p_collection_id), '[]'::jsonb),
    p_config);
$function$;

CREATE OR REPLACE FUNCTION public.read_project_backup(p_project_id uuid, p_kind text, p_after text DEFAULT NULL::text, p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_manuscript_id uuid;
  v_limit integer := greatest(1, least(coalesce(p_limit, 200), 500));
  v_table text;
  v_filter text;
  v_keys text[];
  v_order text;
  v_after text;
  v_cursor text;
  v_rows jsonb;
  v_count integer;
  v_last text;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select m.id into v_manuscript_id
    from public.projects p
    join public.manuscripts m on m.project_id = p.id
   where p.id = p_project_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Project not found');
  end if;

  -- The kind → (table, rows of this Project, key columns). Constants only.
  case p_kind
    when 'groups' then v_table := 'manuscript_groups'; v_filter := 't.manuscript_id = $2'; v_keys := array['id'];
    when 'chapters' then v_table := 'chapters'; v_filter := 't.manuscript_id = $2'; v_keys := array['id'];
    when 'scenes' then v_table := 'scenes'; v_filter := 't.manuscript_id = $2'; v_keys := array['id'];
    when 'scene_property_definitions' then v_table := 'scene_property_definitions'; v_filter := 't.manuscript_id = $2'; v_keys := array['id'];
    when 'scene_property_values' then v_table := 'scene_property_values'; v_filter := 't.manuscript_id = $2'; v_keys := array['scene_id', 'property_id'];
    when 'scene_views' then v_table := 'scene_views'; v_filter := 't.manuscript_id = $2'; v_keys := array['id'];
    when 'revision_notes' then v_table := 'revision_notes'; v_filter := 't.project_id = $1'; v_keys := array['id'];
    when 'scene_revisions' then v_table := 'scene_revisions'; v_filter := 't.manuscript_id = $2'; v_keys := array['id'];
    when 'milestones' then v_table := 'manuscript_milestones'; v_filter := 't.manuscript_id = $2'; v_keys := array['id'];
    when 'milestone_scenes' then
      v_table := 'manuscript_milestone_scenes';
      v_filter := 't.milestone_id in (select ml.id from public.manuscript_milestones ml where ml.manuscript_id = $2)';
      v_keys := array['milestone_id', 'scene_id'];
    when 'workspace_nodes' then v_table := 'workspace_nodes'; v_filter := 't.project_id = $1'; v_keys := array['id'];
    when 'workspace_folders' then v_table := 'workspace_folders'; v_filter := 't.project_id = $1'; v_keys := array['id'];
    when 'workspace_documents' then v_table := 'workspace_documents'; v_filter := 't.project_id = $1'; v_keys := array['id'];
    when 'workspace_collections' then v_table := 'workspace_collections'; v_filter := 't.project_id = $1'; v_keys := array['id'];
    when 'workspace_collection_properties' then v_table := 'workspace_collection_properties'; v_filter := 't.project_id = $1'; v_keys := array['id'];
    when 'workspace_collection_views' then v_table := 'workspace_collection_views'; v_filter := 't.project_id = $1'; v_keys := array['id'];
    when 'workspace_collection_entries' then v_table := 'workspace_collection_entries'; v_filter := 't.project_id = $1'; v_keys := array['id'];
    when 'workspace_entry_values' then v_table := 'workspace_entry_values'; v_filter := 't.project_id = $1'; v_keys := array['entry_id', 'property_id'];
    when 'object_references' then v_table := 'object_references'; v_filter := 't.project_id = $1'; v_keys := array['id'];
    when 'writing_sessions' then v_table := 'writing_sessions'; v_filter := 't.project_id = $1 and t.user_id = auth.uid()'; v_keys := array['id'];
    when 'writing_goals' then v_table := 'writing_goals'; v_filter := 't.project_id = $1 and t.user_id = auth.uid()'; v_keys := array['id'];
    when 'project_notes' then v_table := 'project_notes'; v_filter := 't.project_id = $1 and t.user_id = auth.uid()'; v_keys := array['id'];
    else
      return jsonb_build_object('status', 'error', 'error', 'Unknown kind');
  end case;

  -- Keyset paging: rows after the cursor (the last row's key, "a" or "a:b").
  v_order := array_to_string(array(select 't.' || quote_ident(k) from unnest(v_keys) k), ', ');
  v_cursor := array_to_string(array(select 't.' || quote_ident(k) || '::text' from unnest(v_keys) k), ' || '':'' || ');
  if p_after is not null then
    v_after := format('(%s) > (%s)', v_order,
      array_to_string(array(select format('split_part($3, '':'', %s)::uuid', i) from generate_subscripts(v_keys, 1) i), ', '));
  else
    v_after := 'true';
  end if;

  execute format(
    'select coalesce(jsonb_agg(to_jsonb(t) order by %1$s), ''[]''::jsonb), count(*)::int, max(%2$s)
       from (select * from public.%3$I t where %4$s and %5$s order by %1$s limit %6$s) t',
    v_order, v_cursor, v_table, v_filter, v_after, v_limit)
    into v_rows, v_count, v_last
    using p_project_id, v_manuscript_id, p_after;

  return jsonb_build_object(
    'status', 'ok',
    'rows', v_rows,
    'next', case when v_count = v_limit then v_last else null end);
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_scene_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_restore boolean := coalesce(current_setting('rune.scene_restore', true), '') = old.id::text;
  v_latest public.scene_revisions%rowtype;
begin
  begin
    if old.word_count <= 0 or old.content is null then
      return null;
    end if;
    select r.* into v_latest
      from public.scene_revisions r
     where r.scene_id = old.id
     order by r.created_at desc, r.id desc
     limit 1;
    if found and v_latest.content = old.content then
      return null;
    end if;
    if not v_restore
       and now() - old.updated_at < interval '30 minutes'
       and now() - coalesce(v_latest.created_at, old.created_at) < interval '60 minutes' then
      return null;
    end if;
    insert into public.scene_revisions (manuscript_id, scene_id, title, content, word_count, saved_at, reason)
    values (old.manuscript_id, old.id, old.title, old.content, old.word_count, old.updated_at,
            case when v_restore then 'restore' else 'checkpoint' end);
    perform public.prune_scene_revisions(old.id);
  exception when others then
    -- The writer's text is saved regardless; only this checkpoint is missed.
    raise warning 'Scene history for % was not recorded (%)', old.id, sqlstate;
  end;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.reference_object_project(p_type text, p_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select case p_type
    when 'entry' then (select e.project_id from public.workspace_collection_entries e where e.id = p_id)
    when 'page'  then (select d.project_id from public.workspace_documents d where d.id = p_id)
    when 'scene' then (select m.project_id from public.scenes s join public.manuscripts m on m.id = s.manuscript_id where s.id = p_id)
    when 'chapter' then (select m.project_id from public.chapters c join public.manuscripts m on m.id = c.manuscript_id where c.id = p_id)
  end;
$function$;

CREATE OR REPLACE FUNCTION public.refresh_project_word_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_manuscript_id uuid;
  v_project_id uuid;
  v_total int;
begin
  -- Only a change to this row's placed words can change the ordered total.
  if tg_op = 'INSERT' then
    if new.chapter_id is null or new.word_count = 0 then return null; end if;
    v_manuscript_id := new.manuscript_id;
  elsif tg_op = 'DELETE' then
    if old.chapter_id is null or old.word_count = 0 then return null; end if;
    v_manuscript_id := old.manuscript_id;
  else
    if (case when old.chapter_id is null then 0 else old.word_count end)
       = (case when new.chapter_id is null then 0 else new.word_count end) then
      return null;
    end if;
    v_manuscript_id := new.manuscript_id;
  end if;

  select m.project_id into v_project_id
    from public.manuscripts m where m.id = v_manuscript_id;
  if v_project_id is null then return null; end if; -- the Project is being deleted

  -- Lock first; the total is read by the NEXT statement, whose snapshot then
  -- includes every change committed by the previous lock holder.
  perform 1 from public.projects p where p.id = v_project_id for update;
  v_total := public.ordered_manuscript_word_total(v_manuscript_id);

  update public.projects p
     set word_count = v_total
   where p.id = v_project_id and p.word_count <> v_total;

  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.remove_object_reference(p_reference_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_reference public.object_references%rowtype;
begin
  select r.* into v_reference
    from public.object_references r
    join public.projects p on p.id = r.project_id
   where r.id = p_reference_id and p.user_id = auth.uid() and r.property_id is null and r.scene_property_id is null
     and r.origin = 'link';
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Reference not found');
  end if;
  perform public.lock_project_workspace(v_reference.project_id);
  delete from public.object_references r where r.id = p_reference_id;
  return jsonb_build_object('status', 'ok');
end;
$function$;

CREATE OR REPLACE FUNCTION public.renumber_workspace_siblings(p_project_id uuid, p_parent_node_id uuid)
 RETURNS void
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  update public.workspace_nodes n
     set position = o.ord
    from (select s.id, row_number() over (order by s.position, s.id)::int as ord
            from public.workspace_nodes s
           where s.project_id = p_project_id
             and s.parent_node_id is not distinct from p_parent_node_id) o
   where n.id = o.id and n.position <> o.ord;
$function$;

CREATE OR REPLACE FUNCTION public.reorder_chapter_scenes(p_chapter_id uuid, p_scene_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_current uuid[];
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  -- RLS: another writer's Chapter is invisible.
  if not exists (select 1 from public.chapters c where c.id = p_chapter_id) then
    return jsonb_build_object('status', 'error', 'error', 'Chapter not found');
  end if;

  -- Lock the Chapter's Scenes so a concurrent reorder or move-out waits.
  select coalesce(array_agg(s.id order by s.id), '{}')
    into v_current
    from (select id from public.scenes where chapter_id = p_chapter_id for update) s;

  if coalesce(array_length(p_scene_ids, 1), 0) <> coalesce(array_length(v_current, 1), 0)
     or (select count(distinct x) from unnest(p_scene_ids) x) <> coalesce(array_length(v_current, 1), 0)
     or not (p_scene_ids <@ v_current) then
    return jsonb_build_object('status', 'stale');
  end if;

  update public.scenes s
     set position = o.ord - 1
    from unnest(p_scene_ids) with ordinality as o(id, ord)
   where s.id = o.id
     and s.chapter_id = p_chapter_id
     and s.position is distinct from (o.ord - 1)::int;

  return jsonb_build_object('status', 'ok');
end;
$function$;

CREATE OR REPLACE FUNCTION public.restore_manuscript_chapter(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_chapter public.chapters%rowtype;
  v_parent uuid;
begin
  perform public.lock_account_word_budget();
  select c.* into v_chapter
    from public.chapters c
    join public.manuscripts m on m.id = c.manuscript_id
    join public.projects p on p.id = m.project_id
   where c.id = p_id and p.user_id = auth.uid()
     for update of c;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Item not found');
  end if;
  if v_chapter.trashed_at is null then
    return jsonb_build_object('status', 'error', 'error', 'Not in Trash');
  end if;

  select g.id into v_parent
    from public.manuscript_groups g
   where g.id = v_chapter.trashed_from_group_id and g.manuscript_id = v_chapter.manuscript_id;

  -- Active again, at the end of its parent; then into its old place.
  update public.chapters
     set trashed_at = null, trashed_from_group_id = null, trashed_from_index = null,
         group_id = v_parent, position = public.next_structure_position(v_chapter.manuscript_id, v_parent)
   where id = p_id;
  if v_parent is not null or v_chapter.trashed_from_group_id is null then
    perform public.place_in_manuscript_structure(v_chapter.manuscript_id, v_parent, 'chapter', p_id,
                                                 v_chapter.trashed_from_index);
  end if;

  -- Its Scenes come back inside it, in their order.
  update public.scenes
     set trashed_at = null, trashed_from_chapter_id = null, trashed_with_chapter = false, chapter_id = p_id
   where trashed_with_chapter and trashed_from_chapter_id = p_id and manuscript_id = v_chapter.manuscript_id;

  return jsonb_build_object('status', 'ok',
    'location', case when v_chapter.trashed_from_group_id is not null and v_parent is null then 'top' else 'original' end);
end;
$function$;

CREATE OR REPLACE FUNCTION public.restore_manuscript_scene(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_scene public.scenes%rowtype;
  v_chapter uuid;
  v_position integer;
begin
  perform public.lock_account_word_budget();
  select s.* into v_scene
    from public.scenes s
    join public.manuscripts m on m.id = s.manuscript_id
    join public.projects p on p.id = m.project_id
   where s.id = p_id and p.user_id = auth.uid()
     for update of s;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Item not found');
  end if;
  if v_scene.trashed_at is null then
    return jsonb_build_object('status', 'error', 'error', 'Not in Trash');
  end if;
  if v_scene.trashed_with_chapter then
    return jsonb_build_object('status', 'error', 'error', 'Restore its chapter first');
  end if;

  select c.id into v_chapter
    from public.chapters c
   where c.id = v_scene.trashed_from_chapter_id and c.manuscript_id = v_scene.manuscript_id
     and c.trashed_at is null
     for update;

  if v_chapter is not null then
    if exists (select 1 from public.scenes s where s.chapter_id = v_chapter and s.position = v_scene.position) then
      select coalesce(max(s.position) + 1, 0) into v_position from public.scenes s where s.chapter_id = v_chapter;
    else
      v_position := v_scene.position;
    end if;
  else
    if exists (select 1 from public.scenes s
                where s.manuscript_id = v_scene.manuscript_id and s.chapter_id is null
                  and s.trashed_at is null and s.position = v_scene.position) then
      select coalesce(max(s.position) + 1, 0) into v_position
        from public.scenes s
       where s.manuscript_id = v_scene.manuscript_id and s.chapter_id is null and s.trashed_at is null;
    else
      v_position := v_scene.position;
    end if;
  end if;

  update public.scenes
     set trashed_at = null, trashed_from_chapter_id = null, chapter_id = v_chapter, position = v_position
   where id = p_id;
  if v_chapter is not null then
    update public.chapters set updated_at = now() where id = v_chapter;
  end if;

  return jsonb_build_object('status', 'ok',
    'location', case when v_scene.trashed_from_chapter_id is not null and v_chapter is null then 'unplaced' else 'original' end);
end;
$function$;

CREATE OR REPLACE FUNCTION public.restore_scene_revision(p_revision_id uuid, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_rev public.scene_revisions%rowtype;
  v_scene public.scenes%rowtype;
  v_result jsonb;
begin
  perform public.lock_account_word_budget();
  select r.* into v_rev
    from public.scene_revisions r
    join public.manuscripts m on m.id = r.manuscript_id
    join public.projects p on p.id = m.project_id
   where r.id = p_revision_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Version not found');
  end if;
  if v_rev.scene_id is null then
    return jsonb_build_object('status', 'error', 'error', 'This scene no longer exists');
  end if;
  select s.* into v_scene from public.scenes s where s.id = v_rev.scene_id for update;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'This scene no longer exists');
  end if;
  if v_scene.trashed_at is not null then
    return jsonb_build_object('status', 'error', 'error', 'Restore this scene from Trash first');
  end if;
  if p_expected_version is null or v_scene.version <> p_expected_version then
    return jsonb_build_object('status', 'version_mismatch');
  end if;
  if v_scene.content is not distinct from v_rev.content then
    return jsonb_build_object('status', 'unchanged', 'version', v_scene.version,
                              'updated_at', v_scene.updated_at, 'word_count', v_scene.word_count);
  end if;

  perform set_config('rune.scene_restore', v_scene.id::text, true);
  v_result := public.save_scene_checked(v_scene.id, v_rev.content, v_rev.word_count, p_expected_version);
  perform set_config('rune.scene_restore', '', true);

  if v_result ->> 'status' = 'ok' then
    return v_result || jsonb_build_object('word_count', v_rev.word_count, 'scene_id', v_scene.id);
  end if;
  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.restore_workspace_object(p_type text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_project_id uuid;
  v_trashed_at timestamptz;
  v_from_folder uuid;
  v_from_position integer;
  v_parent uuid;
  v_index integer;
  v_node_id uuid;
begin
  -- A Scene (031) follows the manuscript's rules, not the Workspace tree's.
  if p_type = 'scene' then
    return public.restore_manuscript_scene(p_id);
  end if;
  -- A Chapter (037) goes with its Scenes, as one piece of the manuscript.
  if p_type = 'chapter' then
    return public.restore_manuscript_chapter(p_id);
  end if;
  if p_type is null or p_type not in ('page', 'folder', 'collection', 'entry') then
    return jsonb_build_object('status', 'error', 'error', 'Unknown item type');
  end if;
  v_project_id := public.owned_workspace_object_project(p_type, p_id);
  if v_project_id is null then
    return jsonb_build_object('status', 'error', 'error', 'Item not found');
  end if;
  perform public.lock_project_workspace(v_project_id);

  if p_type = 'entry' then
    select e.trashed_at into v_trashed_at from public.workspace_collection_entries e where e.id = p_id;
    if v_trashed_at is null then
      return jsonb_build_object('status', 'error', 'error', 'Not in Trash');
    end if;
    if not exists (select 1 from public.workspace_collection_entries e
                     join public.workspace_collections c on c.id = e.collection_id
                    where e.id = p_id and c.trashed_at is null) then
      return jsonb_build_object('status', 'error', 'error', 'Restore its collection first');
    end if;
    update public.workspace_collection_entries set trashed_at = null where id = p_id;
    return jsonb_build_object('status', 'ok', 'location', 'original');
  end if;

  if p_type = 'page' then
    select d.trashed_at, d.trashed_from_folder_id, d.trashed_from_position
      into v_trashed_at, v_from_folder, v_from_position from public.workspace_documents d where d.id = p_id;
  elsif p_type = 'folder' then
    select f.trashed_at, f.trashed_from_folder_id, f.trashed_from_position
      into v_trashed_at, v_from_folder, v_from_position from public.workspace_folders f where f.id = p_id;
  else
    select c.trashed_at, c.trashed_from_folder_id, c.trashed_from_position
      into v_trashed_at, v_from_folder, v_from_position from public.workspace_collections c where c.id = p_id;
  end if;
  if v_trashed_at is null then
    return jsonb_build_object('status', 'error', 'error', 'Not in Trash');
  end if;

  -- Where it was, if that is still somewhere: an active Folder of this Project
  -- (its node) or the top level. Otherwise the end of the top level.
  if v_from_folder is null then
    v_parent := null;
    v_index := v_from_position - 1;
  else
    select n.id into v_parent
      from public.workspace_nodes n
      join public.workspace_folders f on f.id = n.folder_id
     where f.id = v_from_folder and f.project_id = v_project_id and f.trashed_at is null;
    v_index := case when v_parent is null then null else v_from_position - 1 end;
  end if;

  if p_type = 'page' then
    update public.workspace_documents set trashed_at = null, trashed_from_folder_id = null, trashed_from_position = null where id = p_id;
  elsif p_type = 'folder' then
    update public.workspace_folders set trashed_at = null, trashed_from_folder_id = null, trashed_from_position = null where id = p_id;
  else
    update public.workspace_collections set trashed_at = null, trashed_from_folder_id = null, trashed_from_position = null where id = p_id;
  end if;

  -- Its one node (the unique target keys refuse a second), made at the end of
  -- the top level and then put in place.
  insert into public.workspace_nodes (project_id, target_type, document_id, folder_id, collection_id, parent_node_id, position)
  values (v_project_id, p_type,
          case when p_type = 'page' then p_id end,
          case when p_type = 'folder' then p_id end,
          case when p_type = 'collection' then p_id end,
          null,
          (select coalesce(max(n.position), 0) + 1 from public.workspace_nodes n
            where n.project_id = v_project_id and n.parent_node_id is null))
  returning id into v_node_id;
  perform public.place_workspace_node(v_node_id, v_parent, v_index);

  return jsonb_build_object('status', 'ok', 'node_id', v_node_id,
    'location', case when v_from_folder is not null and v_parent is null then 'top' else 'original' end);
end;
$function$;

CREATE OR REPLACE FUNCTION public.revision_note_anchor_valid(p_anchor jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select p_anchor is not null
     and jsonb_typeof(p_anchor) = 'object'
     and (select coalesce(array_agg(k order by k), '{}') from jsonb_object_keys(p_anchor) k)
         = array['after', 'before', 'from', 'scene_version', 'text', 'to']
     and jsonb_typeof(p_anchor->'text') = 'string'
     and (p_anchor->>'text') ~ '\S'
     and char_length(p_anchor->>'text') <= 2000
     and jsonb_typeof(p_anchor->'before') = 'string'
     and char_length(p_anchor->>'before') <= 200
     and jsonb_typeof(p_anchor->'after') = 'string'
     and char_length(p_anchor->>'after') <= 200
     and jsonb_typeof(p_anchor->'from') = 'number'
     and jsonb_typeof(p_anchor->'to') = 'number'
     and (p_anchor->>'from')::numeric = floor((p_anchor->>'from')::numeric)
     and (p_anchor->>'to')::numeric = floor((p_anchor->>'to')::numeric)
     and (p_anchor->>'from')::numeric >= 0
     and (p_anchor->>'to')::numeric > (p_anchor->>'from')::numeric
     and jsonb_typeof(p_anchor->'scene_version') = 'number'
     and (p_anchor->>'scene_version')::numeric >= 1;
$function$;

CREATE OR REPLACE FUNCTION public.revision_note_json(n revision_notes)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object('id', n.id, 'project_id', n.project_id, 'target_type', n.target_type,
                            'target_id', n.target_id, 'body', n.body, 'version', n.version,
                            'created_at', n.created_at, 'updated_at', n.updated_at,
                            'details', n.details, 'resolved_at', n.resolved_at, 'anchor', n.anchor);
$function$;

CREATE OR REPLACE FUNCTION public.revision_note_target_active(p_target_type text, p_target_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select case p_target_type
    when 'scene' then exists (
      select 1 from public.scenes s
        join public.manuscripts m on m.id = s.manuscript_id
        join public.projects p on p.id = m.project_id
       where s.id = p_target_id and s.trashed_at is null and p.user_id = auth.uid())
    when 'chapter' then exists (
      select 1 from public.chapters c
        join public.manuscripts m on m.id = c.manuscript_id
        join public.projects p on p.id = m.project_id
       where c.id = p_target_id and c.trashed_at is null and p.user_id = auth.uid())
    when 'group' then exists (
      select 1 from public.manuscript_groups g
        join public.manuscripts m on m.id = g.manuscript_id
        join public.projects p on p.id = m.project_id
       where g.id = p_target_id and p.user_id = auth.uid())
    when 'manuscript' then exists (
      select 1 from public.manuscripts m
        join public.projects p on p.id = m.project_id
       where m.id = p_target_id and p.user_id = auth.uid())
    else false
  end;
$function$;

CREATE OR REPLACE FUNCTION public.revision_notes_check_target()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'UPDATE' then
    if new.id <> old.id or new.project_id <> old.project_id or new.manuscript_id <> old.manuscript_id
       or new.target_type <> old.target_type or new.target_id <> old.target_id
       or new.scene_id is distinct from old.scene_id or new.chapter_id is distinct from old.chapter_id
       or new.group_id is distinct from old.group_id then
      raise exception 'A revision note keeps its target';
    end if;
    if new.anchor is distinct from old.anchor then
      raise exception 'A revision note keeps its anchor';
    end if;
    return new;
  end if;
  if not exists (select 1 from public.manuscripts m where m.id = new.manuscript_id and m.project_id = new.project_id) then
    raise exception 'A revision note''s Manuscript must be its Project''s';
  end if;
  if new.target_type = 'scene'
     and not exists (select 1 from public.scenes s where s.id = new.scene_id and s.manuscript_id = new.manuscript_id) then
    raise exception 'A revision note''s Scene must be of its Manuscript';
  end if;
  if new.anchor is not null and (new.target_type <> 'scene' or not public.revision_note_anchor_valid(new.anchor)) then
    raise exception 'A revision note''s anchor must be a passage of its Scene';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.rich_text_plain(p_doc jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
  select coalesce(btrim(regexp_replace(string_agg(t #>> '{}', ' ' order by n), '\s+', ' ', 'g')), '')
    from jsonb_path_query(coalesce(p_doc, '{}'::jsonb), 'strict $.** ? (@.type == "text").text ? (@.type() == "string")')
         with ordinality as x(t, n);
$function$;

-- Save-path RPC. Statuses: ok | word_limit_blocked | version_mismatch | error
-- ('Scene not found'). Once clients depend on it, never overload or extend it.
CREATE OR REPLACE FUNCTION public.save_scene_checked(p_scene_id uuid, p_content jsonb, p_word_count integer, p_expected_version integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_old_word_count int;
  v_limit int;
  v_new_total int;
  v_updated public.scenes%rowtype;
begin
  perform public.lock_account_word_budget();

  select s.word_count
    into v_old_word_count
    from public.scenes s
    where s.id = p_scene_id;

  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Scene not found');
  end if;

  -- Only enforce when words are being added — never block edits/deletions.
  -- A Scene that is already over the allowance is never trapped: shrinking
  -- or net-neutral edits always pass, only further growth is blocked.
  if p_word_count > v_old_word_count then
    v_limit := public.free_word_limit_for_caller();
    if v_limit is not null then
      v_new_total := public.account_word_total(p_scene_id, p_word_count);
      if v_new_total > v_limit then
        return jsonb_build_object('status', 'word_limit_blocked', 'limit', v_limit);
      end if;
    end if;
  end if;

  if p_expected_version is not null then
    update public.scenes
       set content = p_content, word_count = p_word_count
     where id = p_scene_id and version = p_expected_version
     returning * into v_updated;

    if not found then
      return jsonb_build_object('status', 'version_mismatch');
    end if;
  else
    update public.scenes
       set content = p_content, word_count = p_word_count
     where id = p_scene_id
     returning * into v_updated;

    if not found then
      return jsonb_build_object('status', 'error', 'error', 'Scene not found');
    end if;
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'updated_at', v_updated.updated_at,
    'version', v_updated.version
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.search_project_content(p_project_id uuid, p_query text, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with q as (
    select lower(btrim(regexp_replace(coalesce(p_query, ''), '\s+', ' ', 'g'))) as q
  ),
  owned as (
    select p.id from public.projects p where p.id = p_project_id and p.user_id = auth.uid()
  ),
  texts as (
    select 'scene'::text as object_type, s.id as object_id, public.rich_text_plain(s.content) as body, 0 as kind_rank
      from public.scenes s
      join public.manuscripts m on m.id = s.manuscript_id
      join owned o on o.id = m.project_id
     where s.trashed_at is null
    union all
    select 'page', d.id, public.rich_text_plain(d.content), 1
      from public.workspace_documents d
      join owned o on o.id = d.project_id
     where d.trashed_at is null
    union all
    select 'entry', e.id, public.rich_text_plain(e.content), 2
      from public.workspace_collection_entries e
      join public.workspace_collections c on c.id = e.collection_id
      join owned o on o.id = e.project_id
     where e.trashed_at is null and c.trashed_at is null
  ),
  found as (
    select t.object_type, t.object_id, t.body, t.kind_rank, strpos(lower(t.body), q.q) as at, length(q.q) as len
      from texts t, q
     where length(q.q) >= 2
       and strpos(lower(t.body), q.q) > 0
  ),
  windowed as (
    select f.*, greatest(f.at - 60, 1) as w_from, least(f.at + f.len + 80, length(f.body) + 1) as w_to
      from found f
  )
  select coalesce(jsonb_agg(jsonb_build_object('type', r.object_type, 'id', r.object_id, 'snippet', r.snippet)
                            order by r.kind_rank, r.object_id), '[]'::jsonb)
    from (
      select w.object_type,
             w.object_id,
             w.kind_rank,
             -- An excerpt around the first match, trimmed to whole words, with
             -- an ellipsis where the text goes on.
             case when w.w_from > 1 then '…' else '' end
               || btrim(regexp_replace(regexp_replace(substr(w.body, w.w_from, w.w_to - w.w_from),
                    case when w.w_from > 1 then '^\S*\s' else '^' end, ''),
                    case when w.w_to <= length(w.body) then '\s\S*$' else '$' end, ''))
               || case when w.w_to <= length(w.body) then '…' else '' end as snippet
        from windowed w
       order by w.kind_rank, w.object_id
       limit greatest(1, least(coalesce(p_limit, 100), 200))
    ) r;
$function$;

CREATE OR REPLACE FUNCTION public.set_scene_property_value(p_scene_id uuid, p_property_id uuid, p_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_manuscript_id uuid;
  v_project_id uuid;
  v_property public.scene_property_definitions%rowtype;
  v_value jsonb := p_value;
begin
  select s.manuscript_id, m.project_id into v_manuscript_id, v_project_id
    from public.scenes s
    join public.manuscripts m on m.id = s.manuscript_id
    join public.projects p on p.id = m.project_id
   where s.id = p_scene_id and p.user_id = auth.uid() and s.trashed_at is null;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Scene not found');
  end if;
  perform public.lock_project_workspace(v_project_id);
  -- Only a (non-Relationship) property of the Scene's own Manuscript.
  select * into v_property from public.scene_property_definitions pr
   where pr.id = p_property_id and pr.manuscript_id = v_manuscript_id and pr.type <> 'relationship';
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Property not found');
  end if;

  if v_property.type = 'text' and jsonb_typeof(v_value) = 'string' then
    v_value := to_jsonb(btrim(v_value #>> '{}'));
  elsif v_property.type = 'multi_select' and jsonb_typeof(v_value) = 'array' then
    -- Duplicates collapse, first occurrence kept.
    v_value := coalesce((select jsonb_agg(x order by i)
                           from (select x, min(i) as i from jsonb_array_elements(v_value) with ordinality as t(x, i) group by x) d),
                        '[]'::jsonb);
  end if;

  if v_value is null or v_value = 'null'::jsonb or v_value = '""'::jsonb or v_value = '[]'::jsonb or v_value = 'false'::jsonb then
    delete from public.scene_property_values v where v.scene_id = p_scene_id and v.property_id = p_property_id;
    return jsonb_build_object('status', 'ok', 'value', null);
  end if;
  if not public.workspace_property_value_valid(v_property.type, v_property.options, v_value) then
    return jsonb_build_object('status', 'error', 'error', 'Invalid value');
  end if;

  insert into public.scene_property_values (scene_id, property_id, manuscript_id, project_id, value)
  values (p_scene_id, p_property_id, v_manuscript_id, v_project_id, v_value)
  on conflict (scene_id, property_id) do update set value = excluded.value;
  return jsonb_build_object('status', 'ok', 'value', v_value);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_scene_relationship(p_scene_id uuid, p_property_id uuid, p_target_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_manuscript_id uuid;
  v_project_id uuid;
  v_property public.scene_property_definitions%rowtype;
  v_targets uuid[];
  v_bad integer;
begin
  select s.manuscript_id, m.project_id into v_manuscript_id, v_project_id
    from public.scenes s
    join public.manuscripts m on m.id = s.manuscript_id
    join public.projects p on p.id = m.project_id
   where s.id = p_scene_id and p.user_id = auth.uid() and s.trashed_at is null;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Scene not found');
  end if;
  perform public.lock_project_workspace(v_project_id);
  select * into v_property from public.scene_property_definitions pr
   where pr.id = p_property_id and pr.manuscript_id = v_manuscript_id and pr.type = 'relationship';
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Property not found');
  end if;

  v_targets := coalesce((select array_agg(t order by i)
                           from (select t, min(i) as i from unnest(coalesce(p_target_ids, '{}')) with ordinality as u(t, i)
                                  where t is not null group by t) d), '{}');
  if cardinality(v_targets) > 1 and not v_property.relation_many then
    return jsonb_build_object('status', 'error', 'error', 'This relationship holds one value');
  end if;
  if cardinality(v_targets) > 500 then
    return jsonb_build_object('status', 'error', 'error', 'Too many values');
  end if;
  if p_scene_id = any (v_targets) then
    return jsonb_build_object('status', 'error', 'error', 'A scene cannot point to itself');
  end if;
  select count(*) into v_bad
    from unnest(v_targets) t
   where not public.workspace_object_active(v_property.relation_target, t)
      or case v_property.relation_target
           when 'entry' then not exists (select 1 from public.workspace_collection_entries e
                                          where e.id = t and e.collection_id = v_property.relation_collection_id
                                            and e.project_id = v_project_id)
           else public.reference_object_project(v_property.relation_target, t) is distinct from v_project_id
         end;
  if v_bad > 0 then
    return jsonb_build_object('status', 'error', 'error', 'Not a valid target');
  end if;

  -- Visible targets no longer chosen go; dormant ones stay, unless a one-value
  -- Relationship is being given a new target.
  delete from public.object_references r
   where r.scene_property_id = p_property_id and r.source_scene_id = p_scene_id
     and not (coalesce(r.target_entry_id, r.target_document_id, r.target_scene_id) = any (v_targets))
     and (public.workspace_object_active(r.target_type, coalesce(r.target_entry_id, r.target_document_id, r.target_scene_id))
          or (not v_property.relation_many and cardinality(v_targets) > 0));
  update public.object_references r
     set position = o.ord
    from unnest(v_targets) with ordinality as o(t, ord)
   where r.scene_property_id = p_property_id and r.source_scene_id = p_scene_id
     and coalesce(r.target_entry_id, r.target_document_id, r.target_scene_id) = o.t
     and r.position <> o.ord;
  -- Dormant targets after the visible ones, in their order.
  update public.object_references r
     set position = cardinality(v_targets) + d.ord
    from (select x.id, row_number() over (order by x.position, x.id) as ord
            from public.object_references x
           where x.scene_property_id = p_property_id and x.source_scene_id = p_scene_id
             and not (coalesce(x.target_entry_id, x.target_document_id, x.target_scene_id) = any (v_targets))) d
   where r.id = d.id and r.position <> cardinality(v_targets) + d.ord;
  insert into public.object_references
    (project_id, source_type, source_scene_id, target_type, target_entry_id, target_document_id, target_scene_id,
     scene_property_id, position)
  select v_project_id, 'scene', p_scene_id, v_property.relation_target,
         case when v_property.relation_target = 'entry' then o.t end,
         case when v_property.relation_target = 'page' then o.t end,
         case when v_property.relation_target = 'scene' then o.t end,
         p_property_id, o.ord
    from unnest(v_targets) with ordinality as o(t, ord)
   where not exists (select 1 from public.object_references r
                      where r.scene_property_id = p_property_id and r.source_scene_id = p_scene_id
                        and coalesce(r.target_entry_id, r.target_document_id, r.target_scene_id) = o.t);

  return jsonb_build_object('status', 'ok', 'targets', to_jsonb(v_targets));
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_workspace_entry_relationship(p_entry_id uuid, p_property_id uuid, p_target_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_entry public.workspace_collection_entries%rowtype;
  v_property public.workspace_collection_properties%rowtype;
  v_targets uuid[];
  v_bad integer;
begin
  select e.* into v_entry
    from public.workspace_collection_entries e
    join public.projects p on p.id = e.project_id
   where e.id = p_entry_id and p.user_id = auth.uid();
  if not found or not public.workspace_object_active('entry', p_entry_id) then
    return jsonb_build_object('status', 'error', 'error', 'Entry not found');
  end if;
  perform public.lock_project_workspace(v_entry.project_id);
  select * into v_property from public.workspace_collection_properties pr
   where pr.id = p_property_id and pr.collection_id = v_entry.collection_id and pr.type = 'relationship';
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Property not found');
  end if;

  v_targets := coalesce((select array_agg(t order by i)
                           from (select t, min(i) as i from unnest(coalesce(p_target_ids, '{}')) with ordinality as u(t, i)
                                  where t is not null group by t) d), '{}');
  if cardinality(v_targets) > 1 and not v_property.relation_many then
    return jsonb_build_object('status', 'error', 'error', 'This relationship holds one value');
  end if;
  if cardinality(v_targets) > 500 then
    return jsonb_build_object('status', 'error', 'error', 'Too many values');
  end if;
  if p_entry_id = any (v_targets) then
    return jsonb_build_object('status', 'error', 'error', 'An entry cannot point to itself');
  end if;
  select count(*) into v_bad
    from unnest(v_targets) t
   where not public.workspace_object_active(v_property.relation_target, t)
      or case v_property.relation_target
           when 'entry' then not exists (select 1 from public.workspace_collection_entries e
                                          where e.id = t and e.collection_id = v_property.relation_collection_id
                                            and e.project_id = v_entry.project_id)
           else public.reference_object_project(v_property.relation_target, t) is distinct from v_entry.project_id
         end;
  if v_bad > 0 then
    return jsonb_build_object('status', 'error', 'error', 'Not a valid target');
  end if;

  -- Visible targets no longer chosen go; dormant ones stay, unless a one-value
  -- Relationship is being given a new target.
  delete from public.object_references r
   where r.property_id = p_property_id and r.source_entry_id = p_entry_id
     and not (coalesce(r.target_entry_id, r.target_document_id, r.target_scene_id) = any (v_targets))
     and (public.workspace_object_active(r.target_type, coalesce(r.target_entry_id, r.target_document_id, r.target_scene_id))
          or (not v_property.relation_many and cardinality(v_targets) > 0));
  update public.object_references r
     set position = o.ord
    from unnest(v_targets) with ordinality as o(t, ord)
   where r.property_id = p_property_id and r.source_entry_id = p_entry_id
     and coalesce(r.target_entry_id, r.target_document_id, r.target_scene_id) = o.t
     and r.position <> o.ord;
  -- Dormant targets after the visible ones, in their order.
  update public.object_references r
     set position = cardinality(v_targets) + d.ord
    from (select x.id, row_number() over (order by x.position, x.id) as ord
            from public.object_references x
           where x.property_id = p_property_id and x.source_entry_id = p_entry_id
             and not (coalesce(x.target_entry_id, x.target_document_id, x.target_scene_id) = any (v_targets))) d
   where r.id = d.id and r.position <> cardinality(v_targets) + d.ord;
  insert into public.object_references
    (project_id, source_type, source_entry_id, target_type, target_entry_id, target_document_id, target_scene_id, property_id, position)
  select v_entry.project_id, 'entry', p_entry_id, v_property.relation_target,
         case when v_property.relation_target = 'entry' then o.t end,
         case when v_property.relation_target = 'page' then o.t end,
         case when v_property.relation_target = 'scene' then o.t end,
         p_property_id, o.ord
    from unnest(v_targets) with ordinality as o(t, ord)
   where not exists (select 1 from public.object_references r
                      where r.property_id = p_property_id and r.source_entry_id = p_entry_id
                        and coalesce(r.target_entry_id, r.target_document_id, r.target_scene_id) = o.t);

  return jsonb_build_object('status', 'ok', 'targets', to_jsonb(v_targets));
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_workspace_entry_value(p_entry_id uuid, p_property_id uuid, p_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_entry public.workspace_collection_entries%rowtype;
  v_property public.workspace_collection_properties%rowtype;
  v_value jsonb := p_value;
begin
  select e.* into v_entry
    from public.workspace_collection_entries e
    join public.projects p on p.id = e.project_id
   where e.id = p_entry_id and p.user_id = auth.uid();
  if not found or not public.workspace_object_active('entry', p_entry_id) then
    return jsonb_build_object('status', 'error', 'error', 'Entry not found');
  end if;
  -- Only a property of the Entry's own Collection.
  select * into v_property from public.workspace_collection_properties pr
   where pr.id = p_property_id and pr.collection_id = v_entry.collection_id;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Property not found');
  end if;

  if v_property.type = 'text' and jsonb_typeof(v_value) = 'string' then
    v_value := to_jsonb(btrim(v_value #>> '{}'));
  elsif v_property.type = 'multi_select' and jsonb_typeof(v_value) = 'array' then
    -- Duplicates collapse, first occurrence kept.
    v_value := coalesce((select jsonb_agg(x order by i)
                           from (select x, min(i) as i from jsonb_array_elements(v_value) with ordinality as t(x, i) group by x) d),
                        '[]'::jsonb);
  end if;

  if v_value is null or v_value = 'null'::jsonb or v_value = '""'::jsonb or v_value = '[]'::jsonb or v_value = 'false'::jsonb then
    delete from public.workspace_entry_values v where v.entry_id = p_entry_id and v.property_id = p_property_id;
    return jsonb_build_object('status', 'ok', 'value', null);
  end if;
  if not public.workspace_property_value_valid(v_property.type, v_property.options, v_value) then
    return jsonb_build_object('status', 'error', 'error', 'Invalid value');
  end if;

  insert into public.workspace_entry_values (entry_id, property_id, collection_id, project_id, value)
  values (p_entry_id, p_property_id, v_entry.collection_id, v_entry.project_id, v_value)
  on conflict (entry_id, property_id) do update set value = excluded.value;
  return jsonb_build_object('status', 'ok', 'value', v_value);
end;
$function$;

CREATE OR REPLACE FUNCTION public.stamp_workspace_document()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    new.version := 1;
    new.created_at := now();
    new.updated_at := now();
    return new;
  end if;
  new.id := old.id;
  new.created_at := old.created_at;
  new.version := case when new.content is distinct from old.content then old.version + 1 else old.version end;
  new.updated_at := case when new.content is distinct from old.content or new.title is distinct from old.title
                         then now() else old.updated_at end;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.stamp_workspace_folder()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    new.created_at := now();
    new.updated_at := now();
    return new;
  end if;
  new.id := old.id;
  new.created_at := old.created_at;
  new.updated_at := case when new.title is distinct from old.title then now() else old.updated_at end;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_scene_views_with_property()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_manuscript_id uuid := coalesce(new.manuscript_id, old.manuscript_id);
begin
  -- The Manuscript itself is being deleted: its Views go with it.
  if not exists (select 1 from public.manuscripts m where m.id = v_manuscript_id) then
    return null;
  end if;

  if tg_op = 'INSERT' then
    update public.scene_views v
       set config = jsonb_set(v.config, '{properties}', (v.config -> 'properties') || to_jsonb(new.id::text))
     where v.manuscript_id = v_manuscript_id
       and (v.type = 'table' or jsonb_array_length(v.config -> 'properties') < 3);
    if new.type in ('select', 'status') then
      update public.scene_views v
         set config = jsonb_set(v.config, '{group_by}', to_jsonb(new.id::text))
       where v.manuscript_id = v_manuscript_id and v.type = 'board' and jsonb_typeof(v.config -> 'group_by') = 'null';
    end if;
    if new.type in ('date', 'number') then
      update public.scene_views v
         set config = jsonb_set(v.config, '{axis}', to_jsonb(new.id::text))
       where v.manuscript_id = v_manuscript_id and v.type = 'timeline' and jsonb_typeof(v.config -> 'axis') is distinct from 'string';
    end if;
    return null;
  end if;

  update public.scene_views v
     set config = public.prune_scene_view_config(v_manuscript_id, v.config)
   where v.manuscript_id = v_manuscript_id
     and v.config is distinct from public.prune_scene_view_config(v_manuscript_id, v.config);
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_workspace_inline_references()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_source_type text := case tg_table_name when 'workspace_documents' then 'page' else 'entry' end;
  v_types text[];
  v_ids uuid[];
begin
  begin
    -- The document's mentions: known kinds, well-formed ids, in this Project,
    -- never itself — once each, in order of first appearance.
    select coalesce(array_agg(m.target_type order by m.first_at), '{}'),
           coalesce(array_agg(m.target_id order by m.first_at), '{}')
      into v_types, v_ids
      from (select f.target_type, f.target_id, min(f.at) as first_at
              from (select n.node #>> '{attrs,targetType}' as target_type,
                           case when n.node #>> '{attrs,targetId}'
                                     ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                                then (n.node #>> '{attrs,targetId}')::uuid end as target_id,
                           n.at
                      from jsonb_path_query(new.content, 'strict $.**') with ordinality as n(node, at)
                     where jsonb_typeof(n.node) = 'object'
                       and n.node ->> 'type' = 'reference'
                       and n.node #>> '{attrs,targetType}' in ('entry', 'page', 'scene', 'chapter')) f
             where f.target_id is not null
               and not (f.target_type = v_source_type and f.target_id = new.id)
             group by f.target_type, f.target_id) m
     where public.reference_object_project(m.target_type, m.target_id) = new.project_id;

    -- Mentions no longer in the text go (dormant ones included).
    delete from public.object_references r
     where r.origin = 'inline'
       and (case v_source_type when 'page' then r.source_document_id else r.source_entry_id end) = new.id
       and not exists (select 1 from unnest(v_types, v_ids) as w(t, i)
                        where w.t = r.target_type
                          and w.i = coalesce(r.target_entry_id, r.target_document_id, r.target_scene_id, r.target_chapter_id));

    -- The rest in the text's order; new ones only to an active target.
    update public.object_references r
       set position = w.ord
      from unnest(v_types, v_ids) with ordinality as w(t, i, ord)
     where r.origin = 'inline'
       and (case v_source_type when 'page' then r.source_document_id else r.source_entry_id end) = new.id
       and r.target_type = w.t
       and coalesce(r.target_entry_id, r.target_document_id, r.target_scene_id, r.target_chapter_id) = w.i
       and r.position <> w.ord;

    insert into public.object_references
      (project_id, source_type, source_entry_id, source_document_id,
       target_type, target_entry_id, target_document_id, target_scene_id, target_chapter_id, position, origin)
    select new.project_id, v_source_type,
           case when v_source_type = 'entry' then new.id end,
           case when v_source_type = 'page' then new.id end,
           w.t,
           case when w.t = 'entry' then w.i end,
           case when w.t = 'page' then w.i end,
           case when w.t = 'scene' then w.i end,
           case when w.t = 'chapter' then w.i end,
           w.ord, 'inline'
      from unnest(v_types, v_ids) with ordinality as w(t, i, ord)
     where public.workspace_object_active(w.t, w.i)
       and not exists (select 1 from public.object_references r
                        where r.origin = 'inline'
                          and (case v_source_type when 'page' then r.source_document_id else r.source_entry_id end) = new.id
                          and r.target_type = w.t
                          and coalesce(r.target_entry_id, r.target_document_id, r.target_scene_id, r.target_chapter_id) = w.i);
  exception when others then
    -- The writer's text is saved regardless; its backlinks catch up on the next save.
    raise warning 'Inline references of % % were not updated (%)', v_source_type, new.id, sqlstate;
  end;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_workspace_views_with_property()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_collection_id uuid := coalesce(new.collection_id, old.collection_id);
begin
  -- The Collection itself is being deleted: its Views go with it.
  if not exists (select 1 from public.workspace_collections c where c.id = v_collection_id) then
    return null;
  end if;

  if tg_op = 'INSERT' then
    update public.workspace_collection_views v
       set config = jsonb_set(v.config, '{properties}', (v.config -> 'properties') || to_jsonb(new.id::text))
     where v.collection_id = v_collection_id
       and (v.type = 'table' or jsonb_array_length(v.config -> 'properties') < 3);
    if new.type in ('select', 'status') then
      update public.workspace_collection_views v
         set config = jsonb_set(v.config, '{group_by}', to_jsonb(new.id::text))
       where v.collection_id = v_collection_id and v.type = 'board' and jsonb_typeof(v.config -> 'group_by') = 'null';
    end if;
    if new.type in ('date', 'number') then
      update public.workspace_collection_views v
         set config = jsonb_set(v.config, '{axis}', to_jsonb(new.id::text))
       where v.collection_id = v_collection_id and v.type = 'timeline' and jsonb_typeof(v.config -> 'axis') is distinct from 'string';
    end if;
    return null;
  end if;

  update public.workspace_collection_views v
     set config = public.prune_workspace_view_config(v_collection_id, v.config)
   where v.collection_id = v_collection_id
     and v.config is distinct from public.prune_workspace_view_config(v_collection_id, v.config);
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.touch_pricing_entitlement_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trash_manuscript_chapter(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_chapter public.chapters%rowtype;
  v_index integer;
  v_scenes integer;
begin
  perform public.lock_account_word_budget();
  select c.* into v_chapter
    from public.chapters c
    join public.manuscripts m on m.id = c.manuscript_id
    join public.projects p on p.id = m.project_id
   where c.id = p_id and p.user_id = auth.uid()
     for update of c;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Item not found');
  end if;
  if v_chapter.trashed_at is not null then
    return jsonb_build_object('status', 'error', 'error', 'Already in Trash');
  end if;

  -- Its place among its parent's Groups and Chapters, in the one sibling order.
  select o.ord - 1 into v_index
    from (select s.id, row_number() over (order by s.position, s.kind desc, s.id) as ord
            from (select 'group'::text as kind, g.id, g.position from public.manuscript_groups g
                   where g.manuscript_id = v_chapter.manuscript_id
                     and g.parent_group_id is not distinct from v_chapter.group_id
                  union all
                  select 'chapter'::text, c.id, c.position from public.chapters c
                   where c.manuscript_id = v_chapter.manuscript_id
                     and c.group_id is not distinct from v_chapter.group_id
                     and c.trashed_at is null) s) o
   where o.id = p_id;

  -- Its active Scenes go with it: out of the Chapter (so out of the ordered
  -- total, through scenes_refresh_project_word_count), each keeping its
  -- position, version and updated_at (increment_scene_version skips the
  -- trash transition).
  perform 1 from public.scenes s where s.chapter_id = p_id for update;
  update public.scenes
     set trashed_at = now(), trashed_from_chapter_id = p_id, trashed_with_chapter = true, chapter_id = null
   where chapter_id = p_id;
  get diagnostics v_scenes = row_count;

  update public.chapters
     set trashed_at = now(), trashed_from_group_id = v_chapter.group_id, trashed_from_index = v_index, group_id = null
   where id = p_id;

  return jsonb_build_object('status', 'ok', 'moved', 0, 'scenes', v_scenes);
end;
$function$;

CREATE OR REPLACE FUNCTION public.trash_manuscript_scene(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_scene public.scenes%rowtype;
begin
  perform public.lock_account_word_budget();
  select s.* into v_scene
    from public.scenes s
    join public.manuscripts m on m.id = s.manuscript_id
    join public.projects p on p.id = m.project_id
   where s.id = p_id and p.user_id = auth.uid()
     for update of s;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Item not found');
  end if;
  if v_scene.trashed_at is not null then
    return jsonb_build_object('status', 'error', 'error', 'Already in Trash');
  end if;

  -- scenes_refresh_project_word_count takes a placed Scene's words out of the
  -- ordered total.
  update public.scenes
     set trashed_at = now(), trashed_from_chapter_id = v_scene.chapter_id, chapter_id = null
   where id = p_id;
  return jsonb_build_object('status', 'ok', 'moved', 0);
end;
$function$;

CREATE OR REPLACE FUNCTION public.trash_workspace_object(p_type text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_project_id uuid;
  v_node public.workspace_nodes%rowtype;
  v_from_folder uuid;
  v_child uuid;
  v_at integer;
  v_moved integer := 0;
begin
  -- A Scene (031) follows the manuscript's rules, not the Workspace tree's.
  if p_type = 'scene' then
    return public.trash_manuscript_scene(p_id);
  end if;
  -- A Chapter (037) goes with its Scenes, as one piece of the manuscript.
  if p_type = 'chapter' then
    return public.trash_manuscript_chapter(p_id);
  end if;
  if p_type is null or p_type not in ('page', 'folder', 'collection', 'entry') then
    return jsonb_build_object('status', 'error', 'error', 'Unknown item type');
  end if;
  v_project_id := public.owned_workspace_object_project(p_type, p_id);
  if v_project_id is null then
    return jsonb_build_object('status', 'error', 'error', 'Item not found');
  end if;
  perform public.lock_project_workspace(v_project_id);
  if not public.workspace_object_active(p_type, p_id) then
    return jsonb_build_object('status', 'error', 'error', 'Already in Trash');
  end if;

  if p_type = 'entry' then
    update public.workspace_collection_entries set trashed_at = now() where id = p_id;
    return jsonb_build_object('status', 'ok', 'moved', 0);
  end if;

  select n.* into v_node from public.workspace_nodes n
   where case p_type when 'page' then n.document_id when 'folder' then n.folder_id else n.collection_id end = p_id;
  if found then
    select pn.folder_id into v_from_folder from public.workspace_nodes pn where pn.id = v_node.parent_node_id;

    -- A Folder's items take its place, in order, just after it; then it goes.
    if p_type = 'folder' then
      v_at := v_node.position;          -- 0-based: just after the Folder
      for v_child in
        select c.id from public.workspace_nodes c where c.parent_node_id = v_node.id order by c.position, c.id
      loop
        perform public.place_workspace_node(v_child, v_node.parent_node_id, v_at);
        v_at := v_at + 1;
        v_moved := v_moved + 1;
      end loop;
    end if;

    delete from public.workspace_nodes n where n.id = v_node.id;
    perform public.renumber_workspace_siblings(v_project_id, v_node.parent_node_id);
  end if;

  if p_type = 'page' then
    update public.workspace_documents
       set trashed_at = now(), trashed_from_folder_id = v_from_folder, trashed_from_position = v_node.position
     where id = p_id;
  elsif p_type = 'folder' then
    update public.workspace_folders
       set trashed_at = now(), trashed_from_folder_id = v_from_folder, trashed_from_position = v_node.position
     where id = p_id;
  else
    update public.workspace_collections
       set trashed_at = now(), trashed_from_folder_id = v_from_folder, trashed_from_position = v_node.position
     where id = p_id;
  end if;
  return jsonb_build_object('status', 'ok', 'moved', v_moved);
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_revision_note(p_note_id uuid, p_body text, p_base_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_note public.revision_notes%rowtype;
  v_body text := coalesce(p_body, '');
begin
  select n.* into v_note
    from public.revision_notes n
    join public.projects p on p.id = n.project_id
   where n.id = p_note_id and p.user_id = auth.uid()
   for update of n;
  if not found then
    return jsonb_build_object('status', 'missing');
  end if;
  if not public.revision_note_target_active(v_note.target_type, v_note.target_id) then
    return jsonb_build_object('status', 'unavailable');
  end if;
  if v_body !~ '\S' then
    return jsonb_build_object('status', 'error', 'error', 'blank');
  end if;
  if char_length(v_body) > 20000 then
    return jsonb_build_object('status', 'error', 'error', 'too_long');
  end if;
  if v_note.body = v_body then
    return jsonb_build_object('status', 'ok', 'note', public.revision_note_json(v_note));
  end if;
  if p_base_version is not null and p_base_version <> v_note.version then
    return jsonb_build_object('status', 'conflict', 'note', public.revision_note_json(v_note));
  end if;

  update public.revision_notes n
     set body = v_body, version = n.version + 1, updated_at = now()
   where n.id = p_note_id
  returning * into v_note;
  return jsonb_build_object('status', 'ok', 'note', public.revision_note_json(v_note));
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_revision_note_item(p_note_id uuid, p_body text, p_details text, p_resolved boolean, p_base_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_note public.revision_notes%rowtype;
  v_body text := coalesce(p_body, '');
  v_details text := nullif(btrim(coalesce(p_details, '')), '');
  v_resolved boolean := coalesce(p_resolved, false);
begin
  select n.* into v_note
    from public.revision_notes n
    join public.projects p on p.id = n.project_id
   where n.id = p_note_id and p.user_id = auth.uid()
   for update of n;
  if not found then
    return jsonb_build_object('status', 'missing');
  end if;
  if not public.revision_note_target_active(v_note.target_type, v_note.target_id) then
    return jsonb_build_object('status', 'unavailable');
  end if;
  if v_body !~ '\S' then
    return jsonb_build_object('status', 'error', 'error', 'blank');
  end if;
  if char_length(v_body) > 20000 or (v_details is not null and char_length(v_details) > 20000) then
    return jsonb_build_object('status', 'error', 'error', 'too_long');
  end if;
  if v_note.body = v_body and v_note.details is not distinct from v_details
     and (v_note.resolved_at is not null) = v_resolved then
    return jsonb_build_object('status', 'ok', 'note', public.revision_note_json(v_note));
  end if;
  if p_base_version is not null and p_base_version <> v_note.version then
    return jsonb_build_object('status', 'conflict', 'note', public.revision_note_json(v_note));
  end if;

  update public.revision_notes n
     set body = v_body,
         details = v_details,
         resolved_at = case when v_resolved then coalesce(n.resolved_at, now()) else null end,
         version = n.version + 1,
         updated_at = now()
   where n.id = p_note_id
  returning * into v_note;
  return jsonb_build_object('status', 'ok', 'note', public.revision_note_json(v_note));
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_scene_property(p_property_id uuid, p_changes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_old public.scene_property_definitions%rowtype;
  v_new public.scene_property_definitions%rowtype;
  v_key text;
  v_opt jsonb;
  v_options jsonb := '[]'::jsonb;
  v_ids text[];
  v_cleared integer := 0;
begin
  select pr.* into v_old
    from public.scene_property_definitions pr
    join public.projects p on p.id = pr.project_id
   where pr.id = p_property_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Property not found');
  end if;
  perform public.lock_project_workspace(v_old.project_id);
  -- Re-read under the lock.
  select * into v_old from public.scene_property_definitions where id = p_property_id;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Property not found');
  end if;
  v_new := v_old;

  if jsonb_typeof(p_changes) is distinct from 'object' then
    return jsonb_build_object('status', 'error', 'error', 'Nothing to change');
  end if;
  for v_key in select jsonb_object_keys(p_changes) loop
    if v_key not in ('name', 'type', 'options', 'many', 'target', 'target_collection_id') then
      return jsonb_build_object('status', 'error', 'error', format('Unknown change: %s', v_key));
    end if;
  end loop;

  if p_changes ? 'name' then
    if jsonb_typeof(p_changes -> 'name') is distinct from 'string' or btrim(p_changes ->> 'name') = '' then
      return jsonb_build_object('status', 'error', 'error', 'A property needs a name');
    end if;
    v_new.name := left(btrim(p_changes ->> 'name'), 100);
    if exists (select 1 from public.scene_property_definitions p
                where p.manuscript_id = v_old.manuscript_id and p.id <> v_old.id and lower(p.name) = lower(v_new.name)) then
      return jsonb_build_object('status', 'error', 'error', 'A property with this name already exists');
    end if;
  end if;

  if p_changes ? 'type' then
    v_new.type := p_changes ->> 'type';
    -- Only where every value survives as it is (select ↔ status), or is
    -- wrapped losslessly (a single choice becomes a one-item multi-select).
    if v_new.type is distinct from v_old.type
       and not (v_old.type in ('select', 'status') and v_new.type in ('select', 'status', 'multi_select')) then
      return jsonb_build_object('status', 'error', 'error', 'This property’s type can’t be changed');
    end if;
  end if;

  if p_changes ? 'options' then
    if v_new.type not in ('select', 'multi_select', 'status') then
      return jsonb_build_object('status', 'error', 'error', 'Only a choice property has options');
    end if;
    if jsonb_typeof(p_changes -> 'options') is distinct from 'array' then
      return jsonb_build_object('status', 'error', 'error', 'Invalid property options');
    end if;
    -- An option keeps its id; one without an id is new and gets one here. An
    -- id the property never had is refused (a client can't invent a reference).
    for v_opt in select * from jsonb_array_elements(p_changes -> 'options') loop
      if jsonb_typeof(v_opt) <> 'object' then
        return jsonb_build_object('status', 'error', 'error', 'Invalid property options');
      end if;
      if v_opt ? 'id' and not exists (select 1 from jsonb_array_elements(v_old.options) o where o -> 'id' = v_opt -> 'id') then
        return jsonb_build_object('status', 'error', 'error', 'Unknown option');
      end if;
      v_options := v_options || jsonb_build_array(jsonb_build_object(
        'id', coalesce(v_opt ->> 'id', gen_random_uuid()::text),
        'name', left(btrim(coalesce(v_opt ->> 'name', '')), 100)));
    end loop;
    if not public.workspace_property_options_valid(v_options) then
      return jsonb_build_object('status', 'error', 'error', 'Each option needs a different name');
    end if;
    v_new.options := v_options;
  end if;

  if p_changes ? 'many' or p_changes ? 'target' or p_changes ? 'target_collection_id' then
    if v_old.type <> 'relationship' then
      return jsonb_build_object('status', 'error', 'error', 'Only a relationship points somewhere');
    end if;
  end if;

  if p_changes ? 'many' then
    if jsonb_typeof(p_changes -> 'many') is distinct from 'boolean' then
      return jsonb_build_object('status', 'error', 'error', 'many must be true or false');
    end if;
    v_new.relation_many := (p_changes ->> 'many')::boolean;
    if not v_new.relation_many and exists (
         select 1 from public.object_references r where r.scene_property_id = p_property_id
          group by r.source_scene_id having count(*) > 1) then
      return jsonb_build_object('status', 'error', 'error', 'Some scenes hold more than one');
    end if;
  end if;

  if p_changes ? 'target' or p_changes ? 'target_collection_id' then
    v_new.relation_target := coalesce(p_changes ->> 'target', v_old.relation_target);
    if v_new.relation_target not in ('entry', 'page', 'scene') then
      return jsonb_build_object('status', 'error', 'error', 'Unknown relationship target');
    end if;
    v_new.relation_collection_id := case when v_new.relation_target = 'entry'
                                         then coalesce((p_changes ->> 'target_collection_id')::uuid, v_old.relation_collection_id)
                                         else null end;
    if v_new.relation_target = 'entry'
       and not exists (select 1 from public.workspace_collections c
                        where c.id = v_new.relation_collection_id and c.project_id = v_old.project_id and c.trashed_at is null) then
      return jsonb_build_object('status', 'error', 'error', 'Target collection not found');
    end if;
    if (v_new.relation_target, v_new.relation_collection_id) is distinct from (v_old.relation_target, v_old.relation_collection_id)
       and exists (select 1 from public.object_references r where r.scene_property_id = p_property_id) then
      return jsonb_build_object('status', 'error', 'error', 'Clear its values before changing what it points to');
    end if;
  end if;

  -- Values first, then the definition, so every value is valid against the
  -- options it will have when the statement ends.
  v_ids := array(select o ->> 'id' from jsonb_array_elements(v_new.options) o);
  if v_old.type in ('select', 'status') then
    -- Removed options: those values are cleared.
    delete from public.scene_property_values v
     where v.property_id = v_old.id and not ((v.value #>> '{}') = any (v_ids));
    get diagnostics v_cleared = row_count;
  elsif v_old.type = 'multi_select' then
    with stripped as (
      select v.scene_id,
             coalesce((select jsonb_agg(x order by i) from jsonb_array_elements(v.value) with ordinality as t(x, i)
                        where (x #>> '{}') = any (v_ids)), '[]'::jsonb) as value
        from public.scene_property_values v
       where v.property_id = v_old.id
    ), changed as (
      select s.* from stripped s
        join public.scene_property_values v on v.scene_id = s.scene_id and v.property_id = v_old.id
       where s.value <> v.value
    ), emptied as (
      delete from public.scene_property_values v using changed c
       where v.property_id = v_old.id and v.scene_id = c.scene_id and c.value = '[]'::jsonb
      returning 1
    ), narrowed as (
      update public.scene_property_values v set value = c.value from changed c
       where v.property_id = v_old.id and v.scene_id = c.scene_id and c.value <> '[]'::jsonb
      returning 1
    )
    select (select count(*) from emptied) + (select count(*) from narrowed) into v_cleared;
  end if;

  update public.scene_property_definitions
     set name = v_new.name, type = v_new.type, options = v_new.options,
         relation_target = v_new.relation_target, relation_collection_id = v_new.relation_collection_id,
         relation_many = v_new.relation_many
   where id = v_old.id
  returning * into v_new;

  if v_old.type in ('select', 'status') and v_new.type = 'multi_select' then
    update public.scene_property_values v set value = jsonb_build_array(v.value) where v.property_id = v_old.id;
  end if;

  return jsonb_build_object('status', 'ok', 'property', to_jsonb(v_new), 'cleared', v_cleared);
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_scene_view(p_view_id uuid, p_changes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_old public.scene_views%rowtype;
  v_new public.scene_views%rowtype;
  v_key text;
begin
  select v.* into v_old
    from public.scene_views v
    join public.projects p on p.id = v.project_id
   where v.id = p_view_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'View not found');
  end if;
  perform public.lock_project_workspace(v_old.project_id);
  -- Re-read under the lock.
  select * into v_old from public.scene_views where id = p_view_id;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'View not found');
  end if;
  v_new := v_old;

  if jsonb_typeof(p_changes) is distinct from 'object' then
    return jsonb_build_object('status', 'error', 'error', 'Nothing to change');
  end if;
  for v_key in select jsonb_object_keys(p_changes) loop
    if v_key not in ('name', 'type', 'config') then
      return jsonb_build_object('status', 'error', 'error', format('Unknown change: %s', v_key));
    end if;
  end loop;

  if p_changes ? 'name' then
    if jsonb_typeof(p_changes -> 'name') is distinct from 'string' or btrim(p_changes ->> 'name') = '' then
      return jsonb_build_object('status', 'error', 'error', 'A view needs a name');
    end if;
    v_new.name := left(btrim(p_changes ->> 'name'), 100);
  end if;

  if p_changes ? 'type' then
    if (p_changes ->> 'type') is null or (p_changes ->> 'type') not in ('list', 'table', 'board', 'timeline') then
      return jsonb_build_object('status', 'error', 'error', 'Unknown view type');
    end if;
    v_new.type := p_changes ->> 'type';
  end if;

  if p_changes ? 'config' then
    if not public.workspace_view_config_shape_valid(p_changes -> 'config') then
      return jsonb_build_object('status', 'error', 'error', 'Invalid view configuration');
    end if;
    v_new.config := public.normalize_workspace_view_config(p_changes -> 'config');
    if v_new.config is distinct from public.prune_scene_view_config(v_old.manuscript_id, v_new.config) then
      return jsonb_build_object('status', 'error', 'error', 'Invalid view configuration');
    end if;
  end if;

  if v_new.type = 'board' and jsonb_typeof(v_new.config -> 'group_by') = 'null' then
    v_new.config := jsonb_set(v_new.config, '{group_by}',
      public.default_scene_view_config(v_old.manuscript_id, 'board') -> 'group_by');
  end if;
  if v_new.type = 'timeline' and jsonb_typeof(v_new.config -> 'axis') is distinct from 'string' then
    v_new.config := jsonb_set(v_new.config, '{axis}',
      public.default_scene_view_config(v_old.manuscript_id, 'timeline') -> 'axis');
  end if;

  update public.scene_views
     set name = v_new.name, type = v_new.type, config = v_new.config
   where id = v_old.id
  returning * into v_new;

  return jsonb_build_object('status', 'ok', 'view', to_jsonb(v_new));
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_workspace_collection_property(p_property_id uuid, p_changes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_old public.workspace_collection_properties%rowtype;
  v_new public.workspace_collection_properties%rowtype;
  v_key text;
  v_opt jsonb;
  v_options jsonb := '[]'::jsonb;
  v_ids text[];
  v_cleared integer := 0;
  v_n integer;
begin
  select pr.* into v_old
    from public.workspace_collection_properties pr
    join public.projects p on p.id = pr.project_id
   where pr.id = p_property_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Property not found');
  end if;
  perform public.lock_project_workspace(v_old.project_id);
  -- Re-read under the lock.
  select * into v_old from public.workspace_collection_properties where id = p_property_id;
  v_new := v_old;

  if jsonb_typeof(p_changes) is distinct from 'object' then
    return jsonb_build_object('status', 'error', 'error', 'Nothing to change');
  end if;
  for v_key in select jsonb_object_keys(p_changes) loop
    if v_key not in ('name', 'type', 'options', 'shown_in_list') then
      return jsonb_build_object('status', 'error', 'error', format('Unknown change: %s', v_key));
    end if;
  end loop;

  if p_changes ? 'name' then
    if jsonb_typeof(p_changes -> 'name') is distinct from 'string' or btrim(p_changes ->> 'name') = '' then
      return jsonb_build_object('status', 'error', 'error', 'A property needs a name');
    end if;
    v_new.name := left(btrim(p_changes ->> 'name'), 100);
    if exists (select 1 from public.workspace_collection_properties p
                where p.collection_id = v_old.collection_id and p.id <> v_old.id and lower(p.name) = lower(v_new.name)) then
      return jsonb_build_object('status', 'error', 'error', 'A property with this name already exists');
    end if;
  end if;

  if p_changes ? 'shown_in_list' then
    if jsonb_typeof(p_changes -> 'shown_in_list') is distinct from 'boolean' then
      return jsonb_build_object('status', 'error', 'error', 'shown_in_list must be true or false');
    end if;
    v_new.shown_in_list := (p_changes ->> 'shown_in_list')::boolean;
  end if;

  if p_changes ? 'type' then
    v_new.type := p_changes ->> 'type';
    -- Only where every value survives as it is (select ↔ status), or is
    -- wrapped losslessly (a single choice becomes a one-item multi-select).
    if v_new.type is distinct from v_old.type
       and not (v_old.type in ('select', 'status') and v_new.type in ('select', 'status', 'multi_select')) then
      return jsonb_build_object('status', 'error', 'error', 'This property’s type can’t be changed');
    end if;
  end if;

  if p_changes ? 'options' then
    if v_new.type not in ('select', 'multi_select', 'status') then
      return jsonb_build_object('status', 'error', 'error', 'Only a choice property has options');
    end if;
    if jsonb_typeof(p_changes -> 'options') is distinct from 'array' then
      return jsonb_build_object('status', 'error', 'error', 'Invalid property options');
    end if;
    -- An option keeps its id; one without an id is new and gets one here. An
    -- id the property never had is refused (a client can't invent a reference).
    for v_opt in select * from jsonb_array_elements(p_changes -> 'options') loop
      if jsonb_typeof(v_opt) <> 'object' then
        return jsonb_build_object('status', 'error', 'error', 'Invalid property options');
      end if;
      if v_opt ? 'id' and not exists (select 1 from jsonb_array_elements(v_old.options) o where o -> 'id' = v_opt -> 'id') then
        return jsonb_build_object('status', 'error', 'error', 'Unknown option');
      end if;
      v_options := v_options || jsonb_build_array(jsonb_build_object(
        'id', coalesce(v_opt ->> 'id', gen_random_uuid()::text),
        'name', left(btrim(coalesce(v_opt ->> 'name', '')), 100)));
    end loop;
    if not public.workspace_property_options_valid(v_options) then
      return jsonb_build_object('status', 'error', 'error', 'Each option needs a different name');
    end if;
    v_new.options := v_options;
  end if;

  -- Values first, then the definition, so every value is valid against the
  -- options it will have when the statement ends.
  v_ids := array(select o ->> 'id' from jsonb_array_elements(v_new.options) o);
  if v_old.type in ('select', 'status') then
    -- Removed options: those values are cleared.
    delete from public.workspace_entry_values v
     where v.property_id = v_old.id and not ((v.value #>> '{}') = any (v_ids));
    get diagnostics v_cleared = row_count;
  elsif v_old.type = 'multi_select' then
    with stripped as (
      select v.entry_id,
             coalesce((select jsonb_agg(x order by i) from jsonb_array_elements(v.value) with ordinality as t(x, i)
                        where (x #>> '{}') = any (v_ids)), '[]'::jsonb) as value
        from public.workspace_entry_values v
       where v.property_id = v_old.id
    ), changed as (
      select s.* from stripped s
        join public.workspace_entry_values v on v.entry_id = s.entry_id and v.property_id = v_old.id
       where s.value <> v.value
    ), emptied as (
      delete from public.workspace_entry_values v using changed c
       where v.property_id = v_old.id and v.entry_id = c.entry_id and c.value = '[]'::jsonb
      returning 1
    ), narrowed as (
      update public.workspace_entry_values v set value = c.value from changed c
       where v.property_id = v_old.id and v.entry_id = c.entry_id and c.value <> '[]'::jsonb
      returning 1
    )
    select (select count(*) from emptied) + (select count(*) from narrowed) into v_cleared;
  end if;

  update public.workspace_collection_properties
     set name = v_new.name, type = v_new.type, options = v_new.options, shown_in_list = v_new.shown_in_list
   where id = v_old.id
  returning * into v_new;

  if v_old.type in ('select', 'status') and v_new.type = 'multi_select' then
    update public.workspace_entry_values v set value = jsonb_build_array(v.value) where v.property_id = v_old.id;
    get diagnostics v_n = row_count;
  end if;

  return jsonb_build_object('status', 'ok', 'property', to_jsonb(v_new), 'cleared', v_cleared);
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_workspace_collection_view(p_view_id uuid, p_changes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_old public.workspace_collection_views%rowtype;
  v_new public.workspace_collection_views%rowtype;
  v_key text;
begin
  select v.* into v_old
    from public.workspace_collection_views v
    join public.projects p on p.id = v.project_id
   where v.id = p_view_id and p.user_id = auth.uid();
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'View not found');
  end if;
  perform public.lock_project_workspace(v_old.project_id);
  -- Re-read under the lock.
  select * into v_old from public.workspace_collection_views where id = p_view_id;
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'View not found');
  end if;
  v_new := v_old;

  if jsonb_typeof(p_changes) is distinct from 'object' then
    return jsonb_build_object('status', 'error', 'error', 'Nothing to change');
  end if;
  for v_key in select jsonb_object_keys(p_changes) loop
    if v_key not in ('name', 'type', 'config') then
      return jsonb_build_object('status', 'error', 'error', format('Unknown change: %s', v_key));
    end if;
  end loop;

  if p_changes ? 'name' then
    if jsonb_typeof(p_changes -> 'name') is distinct from 'string' or btrim(p_changes ->> 'name') = '' then
      return jsonb_build_object('status', 'error', 'error', 'A view needs a name');
    end if;
    v_new.name := left(btrim(p_changes ->> 'name'), 100);
  end if;

  if p_changes ? 'type' then
    if (p_changes ->> 'type') is null or (p_changes ->> 'type') not in ('list', 'table', 'board', 'timeline') then
      return jsonb_build_object('status', 'error', 'error', 'Unknown view type');
    end if;
    v_new.type := p_changes ->> 'type';
  end if;

  if p_changes ? 'config' then
    if not public.workspace_view_config_shape_valid(p_changes -> 'config') then
      return jsonb_build_object('status', 'error', 'error', 'Invalid view configuration');
    end if;
    v_new.config := public.normalize_workspace_view_config(p_changes -> 'config');
    if v_new.config is distinct from public.prune_workspace_view_config(v_old.collection_id, v_new.config) then
      return jsonb_build_object('status', 'error', 'error', 'Invalid view configuration');
    end if;
  end if;

  if v_new.type = 'board' and jsonb_typeof(v_new.config -> 'group_by') = 'null' then
    v_new.config := jsonb_set(v_new.config, '{group_by}',
      public.default_workspace_view_config(v_old.collection_id, 'board') -> 'group_by');
  end if;
  if v_new.type = 'timeline' and jsonb_typeof(v_new.config -> 'axis') is distinct from 'string' then
    v_new.config := jsonb_set(v_new.config, '{axis}',
      public.default_workspace_view_config(v_old.collection_id, 'timeline') -> 'axis');
  end if;

  update public.workspace_collection_views
     set name = v_new.name, type = v_new.type, config = v_new.config
   where id = v_old.id
  returning * into v_new;

  return jsonb_build_object('status', 'ok', 'view', to_jsonb(v_new));
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_workspace_relationship_property(p_property_id uuid, p_changes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_old public.workspace_collection_properties%rowtype;
  v_new public.workspace_collection_properties%rowtype;
  v_key text;
begin
  select pr.* into v_old
    from public.workspace_collection_properties pr
    join public.projects p on p.id = pr.project_id
   where pr.id = p_property_id and p.user_id = auth.uid() and pr.type = 'relationship';
  if not found then
    return jsonb_build_object('status', 'error', 'error', 'Property not found');
  end if;
  perform public.lock_project_workspace(v_old.project_id);
  select * into v_old from public.workspace_collection_properties where id = p_property_id;
  v_new := v_old;

  if jsonb_typeof(p_changes) is distinct from 'object' then
    return jsonb_build_object('status', 'error', 'error', 'Nothing to change');
  end if;
  for v_key in select jsonb_object_keys(p_changes) loop
    if v_key not in ('many', 'target', 'target_collection_id') then
      return jsonb_build_object('status', 'error', 'error', format('Unknown change: %s', v_key));
    end if;
  end loop;

  if p_changes ? 'many' then
    if jsonb_typeof(p_changes -> 'many') is distinct from 'boolean' then
      return jsonb_build_object('status', 'error', 'error', 'many must be true or false');
    end if;
    v_new.relation_many := (p_changes ->> 'many')::boolean;
    if not v_new.relation_many and exists (
         select 1 from public.object_references r where r.property_id = p_property_id
          group by r.source_entry_id having count(*) > 1) then
      return jsonb_build_object('status', 'error', 'error', 'Some entries hold more than one');
    end if;
  end if;

  if p_changes ? 'target' or p_changes ? 'target_collection_id' then
    v_new.relation_target := coalesce(p_changes ->> 'target', v_old.relation_target);
    v_new.relation_collection_id := case when v_new.relation_target = 'entry'
                                         then coalesce((p_changes ->> 'target_collection_id')::uuid, v_old.relation_collection_id)
                                         else null end;
    if v_new.relation_target not in ('entry', 'page', 'scene') then
      return jsonb_build_object('status', 'error', 'error', 'Unknown relationship target');
    end if;
    if v_new.relation_target = 'entry'
       and not exists (select 1 from public.workspace_collections c
                        where c.id = v_new.relation_collection_id and c.project_id = v_old.project_id) then
      return jsonb_build_object('status', 'error', 'error', 'Target collection not found');
    end if;
    if (v_new.relation_target, v_new.relation_collection_id) is distinct from (v_old.relation_target, v_old.relation_collection_id)
       and exists (select 1 from public.object_references r where r.property_id = p_property_id) then
      return jsonb_build_object('status', 'error', 'error', 'Clear its values before changing what it points to');
    end if;
  end if;

  update public.workspace_collection_properties
     set relation_target = v_new.relation_target,
         relation_collection_id = v_new.relation_collection_id,
         relation_many = v_new.relation_many
   where id = p_property_id
  returning * into v_new;
  return jsonb_build_object('status', 'ok', 'property', to_jsonb(v_new));
end;
$function$;

CREATE OR REPLACE FUNCTION public.workspace_object_active(p_type text, p_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select case p_type
    when 'page' then exists (select 1 from public.workspace_documents d where d.id = p_id and d.trashed_at is null)
    when 'folder' then exists (select 1 from public.workspace_folders f where f.id = p_id and f.trashed_at is null)
    when 'collection' then exists (select 1 from public.workspace_collections c where c.id = p_id and c.trashed_at is null)
    when 'entry' then exists (select 1 from public.workspace_collection_entries e
                                join public.workspace_collections c on c.id = e.collection_id
                               where e.id = p_id and e.trashed_at is null and c.trashed_at is null)
    when 'scene' then exists (select 1 from public.scenes s where s.id = p_id and s.trashed_at is null)
    when 'chapter' then exists (select 1 from public.chapters c where c.id = p_id and c.trashed_at is null)
    else false
  end;
$function$;

CREATE OR REPLACE FUNCTION public.workspace_property_options_valid(p_options jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select jsonb_typeof(p_options) = 'array'
     and jsonb_array_length(p_options) <= 200
     and not exists (
           select 1 from jsonb_array_elements(p_options) o
            where jsonb_typeof(o) <> 'object'
               or jsonb_typeof(o -> 'id') is distinct from 'string'
               or jsonb_typeof(o -> 'name') is distinct from 'string'
               or btrim(o ->> 'id') = '' or char_length(o ->> 'id') > 64
               or btrim(o ->> 'name') = '' or o ->> 'name' <> btrim(o ->> 'name')
               or char_length(o ->> 'name') > 100
               or exists (select 1 from jsonb_object_keys(o) k where k not in ('id', 'name')))
     and (select count(distinct o ->> 'id') = count(*) and count(distinct lower(o ->> 'name')) = count(*)
            from jsonb_array_elements(p_options) o);
$function$;

CREATE OR REPLACE FUNCTION public.workspace_property_value_valid(p_type text, p_options jsonb, p_value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_ids text[] := array(select o ->> 'id' from jsonb_array_elements(coalesce(p_options, '[]'::jsonb)) o);
begin
  case p_type
    when 'text' then
      return jsonb_typeof(p_value) = 'string' and btrim(p_value #>> '{}') <> '' and char_length(p_value #>> '{}') <= 2000;
    when 'number' then
      return jsonb_typeof(p_value) = 'number';
    when 'checkbox' then
      return p_value = 'true'::jsonb;
    when 'select', 'status' then
      return jsonb_typeof(p_value) = 'string' and (p_value #>> '{}') = any (v_ids);
    when 'multi_select' then
      return jsonb_typeof(p_value) = 'array'
         and jsonb_array_length(p_value) > 0
         and not exists (select 1 from jsonb_array_elements(p_value) v
                          where jsonb_typeof(v) <> 'string' or not ((v #>> '{}') = any (v_ids)))
         and (select count(distinct v) = count(*) from jsonb_array_elements(p_value) v);
    when 'date' then
      if jsonb_typeof(p_value) <> 'string' or (p_value #>> '{}') !~ '^\d{4}-\d{2}-\d{2}$' then
        return false;
      end if;
      begin
        return to_char((p_value #>> '{}')::date, 'YYYY-MM-DD') = (p_value #>> '{}');
      exception when others then
        return false;
      end;
    else
      return false;
  end case;
end;
$function$;

CREATE OR REPLACE FUNCTION public.workspace_trash_state(p_type text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_type is null or p_type not in ('page', 'folder', 'collection', 'entry', 'scene', 'chapter')
     or public.owned_workspace_object_project(p_type, p_id) is null then
    return jsonb_build_object('status', 'ok', 'state', 'missing');
  end if;
  return jsonb_build_object('status', 'ok', 'state',
    case when public.workspace_object_active(p_type, p_id) then 'active' else 'trashed' end);
end;
$function$;

CREATE OR REPLACE FUNCTION public.workspace_view_config_shape_valid(p_config jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select jsonb_typeof(p_config) = 'object'
     and not exists (select 1 from jsonb_object_keys(p_config) k where k not in ('properties', 'sort', 'filters', 'group_by', 'widths', 'axis'))
     -- properties: distinct strings
     and (not p_config ? 'properties' or (
           jsonb_typeof(p_config -> 'properties') = 'array'
       and jsonb_array_length(p_config -> 'properties') <= 200
       and not exists (select 1 from jsonb_array_elements(p_config -> 'properties') x where jsonb_typeof(x) <> 'string')
       and (select count(distinct x) = count(*) from jsonb_array_elements(p_config -> 'properties') x)))
     -- sort: null or { by, direction }
     and (not p_config ? 'sort' or jsonb_typeof(p_config -> 'sort') = 'null' or (
           jsonb_typeof(p_config -> 'sort') = 'object'
       and not exists (select 1 from jsonb_object_keys(p_config -> 'sort') k where k not in ('by', 'direction'))
       and jsonb_typeof(p_config -> 'sort' -> 'by') = 'string'
       and (p_config -> 'sort' ->> 'direction') in ('asc', 'desc')))
     -- filters: [{ property, op, value? }]
     and (not p_config ? 'filters' or (
           jsonb_typeof(p_config -> 'filters') = 'array'
       and jsonb_array_length(p_config -> 'filters') <= 20
       and not exists (
             select 1 from jsonb_array_elements(p_config -> 'filters') f
              where jsonb_typeof(f) <> 'object'
                 or exists (select 1 from jsonb_object_keys(f) k where k not in ('property', 'op', 'value'))
                 or jsonb_typeof(f -> 'property') is distinct from 'string'
                 or (f ->> 'op') is null
                 or (f ->> 'op') not in ('is', 'is_not', 'is_empty', 'is_not_empty', 'contains', 'gt', 'lt')
                 or ((f ->> 'op') in ('is', 'is_not', 'contains') and jsonb_typeof(f -> 'value') is distinct from 'string')
                 or ((f ->> 'op') in ('gt', 'lt') and coalesce(jsonb_typeof(f -> 'value'), '') not in ('number', 'string'))
                 or ((f ->> 'op') in ('is_empty', 'is_not_empty') and f ? 'value'))))
     -- group_by: null or a string
     and (not p_config ? 'group_by' or jsonb_typeof(p_config -> 'group_by') in ('null', 'string'))
     -- widths: { key: integer 80–640 }, at most 210 keys of at most 100 characters
     and (not p_config ? 'widths' or (
           jsonb_typeof(p_config -> 'widths') = 'object'
       and (select count(*) from jsonb_object_keys(p_config -> 'widths')) <= 210
       and not exists (
             select 1 from jsonb_each(p_config -> 'widths') w
              where char_length(w.key) > 100
                 or jsonb_typeof(w.value) <> 'number'
                 or (w.value #>> '{}')::numeric <> floor((w.value #>> '{}')::numeric)
                 or (w.value #>> '{}')::numeric not between 80 and 640)))
     -- axis: null or a string (a field id)
     and (not p_config ? 'axis' or jsonb_typeof(p_config -> 'axis') = 'null'
          or (jsonb_typeof(p_config -> 'axis') = 'string' and char_length(p_config ->> 'axis') between 1 and 100));
$function$;

