   FROM projects p
  WHERE ((p.id = object_references.project_id) AND (p.user_id = ( SELECT auth.uid() AS uid))))) AND workspace_object_active(source_type, COALESCE(source_entry_id, source_document_id, source_scene_id)) AND workspace_object_active(target_type, COALESCE(target_entry_id, target_document_id, target_scene_id, target_chapter_id))));

