create policy "revision_notes: select own" on public.revision_notes
  as permissive for select to authenticated
  using (((EXISTS ( SELECT 1
   FROM projects p
  WHERE ((p.id = revision_notes.project_id) AND (p.user_id = ( SELECT auth.uid() AS uid))))) AND
CASE target_type
    WHEN 'scene'::text THEN (EXISTS ( SELECT 1
       FROM scenes s
      WHERE ((s.id = revision_notes.scene_id) AND (s.trashed_at IS NULL))))
    WHEN 'chapter'::text THEN (EXISTS ( SELECT 1
       FROM chapters c
      WHERE ((c.id = revision_notes.chapter_id) AND (c.trashed_at IS NULL))))
    WHEN 'group'::text THEN (EXISTS ( SELECT 1
       FROM manuscript_groups g
      WHERE (g.id = revision_notes.group_id)))
    ELSE true
END));

