-- ── Triggers ────────────────────────────────────────────────────────────────
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION handle_new_user();
CREATE TRIGGER chapters_check_sibling_position AFTER INSERT OR UPDATE OF group_id, "position" ON chapters FOR EACH ROW EXECUTE FUNCTION check_structure_sibling_position();
CREATE TRIGGER chapters_forbid_manuscript_reassignment BEFORE UPDATE OF manuscript_id ON chapters FOR EACH ROW EXECUTE FUNCTION forbid_manuscript_reassignment();
CREATE TRIGGER chapters_protect_placement BEFORE UPDATE OF group_id, "position" ON chapters FOR EACH ROW EXECUTE FUNCTION protect_structure_placement();
CREATE TRIGGER manuscript_groups_check_sibling_position AFTER INSERT OR UPDATE OF parent_group_id, "position" ON manuscript_groups FOR EACH ROW EXECUTE FUNCTION check_structure_sibling_position();
CREATE TRIGGER manuscript_groups_forbid_cycle BEFORE INSERT OR UPDATE OF parent_group_id ON manuscript_groups FOR EACH ROW EXECUTE FUNCTION forbid_manuscript_group_cycle();
CREATE TRIGGER manuscript_groups_forbid_manuscript_reassignment BEFORE UPDATE OF manuscript_id ON manuscript_groups FOR EACH ROW EXECUTE FUNCTION forbid_manuscript_reassignment();
CREATE TRIGGER manuscript_groups_protect_placement BEFORE UPDATE OF parent_group_id, "position" ON manuscript_groups FOR EACH ROW EXECUTE FUNCTION protect_structure_placement();
CREATE TRIGGER object_references_check BEFORE INSERT OR UPDATE ON object_references FOR EACH ROW EXECUTE FUNCTION check_object_reference();
CREATE TRIGGER object_references_forbid_project_reassignment BEFORE UPDATE OF project_id ON object_references FOR EACH ROW EXECUTE FUNCTION forbid_project_reassignment();
CREATE TRIGGER object_references_guard_trash BEFORE INSERT ON object_references FOR EACH ROW EXECUTE FUNCTION guard_workspace_trash();
CREATE TRIGGER profiles_protect_billing_columns BEFORE UPDATE ON profiles FOR EACH ROW EXECUTE FUNCTION protect_billing_columns();
CREATE TRIGGER profiles_protect_is_admin BEFORE UPDATE ON profiles FOR EACH ROW EXECUTE FUNCTION protect_is_admin();
CREATE TRIGGER projects_protect_word_count BEFORE UPDATE OF word_count ON projects FOR EACH ROW EXECUTE FUNCTION protect_project_word_count();
CREATE TRIGGER trg_project_manuscript AFTER INSERT ON projects FOR EACH ROW EXECUTE FUNCTION create_project_manuscript();
CREATE TRIGGER revision_notes_check_target BEFORE INSERT OR UPDATE ON revision_notes FOR EACH ROW EXECUTE FUNCTION revision_notes_check_target();
CREATE TRIGGER scene_property_definitions_check BEFORE INSERT OR UPDATE ON scene_property_definitions FOR EACH ROW EXECUTE FUNCTION check_scene_property_definition();
CREATE TRIGGER scene_property_definitions_forbid_project_reassignment BEFORE UPDATE OF project_id ON scene_property_definitions FOR EACH ROW EXECUTE FUNCTION forbid_project_reassignment();
