CREATE TRIGGER scene_property_definitions_views_changed AFTER UPDATE OF type, options, relation_target, relation_collection_id ON scene_property_definitions FOR EACH ROW EXECUTE FUNCTION sync_scene_views_with_property();
CREATE TRIGGER scene_property_definitions_views_removed AFTER DELETE ON scene_property_definitions FOR EACH ROW EXECUTE FUNCTION sync_scene_views_with_property();
