CREATE TRIGGER scene_property_values_forbid_project_reassignment BEFORE UPDATE OF project_id ON scene_property_values FOR EACH ROW EXECUTE FUNCTION forbid_project_reassignment();
CREATE TRIGGER scene_views_check BEFORE INSERT OR UPDATE ON scene_views FOR EACH ROW EXECUTE FUNCTION check_scene_view();
CREATE TRIGGER scene_views_forbid_project_reassignment BEFORE UPDATE OF project_id ON scene_views FOR EACH ROW EXECUTE FUNCTION forbid_project_reassignment();
CREATE TRIGGER scene_version_trigger BEFORE UPDATE ON scenes FOR EACH ROW EXECUTE FUNCTION increment_scene_version();
CREATE TRIGGER scenes_detach_writing_sessions BEFORE DELETE ON scenes FOR EACH ROW EXECUTE FUNCTION detach_scene_writing_sessions();
CREATE TRIGGER scenes_fill_manuscript_id BEFORE INSERT ON scenes FOR EACH ROW EXECUTE FUNCTION fill_scene_manuscript_id();
CREATE TRIGGER scenes_forbid_manuscript_reassignment BEFORE UPDATE OF manuscript_id ON scenes FOR EACH ROW EXECUTE FUNCTION forbid_manuscript_reassignment();
CREATE TRIGGER scenes_forget_history BEFORE DELETE ON scenes FOR EACH ROW EXECUTE FUNCTION forget_scene_history();
