CREATE TRIGGER workspace_documents_inline_references_update AFTER UPDATE OF content ON workspace_documents FOR EACH ROW WHEN (old.content IS DISTINCT FROM new.content) EXECUTE FUNCTION sync_workspace_inline_references();
CREATE TRIGGER workspace_documents_place_new AFTER INSERT ON workspace_documents FOR EACH ROW EXECUTE FUNCTION place_new_workspace_object();
CREATE TRIGGER workspace_documents_stamp BEFORE INSERT OR UPDATE ON workspace_documents FOR EACH ROW EXECUTE FUNCTION stamp_workspace_document();
