insert into public.schema_migrations (version, name, applied_at, note) values
  ('000', 'production baseline 2026-09-24 (schema.sql)', null, 'Generated from the production catalog snapshot src/lib/supabase/catalog/production-2026-09-24.json. Fresh databases are built from schema.sql, then migrations 013+.'),
  ('001', '001_canonical_page.sql', null, 'historical — contained in the baseline; never re-run'),
  ('002', '002_word_goals.sql', null, 'historical — contained in the baseline; never re-run. Its unique(user_id, project_id, session_date) was later replaced in production by partial unique indexes.'),
  ('003', '003_chapter_completion.sql', null, 'historical — contained in the baseline; never re-run'),
  ('004', '004_billing.sql', null, 'historical — contained in the baseline; never re-run. Production subscription_events shape differs from this file.'),
  ('005', '005_game_tickets.sql', null, 'historical — contained in the baseline; never re-run'),
  ('006', '006_offline_sync.sql', null, 'historical — contained in the baseline; never re-run'),
  ('007', '007_fix_signup_trigger.sql', null, 'historical — SUPERSEDED by 009; re-running regresses handle_new_user'),
  ('008', '008_future_letters.sql', null, 'historical — contained in the baseline; never re-run'),
  ('009', '009_pricing_cohorts.sql', null, 'historical — contained in the baseline; never re-run (contains a one-time backfill)'),
  ('010', '010_analytics_excluded_users.sql', null, 'historical — contained in the baseline; never re-run'),
  ('011', '011_account_word_limit.sql', null, 'historical — contained in the baseline; never re-run'),
  ('012', '012_fix_bump_project_updated_at.sql', null, 'historical — contained in the baseline; never re-run'),
  ('013', '013_schema_migrations_ledger.sql', null, 'ledger created'),
  ('014', '014_assert_production_baseline.sql', null, 'baseline assertions passed: production-only columns, FK cascades, writing_sessions indexes, triggers, save-path RPC contracts, manuscript RLS policy set'),
  ('015', '015_rune2_manuscript_foundation.sql', null, 'Rune 2.0 manuscript foundation on an empty database: manuscripts, chapters.manuscript_id, scenes (replaces pages), writing_sessions.scene_id, Scene save RPCs, no canonical behavior'),
  ('016', '016_scene_structure_rpcs.sql', null, 'Rune 2.0 Scene structure: insert_unplaced_scene_checked (free-limit-checked Unplaced creation), reorder_chapter_scenes (atomic, validated Scene reorder)'),
  ('017', '017_atomic_scene_move.sql', null, 'Rune 2.0 atomic Scene move: move_scene (Chapter/Unplaced, one transaction under the per-account lock, recomputes the ordered total)'),
  ('018', '018_atomic_scene_creation.sql', null, 'Rune 2.0 atomic placed-Scene creation: insert_scene_checked validates the Chapter and appends under the per-account lock (p_position accepted, ignored)'),
  ('019', '019_creation_path_hardening.sql', null, 'Rune 2.0 creation hardening: create_chapter_checked (Chapter + first Scene atomically); Scene INSERT only through the SECURITY DEFINER creation RPCs; unique deferrable (chapter_id, position)'),
  ('020', '020_manuscript_totals.sql', null, 'Rune 2.0 manuscript totals: projects.word_count maintained by trigger (ordered placed-Scene total); Chapter INSERT only through the SECURITY DEFINER creation RPCs; unique deferrable (manuscript_id, position)'),
  ('021', '021_project_lifecycle_hardening.sql', null, 'Rune 2.0 project lifecycle: create_project_checked (Project + Manuscript + Chapter 1 + Scene 1 atomically, deduplicated by creation_request_id); no client INSERT on projects or write of projects.word_count; Chapter deletion (delete_chapter) moves its Scenes to Unplaced, FK no longer cascades'),
  ('022', '022_manuscript_groups.sql', null, 'Rune 2.0 Manuscript Groups (recursive, no prose) and one sibling ordering model for Groups + Chapters (create/delete/move RPCs, cycle-proof); unique Unplaced Scene order; deleting a Scene keeps its writing history (scene_id set null, merged into Project-level history)'),
  ('023', '023_workspace_pages.sql', null, 'Workspace Pages (workspace_documents): per-Project freeform documents, content-versioned, RLS by Project owner, no client DELETE'),
  ('024', '024_workspace_tree.sql', null, 'Workspace tree: workspace_folders + workspace_nodes (one canonical node per Page/Folder), atomic create/move/delete-empty-folder RPCs, top-level backfill of existing Pages'),
  ('025', '025_workspace_collections.sql', null, 'Workspace Collections + Entries: workspace_collections (one canonical node each), workspace_collection_entries (content-versioned, RLS by Project owner, no client DELETE), empty-only Collection deletion'),
  ('026', '026_collection_properties.sql', null, 'Collection Properties: workspace_collection_properties (typed definitions with owned options, ordered, list visibility) and workspace_entry_values (one checked value per Entry and property, same-Collection composite FKs); client read-only, writes through SECURITY DEFINER functions; property deletion requires the confirmed value count'),
  ('027', '027_collection_views.sql', null, 'Collection Views: workspace_collection_views (saved List/Table/Board configuration per Collection — shown properties, sort, filters, grouping — checked against the Collection''s own properties and pruned when they change); a default List per Collection (backfilled from shown_in_list); client read-only, writes through SECURITY DEFINER functions; the last View cannot be deleted'),
  ('028', '028_references.sql', null, 'References: object_references (canonical forward references between Entries, Pages and Scenes of one Project — generic, or one value of a Relationship property; typed FKs, cascade only on permanent deletion, backlinks derived by target); Relationship property type (relation_target, relation_collection_id, relation_many); client read-only, writes through SECURITY DEFINER functions'),
  ('029', '029_project_search.sql', null, 'Project Search: search_project_content (text inside the Project''s Scenes, Pages and Entries, with an excerpt; SECURITY INVOKER, owner-only, read-only) over rich_text_plain (the readable text of a rich-text document, derived on read, never stored); no table, row, policy or manuscript function changes'),
  ('030', '030_workspace_trash.sql', null, 'Workspace Trash: object-level soft deletion (trashed_at, and for tree objects where they came from) of Pages, Folders, Collections and Entries; a trashed tree object has no node; RLS shows active objects only, and references only while both ends are active; trash / restore / permanent delete / list / state RPCs; set_workspace_entry_value, set_workspace_entry_relationship and search_project_content respect Trash; no manuscript change'),
  ('031', '031_scene_trash.sql', null, 'Scene Trash: scenes.trashed_at + trashed_from_chapter_id (a trashed Scene is unplaced, keeps its position, version and updated_at, and holds no Unplaced slot); RLS shows active Scenes only; restore to its Chapter (old place if free, else the end) or to Unplaced when the Chapter is gone; permanent deletion keeps writing history; the Trash RPCs accept scene; account_word_total SECURITY DEFINER so the allowance still counts every Scene; duplicate_project_checked and search_project_content skip trashed Scenes'),
  ('032', '032_scene_properties_views.sql', null, 'Scene Properties and Scene Views: scene_property_definitions (typed, ordered, per Manuscript; Relationship to Entries, Pages or Scenes), scene_property_values (one checked value per Scene and property; never the Scene row), scene_views (saved List/Table/Board over the Manuscript''s Scenes; manuscript order by default; words and placement as read-only fields); Scene Relationship values are object_references rows (scene_property_id); one owner-agnostic prune_view_config for Collection and Scene Views, with contains / greater / less filters, Relationship filters and Relationship grouping; client read-only, writes through SECURITY DEFINER functions'),
  ('033', '033_manuscript_import.sql', null, 'Manuscript Import: import_manuscript_checked creates a new Project and its whole imported structure in one transaction'),
  ('034', '034_view_column_widths.sql', null, 'Table column widths saved per View: an optional widths key in Collection and Scene View configs (80–640 px), pruned with the fields it names'),
  ('035', '035_inline_references.sql', null, 'Inline references in Workspace rich text: object_references.origin (link | inline) and a Chapter target (target_chapter_id); a Page''s or Entry''s inline rows are derived from its content by an AFTER trigger on every content write (never failing the save), so mentions feed the one backlink system; add/remove_object_reference see links only'),
  ('036', '036_scene_history_milestones.sql', null, 'Scene History (scene_revisions: checkpoints taken on the save path by an AFTER UPDATE OF content trigger that never fails the save — the replaced text after a 30-minute pause or an hour after the last checkpoint; 30-day/daily/200 retention; restore_scene_revision saves through save_scene_checked after keeping the replaced text) and named Manuscript Milestones (manuscript_milestones + manuscript_milestone_scenes: Groups, Chapters and every active Scene''s placement and text, reusing unchanged revisions; read-only; no live row changes)'),
  ('037', '037_manuscript_workflow.sql', null, 'Chapter Trash (chapters.trashed_at/trashed_from_group_id/trashed_from_index, scenes.trashed_with_chapter: a Chapter goes to Trash and back with its Scenes; RLS shows active Chapters only; the sibling order covers active Chapters only); permanent Scene/Chapter deletion only through Trash (no client DELETE); delete_chapter SECURITY DEFINER; place_scene (atomic reorder/move of a Scene among a Chapter''s or the Unplaced Scenes); list_object_milestones; free_word_limit_for_caller returns null — Rune 2.0 has no free-word limit (signatures unchanged)'),
  ('038', '038_scene_revision_notes.sql', null, 'Scene revision notes (scene_revision_notes: one plain-text note per Scene, anchored by scene_id; follows moves, kept through Trash, deleted with the Scene; RLS: owner reads notes of active Scenes; written only by save_scene_revision_note, version-checked, never touching the Scene row)'),
  ('039', '039_revision_notes.sql', null, 'Revision Notes on Chapters and Scenes (revision_notes: many discrete plain-text notes, each on one Chapter or one Scene, anchored by id; hidden while the target is in Trash, deleted with it; written only by create/update/delete_revision_note, id-idempotent and version-checked, never touching Scene or Chapter rows). 038 notes copied as Scene notes; scene_revision_notes kept as scene_revision_notes_038 (no client access); save_scene_revision_note dropped'),
  ('040', '040_revision_note_scopes.sql', null, 'Revision Notes on the Manuscript and on Groups (revision_notes.group_id; target_type manuscript | group | chapter | scene); open project_notes items copied as Manuscript notes (same id, text and times; project_notes untouched); create_revision_note, revision_note_target_active, revision_notes_check_target and the select policy redefined; no existing note changes'),
  ('041', '041_project_backup_read.sql', null, 'read_project_backup(project, kind, after, limit): one STABLE SECURITY DEFINER owner-checked read of every row of one kind of the caller''s Project, Trash included, keyset-paged, for the on-device Whole-Project Backup; no table, policy, trigger, grant on a table or row changes'),
  ('042', '042_timeline_views.sql', null, 'Timeline Views: ''timeline'' joins the Collection and Scene View types; an optional axis key in the View config (a number or date property, or "manuscript" for a Scene View''s manuscript position), pruned with the fields it names; lanes are the existing group_by'),
  ('043', '043_revision_note_items.sql', null, 'Revision Note items: revision_notes.details, resolved_at and anchor (a Scene note''s passage — text, context, offsets, Scene version — best effort, never a mark in the prose; shape checked by the row trigger, never changed); revision_note_json returns them; create_revision_note_item and update_revision_note_item; create/update/delete_revision_note unchanged; no manuscript row, trigger or policy changes'),
  ('044', '044_scene_view_bases.sql', null, 'Scene Views owned per Base: scene_views.group_id (null = the Manuscript''s Base, else that Group''s; FK with its Manuscript, cascade on Group deletion), positions unique per Base; create_scene_view takes an optional group_id (the four-argument call is unchanged); move and delete work within the View''s Base; every existing View stays the Manuscript''s');
